  1→// Repo sync queue consumer and cron handler
  2→// Processes checkpoint sync messages for individual repos
  3→
  4→import { trace } from "@opentelemetry/api";
  5→import type { Env } from "../env";
  6→import { GitHubRateLimitError } from "./github";
  7→import {
  8→  queueRepoSyncBatch,
  9→  syncRepoCheckpoints,
 10→  type RepoSyncMessage,
 11→} from "./repo-sync-service";
 12→import { getDb } from "./db";
 13→import type { Db } from "./db/db-types";
 14→import { avgMs, errorString, generateBatchId, traced } from "./telemetry";
 15→import { getInstallationToken } from "./token";
 16→import { queueUserRepoSyncBatch } from "./user-repo-sync";
 17→
 18→export type { RepoSyncMessage } from "./repo-sync-service";
 19→
 20→// TTL for sync:lastUpdate KV entries (7 days)
 21→const SYNC_LAST_UPDATE_TTL = 60 * 60 * 24 * 7;
 22→
 23→// Log with consistent prefix
 24→function log(event: string, data: Record<string, unknown>): void {
 25→  console.log(`[repo-sync-queue] ${event}`, JSON.stringify(data));
 26→}
 27→
 28→// KV key for per-installation rate limit state
 29→function rateLimitKey(installationId: number): string {
 30→  return `github:ratelimit:installation:${installationId}:resetAt`;
 31→}
 32→
 33→// Check if a specific installation is currently rate limited
 34→async function isRateLimited(cache: KVNamespace, installationId: number): Promise<boolean> {
 35→  const key = rateLimitKey(installationId);
 36→  const resetAt = await cache.get(key);
 37→  if (!resetAt) return false;
 38→
 39→  const resetTime = parseInt(resetAt, 10);
 40→  if (Date.now() < resetTime) {
 41→    return true;
 42→  }
 43→
 44→  // Rate limit has expired, clean up
 45→  await cache.delete(key);
 46→  return false;
 47→}
 48→
 49→// Set rate limit marker for a specific installation (called when we hit a rate limit)
 50→async function setRateLimitMarker(
 51→  cache: KVNamespace,
 52→  installationId: number,
 53→  resetAt?: number,
 54→): Promise<void> {
 55→  // Default to 15 minutes from now if no reset time provided
 56→  const resetTime = resetAt ?? Date.now() + 15 * 60 * 1000;
 57→  // Store with TTL of 1 hour (self-cleaning)
 58→  await cache.put(rateLimitKey(installationId), String(resetTime), {
 59→    expirationTtl: 60 * 60,
 60→  });
 61→  log("rate_limit_set", { installationId, resetAt: new Date(resetTime).toISOString() });
 62→}
 63→
 64→// Notify users with access to a repo that data has been updated
 65→// This triggers frontend polling to detect the change and refresh
 66→// Note: This function never throws - errors are logged and swallowed
 67→// to avoid affecting the main sync flow (notification is best-effort)
 68→async function notifyUsersOfRepoUpdate(
 69→  db: Db,
 70→  cache: KVNamespace,
 71→  repoId: string
 72→): Promise<number> {
 73→  try {
 74→    // Get all users with access to this repo (reuse existing utility)
 75→    const userIds = await db.repos.getUsersForRepo(repoId);
 76→
 77→    if (userIds.length === 0) {
 78→      return 0;
 79→    }
 80→
 81→    // Update sync:lastUpdate for each user
 82→    const now = String(Date.now());
 83→    await Promise.all(
 84→      userIds.map((userId) =>
 85→        cache.put(`sync:lastUpdate:${userId}`, now, {
 86→          expirationTtl: SYNC_LAST_UPDATE_TTL,
 87→        })
 88→      )
 89→    );
 90→
 91→    return userIds.length;
 92→  } catch (err) {
 93→    log("notify_users_error", {
 94→      repoId,
 95→      error: errorString(err),
 96→    });
 97→    return 0;
 98→  }
 99→}
100→
101→// Type guard to check if a message is a RepoSyncMessage
102→export function isRepoSyncMessage(msg: unknown): msg is RepoSyncMessage {
103→  return (
104→    typeof msg === "object" &&
105→    msg !== null &&
106→    "repoId" in msg &&
107→    "reason" in msg &&
108→    "priority" in msg &&
109→    "queuedAt" in msg &&
110→    typeof (msg as RepoSyncMessage).repoId === "string" &&
111→    typeof (msg as RepoSyncMessage).reason === "string" &&
112→    typeof (msg as RepoSyncMessage).priority === "number"
113→  );
114→}
