533→export async function upsertCheckpointCommitBatch(
534→  db: Kysely<DB>,
535→  repoId: string,
536→  branch: string,
537→  commits: CommitWebhookData[],
538→): Promise<number> {
539→  if (commits.length === 0) return 0;
540→
541→  const deduped = deduplicateCheckpoints(commits);
542→  const now = new Date().toISOString();
543→  let successCount = 0;
544→
545→  for (let i = 0; i < deduped.length; i += BATCH_SIZE) {
546→    const batch = deduped.slice(i, i + BATCH_SIZE);
547→    const checkpointIds = batch.map((c) => c.checkpoint_id);
548→
549→    // 1. Batch fetch existing records for COALESCE logic
550→    const existingRecords = await db
551→      .selectFrom("repo_checkpoint_commits")
552→      .selectAll()
553→      .where("repo_id", "=", repoId)
554→      .where("branch", "=", branch)
555→      .where("checkpoint_id", "in", checkpointIds)
556→      .execute();
557→
558→    const existingMap = new Map(existingRecords.map((row) => [row.checkpoint_id, row]));
559→
560→    // 2. Build upsert rows with COALESCE logic
561→    for (const c of batch) {
562→      const existing = existingMap.get(c.checkpoint_id);
563→      const values = {
564→        id: existing?.id ?? generateId(),
565→        repo_id: repoId,
566→        checkpoint_id: c.checkpoint_id,
567→        branch,
568→        commit_sha: c.commit_sha ?? existing?.commit_sha ?? null,
569→        commit_message: c.commit_message ?? existing?.commit_message ?? null,
570→        commit_author: c.commit_author ?? existing?.commit_author ?? null,
571→        commit_author_username: c.commit_author_username ?? existing?.commit_author_username ?? null,
572→        commit_author_github_id: c.commit_author_github_id ?? existing?.commit_author_github_id ?? null,
573→        commit_date: c.commit_date ? new Date(c.commit_date) : existing?.commit_date ?? null,
574→        additions: c.additions ?? existing?.additions ?? 0,
575→        deletions: c.deletions ?? existing?.deletions ?? 0,
576→        files_changed: c.files_changed ?? existing?.files_changed ?? 0,
577→        file_stats: JSON.stringify(c.file_stats ?? existing?.file_stats ?? null) as unknown as string,
578→        synced_at: new Date(now),
579→      };
580→
581→      await db
582→        .insertInto("repo_checkpoint_commits")
583→        .values(values)
584→        .onDuplicateKeyUpdate({
585→          commit_sha: values.commit_sha,
586→          commit_message: values.commit_message,
587→          commit_author: values.commit_author,
588→          commit_author_username: values.commit_author_username,
589→          commit_author_github_id: values.commit_author_github_id,
590→          commit_date: values.commit_date,
591→          additions: values.additions,
592→          deletions: values.deletions,
593→          files_changed: values.files_changed,
594→          file_stats: values.file_stats,
595→          synced_at: values.synced_at,
596→        })
597→        .execute();
598→    }
599→
600→    successCount += batch.length;
601→  }
602→
603→  return successCount;
604→}
