643→export async function deleteOrphanedCheckpoints(
644→  db: Kysely<DB>,
645→  repoId: string,
646→): Promise<number> {
647→  // Get all checkpoint_ids that have commits
648→  const commitsData = await db
649→    .selectFrom("repo_checkpoint_commits")
650→    .select("checkpoint_id")
651→    .where("repo_id", "=", repoId)
652→    .execute();
653→
654→  const commitCheckpointIds = new Set(commitsData.map((c) => c.checkpoint_id));
655→
656→  // Get all checkpoints for this repo
657→  const checkpointsData = await db
658→    .selectFrom("repo_checkpoints")
659→    .select(["id", "checkpoint_id", "created_at"])
660→    .where("repo_id", "=", repoId)
661→    .execute();
662→
663→  // Grace period: don't delete checkpoints created in the last 5 minutes
664→  const gracePeriodMs = 5 * 60 * 1000;
665→  const cutoffTime = Date.now() - gracePeriodMs;
666→
667→  const orphanedIds = checkpointsData
668→    .filter((cp) => {
669→      if (commitCheckpointIds.has(cp.checkpoint_id)) return false;
670→      if (!cp.created_at) return true;
671→      return cp.created_at.getTime() < cutoffTime;
672→    })
673→    .map((cp) => cp.id);
674→
675→  if (orphanedIds.length === 0) return 0;
676→
677→  // Delete orphaned checkpoints in batches to avoid oversized IN lists.
678→  // Each batch re-checks via NOT IN subquery to avoid FK violations from race conditions.
679→  const BATCH_SIZE = 100;
680→  let totalDeleted = 0;
681→
682→  for (let i = 0; i < orphanedIds.length; i += BATCH_SIZE) {
683→    const batch = orphanedIds.slice(i, i + BATCH_SIZE);
684→    const result = await db
685→      .deleteFrom("repo_checkpoints")
686→      .where("id", "in", batch)
687→      .where("repo_id", "=", repoId)
688→      .where((eb) =>
689→        eb(
690→          "checkpoint_id",
691→          "not in",
692→          eb
693→            .selectFrom("repo_checkpoint_commits")
694→            .select("checkpoint_id")
695→            .where("repo_id", "=", repoId),
696→        ),
697→      )
698→      .executeTakeFirst();
699→
700→    totalDeleted += Number(result.numDeletedRows);
701→  }
702→
703→  return totalDeleted;
704→}
