729→/**
730→ * Returns the week index (0-51) for a commit date relative to currentWeekStart.
731→ * Week 51 = current week, week 0 = 51 weeks ago. Returns null if outside the 52-week window.
732→ * Week boundaries align to Sunday 00:00:00.
733→ */
734→export function commitDateToWeekIndex(commitDate: Date, currentWeekStart: Date): number | null {
735→  const weeksAgo = Math.ceil(
736→    (currentWeekStart.getTime() - commitDate.getTime()) / (7 * 24 * 60 * 60 * 1000),
737→  );
738→
739→  if (weeksAgo >= 0 && weeksAgo < 52) {
740→    return 51 - weeksAgo;
741→  }
742→  return null;
743→}
