763→      "cc.commit_date",
764→      "repos.full_name",
765→    ])
766→    .where("repos.is_fork", "=", 0)
767→    .where("cc.commit_date", ">=", fiftyTwoWeeksAgo)
768→    .where("cc.commit_date", "is not", null)
769→    .execute();
770→
771→  // Build repo map
772→  const repoMap = new Map<string, string>();
773→  for (const commit of commits) {
774→    if (commit.repo_id && !repoMap.has(commit.repo_id)) {
775→      repoMap.set(commit.repo_id, commit.full_name);
776→    }
777→  }
778→
779→  // Calculate the start of the current week (Sunday)
780→  const now = new Date();
781→  const currentWeekStart = new Date(now);
782→  currentWeekStart.setDate(now.getDate() - now.getDay());
783→  currentWeekStart.setHours(0, 0, 0, 0);
784→
785→  const oldestWeekStart = new Date(currentWeekStart);
786→  oldestWeekStart.setDate(oldestWeekStart.getDate() - 51 * 7);
787→  const weekStartTimestamp = Math.floor(oldestWeekStart.getTime() / 1000);
788→
789→  // Aggregate commits by repo and week, deduplicating by checkpoint_id
790→  const repoWeeks = new Map<string, number[]>();
791→  const seenCheckpoints = new Map<string, Set<string>>();
792→
793→  for (const commit of commits) {
794→    const repoFullName = repoMap.get(commit.repo_id ?? "");
795→    if (!repoFullName || !commit.commit_date) continue;
796→
797→    const commitDate = commit.commit_date instanceof Date
798→      ? commit.commit_date
799→      : new Date(commit.commit_date);
800→    const weekIndex = commitDateToWeekIndex(commitDate, currentWeekStart);
801→
802→    if (weekIndex !== null) {
803→      const dedupeKey = `${repoFullName}:${weekIndex}`;
804→
805→      if (!seenCheckpoints.has(dedupeKey)) {
806→        seenCheckpoints.set(dedupeKey, new Set());
807→      }
808→      const seen = seenCheckpoints.get(dedupeKey)!;
809→      if (seen.has(commit.checkpoint_id)) continue;
810→      seen.add(commit.checkpoint_id);
811→
812→      if (!repoWeeks.has(repoFullName)) {
813→        repoWeeks.set(repoFullName, new Array(52).fill(0));
814→      }
815→      repoWeeks.get(repoFullName)![weekIndex]++;
816→    }
817→  }
818→
819→  const activities: RepoCommitActivity[] = [];
820→  for (const [repoFullName, weeks] of repoWeeks) {
821→    activities.push({ repo_full_name: repoFullName, weeks, week_start: weekStartTimestamp });
822→  }
823→
824→  return activities;
825→}
