827→export async function getCheckpointsByUser(
828→  db: Kysely<DB>,
829→  userId: string,
830→  githubId: number,
831→  startDate: string,
832→  endDate: string,
833→  limit: number = 500,
834→): Promise<UserCheckpoint[]> {
835→  const commits = await db
836→    .selectFrom("repo_checkpoint_commits as cc")
837→    .innerJoin("repos", "repos.id", "cc.repo_id")
838→    .innerJoin("user_repos", (join) =>
839→      join
840→        .onRef("user_repos.repo_id", "=", "repos.id")
841→        .on("user_repos.user_id", "=", userId),
842→    )
843→    .leftJoin("repo_checkpoints as cp", (join) =>
844→      join
845→        .onRef("cp.repo_id", "=", "cc.repo_id")
846→        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
847→    )
848→    .select([
849→      "cc.checkpoint_id",
850→      "cc.branch",
851→      "cc.commit_sha",
852→      "cc.commit_message",
853→      "cc.commit_date",
854→      "cc.additions",
855→      "cc.deletions",
856→      "cc.files_changed",
857→      "cc.repo_id",
858→      "repos.full_name as repo_full_name",
859→      "repos.is_private",
860→      "cp.agent",
861→      "cp.steps",
862→      "cp.session_count",
863→      "cp.input_tokens",
864→      "cp.output_tokens",
865→    ])
866→    .where("cc.commit_author_github_id", "=", githubId)
867→    .where("cc.commit_date", ">=", new Date(startDate))
868→    .where("cc.commit_date", "<=", new Date(endDate))
869→    .orderBy("cc.commit_date", "desc")
870→    .limit(limit * 2) // Fetch extra to account for duplicates
871→    .execute();
872→
873→  if (commits.length === 0) return [];
874→
875→  // Deduplicate by (repo_id, checkpoint_id), preferring main branch
876→  const deduplicatedCommits = new Map<string, (typeof commits)[0]>();
877→
878→  for (const commit of commits) {
879→    const key = `${commit.repo_id}:${commit.checkpoint_id}`;
880→    const existing = deduplicatedCommits.get(key);
881→
882→    if (!existing) {
883→      deduplicatedCommits.set(key, commit);
884→    } else if (commit.branch === "main" && existing.branch !== "main") {
885→      deduplicatedCommits.set(key, commit);
886→    }
887→  }
888→
889→  return Array.from(deduplicatedCommits.values())
890→    .slice(0, limit)
891→    .map((commit) => ({
892→      checkpoint_id: commit.checkpoint_id,
893→      commit_sha: commit.commit_sha,
894→      commit_message: commit.commit_message,
895→      commit_date: dateToStr(commit.commit_date),
896→      additions: commit.additions ?? 0,
897→      deletions: commit.deletions ?? 0,
898→      files_changed: commit.files_changed ?? 0,
899→      repo_full_name: commit.repo_full_name ?? "",

 900→      branch: commit.branch,
 901→      is_private: toBool(commit.is_private),
 902→      agent: commit.agent ?? null,
 903→      steps: commit.steps ?? null,
 904→      session_count: commit.session_count ?? null,
 905→      input_tokens: commit.input_tokens ?? null,
 906→      output_tokens: commit.output_tokens ?? null,
 907→    }));
 908→}
