 940→export async function upsertSyncCheckpointBatch(
 941→  db: Kysely<DB>,
 942→  repoId: string,
 943→  checkpoints: CheckpointData[],
 944→): Promise<number> {
 945→  if (checkpoints.length === 0) return 0;
 946→
 947→  const uniqueCheckpoints = deduplicateCheckpoints(checkpoints);
 948→  const now = new Date().toISOString();
 949→  let successCount = 0;
 950→
 951→  for (let i = 0; i < uniqueCheckpoints.length; i += BATCH_SIZE) {
 952→    const batch = uniqueCheckpoints.slice(i, i + BATCH_SIZE);
 953→
 954→    // Fetch existing records for COALESCE behavior
 955→    let existingRecords;
 956→    try {
 957→      existingRecords = await db
 958→        .selectFrom("repo_checkpoints")
 959→        .selectAll()
 960→        .where("repo_id", "=", repoId)
 961→        .where("checkpoint_id", "in", batch.map((cp) => cp.checkpoint_id))
 962→        .execute();
 963→    } catch (e) {
 964→      syncLog("fetch_existing_checkpoints_error", { batch: i / BATCH_SIZE + 1, error: String(e) });
 965→      continue;
 966→    }
 967→
 968→    const existingMap = new Map(existingRecords.map((row) => [row.checkpoint_id, row]));
 969→
 970→    const safeJsonParse = (value: string | null | undefined, fallback: unknown): unknown => {
 971→      if (!value) return fallback;
 972→      try {
 973→        return JSON.parse(value);
 974→      } catch {
 975→        syncLog("json_parse_error", { value: value.substring(0, 100) });
 976→        return fallback;
 977→      }
 978→    };
 979→
 980→    for (const cp of batch) {
 981→      const existing = existingMap.get(cp.checkpoint_id);
 982→      const values = {
 983→        id: existing?.id ?? generateId(),
 984→        repo_id: repoId,
 985→        checkpoint_id: cp.checkpoint_id,
 986→        prompt: cp.prompt ?? existing?.prompt ?? null,
 987→        agent: cp.agent ?? existing?.agent ?? "Claude Code",
 988→        steps: cp.steps ?? existing?.steps ?? 1,
 989→        session_count: cp.session_count ?? existing?.session_count ?? 1,
 990→        strategy: cp.strategy ?? existing?.strategy ?? null,
 991→        branch: cp.branch ?? existing?.branch ?? null,
 992→        session_id: cp.session_id ?? existing?.session_id ?? null,
 993→        files_touched: JSON.stringify(safeJsonParse(cp.files_touched, existing?.files_touched ?? null)) as unknown as string,
 994→        session_ids: JSON.stringify(safeJsonParse(cp.session_ids, existing?.session_ids ?? null)) as unknown as string,
 995→        transcript_uuid_at_start: cp.transcript_uuid_at_start ?? existing?.transcript_uuid_at_start ?? null,
 996→        transcript_lines_at_start: cp.transcript_lines_at_start ?? existing?.transcript_lines_at_start ?? null,
 997→        checkpoint_transcript_start:
 998→          cp.checkpoint_transcript_start ??
 999→          existing?.checkpoint_transcript_start ??
1000→          cp.transcript_lines_at_start ??
1001→          existing?.transcript_lines_at_start ??
1002→          null,
1003→        input_tokens: cp.input_tokens ?? existing?.input_tokens ?? null,
1004→        cache_creation_tokens: cp.cache_creation_tokens ?? existing?.cache_creation_tokens ?? null,
1005→        cache_read_tokens: cp.cache_read_tokens ?? existing?.cache_read_tokens ?? null,
1006→        output_tokens: cp.output_tokens ?? existing?.output_tokens ?? null,
1007→        api_call_count: cp.api_call_count ?? existing?.api_call_count ?? null,
1008→        sessions: JSON.stringify(safeJsonParse(cp.sessions, existing?.sessions ?? null)) as unknown as string,
1009→        created_at: cp.created_at ? new Date(cp.created_at) : existing?.created_at ?? new Date(now),
1010→        synced_at: new Date(now),
1011→      };
1012→
1013→      try {
1014→        await db
1015→          .insertInto("repo_checkpoints")
1016→          .values(values)
1017→          .onDuplicateKeyUpdate({
1018→            prompt: values.prompt,
1019→            agent: values.agent,
1020→            steps: values.steps,
1021→            session_count: values.session_count,
1022→            strategy: values.strategy,
1023→            branch: values.branch,
1024→            session_id: values.session_id,
1025→            files_touched: values.files_touched,
1026→            session_ids: values.session_ids,
1027→            transcript_uuid_at_start: values.transcript_uuid_at_start,
1028→            transcript_lines_at_start: values.transcript_lines_at_start,
1029→            checkpoint_transcript_start: values.checkpoint_transcript_start,
1030→            input_tokens: values.input_tokens,
1031→            cache_creation_tokens: values.cache_creation_tokens,
1032→            cache_read_tokens: values.cache_read_tokens,
1033→            output_tokens: values.output_tokens,
1034→            api_call_count: values.api_call_count,
1035→            sessions: values.sessions,
1036→            created_at: values.created_at,
1037→            synced_at: values.synced_at,
1038→          })
1039→          .execute();
1040→        successCount++;
1041→      } catch (e) {
1042→        syncLog("upsert_checkpoint_error", { checkpoint_id: cp.checkpoint_id, error: String(e) });
1043→        continue;
1044→      }
1045→    }
1046→  }
1047→
1048→  return successCount;
1049→}
