1129→export async function updateRepoSyncState(
1130→  db: Kysely<DB>,
1131→  repoId: string,
1132→  options: {
1133→    cursor?: string;
1134→    backfilled?: boolean;
1135→    resetBackfill?: boolean;
1136→    error?: string;
1137→  },
1138→): Promise<void> {
1139→  const now = new Date();
1140→
1141→  if (options.error) {
1142→    await db
1143→      .updateTable("repos")
1144→      .set({
1145→        checkpoints_sync_error: options.error,
1146→        checkpoints_sync_error_at: now,
1147→        updated_at: now,
1148→      })
1149→      .where("id", "=", repoId)
1150→      .execute();
1151→    return;
1152→  }
1153→
1154→  const updates: Record<string, unknown> = {
1155→    checkpoints_last_synced_at: now,
1156→    checkpoints_sync_error: null,
1157→    checkpoints_sync_error_at: null,
1158→    updated_at: now,
1159→  };
1160→
1161→  if (options.cursor) {
1162→    updates.checkpoints_sync_cursor = options.cursor;
1163→  }
1164→
1165→  if (options.backfilled) {
1166→    updates.checkpoints_backfilled_at = now;
1167→  }
1168→
1169→  // Force a full re-backfill on the next sync (e.g., after force push)
1170→  if (options.resetBackfill) {
1171→    updates.checkpoints_backfilled_at = null;
1172→    updates.checkpoints_sync_cursor = null;
1173→  }
1174→
1175→  await db
1176→    .updateTable("repos")
1177→    .set(updates)
1178→    .where("id", "=", repoId)
1179→    .execute();
1180→}
