import { type Kysely } from "kysely";

/**
 * Helper: create an index, ignoring if it already exists.
 * Vitess doesn't support CREATE INDEX IF NOT EXISTS, so we catch the error.
 * MySQL error 1061 = "Duplicate key name".
 */
async function createIndexIfNotExists(
  db: Kysely<unknown>,
  indexName: string,
  table: string,
  columns: string[],
) {
  try {
    await db.schema
      .createIndex(indexName)
      .on(table)
      .columns(columns)
      .execute();
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : "";
    if (msg.includes("Duplicate key name") || msg.includes("already exists"))
      return;
    throw e;
  }
}

export async function up(db: Kysely<unknown>): Promise<void> {
  await createIndexIfNotExists(db, "idx_users_github_login", "users", ["github_login"]);
}

export async function down(db: Kysely<unknown>): Promise<void> {
  await db.schema.dropIndex("idx_users_github_login").on("users").execute();
}

