// Shared checkpoint types decoupled from the database backend.

import type { Json } from "../../types/database";
import type { Repo } from "./repos";

// --- Types ---

// Per-file stats for a commit
export interface FileStats {
  filename: string;
  status: "added" | "removed" | "modified" | "renamed" | "copied" | "changed" | "unchanged";
  additions: number;
  deletions: number;
  patch?: string | null;      // Unified diff for this file
  patchTruncated?: boolean;   // True if patch was truncated due to size limits
}

export interface RepoCheckpoint {
  id: string;
  repo_id: string;
  checkpoint_id: string;
  prompt: string | null;
  agent: string;
  steps: number;
  session_count: number;
  strategy: string | null;
  branch: string | null;
  session_id: string | null;
  files_touched: Json | null;
  session_ids: Json | null;
  transcript_uuid_at_start: string | null;
  transcript_lines_at_start: number | null;
  checkpoint_transcript_start: number | null;
  input_tokens: number | null;
  cache_creation_tokens: number | null;
  cache_read_tokens: number | null;
  output_tokens: number | null;
  api_call_count: number | null;
  attribution_agent_lines: number | null;
  attribution_human_added: number | null;
  attribution_human_modified: number | null;
  attribution_human_removed: number | null;
  attribution_total_committed: number | null;
  attribution_agent_percentage: number | null;
  attribution_calculated_at: string | null;
  sessions: Json | null;
  created_at: string | null;
  synced_at: string;
}

export interface RepoCheckpointCommit {
  id: string;
  repo_id: string;
  checkpoint_id: string;
  branch: string;
  commit_sha: string | null;
  commit_message: string | null;
  commit_author: string | null;
  commit_author_username: string | null;
  commit_author_github_id: number | null;
  commit_date: string | null;
  additions: number;
  deletions: number;
  files_changed: number;
  file_stats: Json | null;
  synced_at: string;
}

export interface CheckpointWithCommit {
  checkpoint_id: string;
  branch: string | null;
  prompt: string | null;
  agent: string;
  steps: number;
  session_count: number;
  strategy: string | null;
  created_at: string | null;
  commit_sha: string | null;
  commit_message: string | null;
  commit_author: string | null;
  commit_author_username: string | null;
  commit_date: string | null;
  additions: number;
  deletions: number;
  files_changed: number;
  files_touched: string[] | null;
  file_stats: FileStats[] | null;
  // Token usage
  input_tokens: number | null;
  cache_creation_tokens: number | null;
  cache_read_tokens: number | null;
  output_tokens: number | null;
  api_call_count: number | null;
  // Attribution metrics
  attribution_agent_lines: number | null;
  attribution_human_added: number | null;
  attribution_human_modified: number | null;
  attribution_human_removed: number | null;
  attribution_total_committed: number | null;
  attribution_agent_percentage: number | null;
  attribution_calculated_at: string | null;
}

// Result type for getRepoWithCheckpoints
export interface RepoWithCheckpointsResult {
  repo: Repo;
  checkpoints: CheckpointWithCommit[];
}

// Find a checkpoint by ID across all branches (for redirect when original branch is deleted)
// Returns the checkpoint data and list of branches it exists on
export interface CheckpointLocation {
  checkpoint_id: string;
  branches: string[];
  default_branch: string | null;  // If checkpoint exists on default branch
  commit: CheckpointWithCommit | null;  // Checkpoint data from preferred branch
}

// --- Webhook Data Types ---

export interface CheckpointWebhookData {
  checkpoint_id: string;
  prompt: string | null;
  agent: string | null;
  steps: number | null;
  session_count: number | null;
  strategy: string | null;
  created_at: string;
  branch: string | null;
  session_id: string | null;
  files_touched: string[] | null;
  session_ids: string[] | null;
  transcript_uuid_at_start: string | null;
  transcript_lines_at_start: number | null;
  checkpoint_transcript_start: number | null;
  input_tokens: number | null;
  cache_creation_tokens: number | null;
  cache_read_tokens: number | null;
  output_tokens: number | null;
  api_call_count: number | null;
  attribution_agent_lines: number | null;
  attribution_human_added: number | null;
  attribution_human_modified: number | null;
  attribution_human_removed: number | null;
  attribution_total_committed: number | null;
  attribution_agent_percentage: number | null;
  attribution_calculated_at: string | null;
  sessions: Json | null;
}

export interface CommitWebhookData {
  checkpoint_id: string;
  commit_sha: string;
  commit_message: string;
  commit_author: string;
  commit_author_username: string | null;
  commit_author_github_id: number | null;
  commit_date: string;
  additions: number;
  deletions: number;
  files_changed: number;
  file_stats: FileStats[] | null;
}

// --- User Checkpoints (for dashboard) ---

export interface UserCheckpoint {
  checkpoint_id: string;
  commit_sha: string | null;
  commit_message: string | null;
  commit_date: string | null;
  additions: number;
  deletions: number;
  files_changed: number;
  repo_full_name: string;
  branch: string;
  is_private: boolean;
  agent: string | null;
  steps: number | null;
  session_count: number | null;
  input_tokens: number | null;
  output_tokens: number | null;
}

// Activity data for a repo
export interface RepoCommitActivity {
  repo_full_name: string;
  weeks: number[];
  week_start?: number;
}

