// Shared database interface types decoupled from the database backend.

import type { User, CachedUser } from "../../types";
import type { RepoTrailInsert } from "../../types/database";
import type {
  Repo,
  RepoAccessResult,
  RepoWithUserData,
  WebhookRepoData,
  GitHubRepoData,
} from "./repos";
import type {
  CheckpointWithCommit,
  CheckpointLocation,
  RepoWithCheckpointsResult,
  CheckpointWebhookData,
  CommitWebhookData,
  UserCheckpoint,
  RepoCommitActivity,
} from "./checkpoints";
import type { CheckpointData, CommitData } from "./sync-types";
import type {
  RepoPullRequest,
  PullRequestWithRepo,
  WebhookPRData,
  GitHubPRData,
} from "./prs";
import type { AdminStats, AdminMutationResult } from "./admin";
import type { GitHubInstallationData } from "./installations";

// --- Installation type (shared shape used by both backends) ---

export interface Installation {
  id: string;
  github_installation_id: number;
  account_login: string;
  account_type: string;
  account_id: number;
  app_slug: string | null;
  suspended_at: string | null;
  repos_synced_at: string | null;
  created_at: string;
  updated_at: string;
}

// --- Top-level Db interface ---

export interface Db {
  users: UsersNamespace;
  repos: ReposNamespace;
  checkpoints: CheckpointsNamespace;
  prs: PrsNamespace;
  admin: AdminNamespace;
  installations: InstallationsNamespace;
  refreshState: RefreshStateNamespace;
  trails?: TrailsNamespace;
}

// --- Namespace interfaces ---

export interface UsersNamespace {
  findByGitHubId(githubId: number): Promise<User | null>;
  findById(id: string): Promise<User | null>;
  create(data: {
    github_id: number;
    github_login: string;
    github_token_enc: string | null;
    github_refresh_token_enc?: string | null;
    github_token_expires_at?: string | null;
  }): Promise<User>;
  update(id: string, data: Partial<Pick<User,
    | "github_login"
    | "github_token_enc"
    | "github_refresh_token_enc"
    | "github_token_expires_at"
    | "discovery_enabled"
  >>): Promise<void>;
  updateLastVisitedAt(userId: string): Promise<void>;
  getWithCache(kv: KVNamespace, userId: string): Promise<CachedUser | null>;
  findGitHubIdsByLogins(logins: string[]): Promise<Map<string, number>>;
}

export interface ReposNamespace {
  // Repo CRUD
  getById(repoId: string): Promise<Repo | null>;
  getByGithubId(githubId: number): Promise<Repo | null>;
  getByFullName(fullName: string): Promise<Repo | null>;
  getByFullNameWithAccess(fullName: string, userId: string): Promise<RepoAccessResult>;
  getPublicByFullName(fullName: string): Promise<Repo | null>;
  upsert(data: {
    github_id: number;
    full_name: string;
    name?: string;
    description?: string | null;
    html_url?: string;
    language?: string | null;
    stargazers_count?: number;
    is_fork?: boolean;
    is_private?: boolean;
    pushed_at?: string | null;
    default_branch?: string;
    app_has_access?: boolean;
    installation_id?: string | null;
  }): Promise<string>;
  upsertBatch(repos: Array<{
    github_id: number;
    full_name: string;
    app_has_access: boolean;
    installation_id?: string | null;
    default_branch?: string;
    is_private?: boolean;
  }>): Promise<string[]>;
  updateAppAccess(repoId: string, hasAccess: boolean): Promise<void>;
  updateAppAccessByFullName(fullName: string, hasAccess: boolean): Promise<void>;
  updateDefaultBranch(identifier: { id: string } | { fullName: string }, defaultBranch: string): Promise<void>;
  updateAppHasAccess(installationRepoIds: Set<number>): PromiseLike<{ error: { message: string } | null }>;
  updateFromWebhook(githubId: number, data: WebhookRepoData): Promise<number>;
  deleteByGithubId(githubId: number): Promise<number>;
  incrementActivity(githubId: number): Promise<number>;
  // Query
  getNeedingSync(staleThreshold: string, limit?: number): Promise<Array<{ id: string; full_name: string }>>;
  getWithUnsyncedCheckpoints(githubIds: number[]): Promise<Array<{ id: string; full_name: string }>>;
  getForReconciliation(options: {
    repoFullName?: string;
    repoIds?: string[];
    force?: boolean;
    staleThreshold: string;
  }): Promise<Array<{ id: string; full_name: string }>>;
  isCheckpointsSynced(repoId: string): Promise<boolean>;
  countPendingSync(userId: string): Promise<number | null>;
  // User-Repo
  getForUser(userId: string): Promise<RepoWithUserData[]>;
  addUserRepo(userId: string, repoId: string): Promise<void>;
  addUserReposBatch(userIds: string[], repoIds: string[]): Promise<void>;
  removeUserRepo(userId: string, repoId: string): Promise<void>;
  getUsersForRepo(repoId: string): Promise<string[]>;
  getUsersByRepoGithubId(githubId: number): Promise<string[]>;
  upsertForUser(userId: string, repos: GitHubRepoData[], installationRepoIds?: Set<number>, kv?: KVNamespace, repoToInstallationId?: Map<number, string>): Promise<void>;
  deleteStaleForUser(userId: string, currentGithubIds: number[]): Promise<void>;
}

export interface CheckpointsNamespace {
  // Query
  getForBranch(repoId: string, branch: string, options?: { limit?: number }): Promise<CheckpointWithCommit[]>;
  countForBranch(repoId: string, branch: string): Promise<number>;
  getByIds(repoId: string, checkpointIds: string[]): Promise<CheckpointWithCommit[]>;
  getRepoWithCheckpoints(repoFullName: string, userId: string, branch: string, limit?: number): Promise<RepoWithCheckpointsResult | null | 'no_access'>;
  getBranchesWithCheckpoints(repoId: string): Promise<Array<{ branch: string; checkpoint_count: number }>>;
  branchHasCommits(repoId: string, branch: string): Promise<boolean>;
  findById(repoId: string, checkpointId: string, defaultBranch?: string): Promise<CheckpointLocation | null>;
  getActivityForUser(userId: string): Promise<RepoCommitActivity[]>;
  getByUser(userId: string, githubId: number, startDate: string, endDate: string, limit?: number): Promise<UserCheckpoint[]>;
  // Mutations
  upsertBatch(repoId: string, checkpoints: CheckpointWebhookData[]): Promise<number>;
  upsertCommitBatch(repoId: string, branch: string, commits: CommitWebhookData[]): Promise<number>;
  deleteCommitsByBranch(repoId: string, branch: string): Promise<number>;
  deleteOrphaned(repoId: string): Promise<number>;
  deleteStaleCommitsForBranch(repoId: string, branch: string, validCheckpointIds: string[]): Promise<number>;
  recalculateCount(repoId: string): Promise<void>;
  // Sync
  getIdsWithCommits(repoId: string, checkpointIds: string[], branch?: string): Promise<Set<string>>;
  upsertSyncCheckpointBatch(repoId: string, checkpoints: CheckpointData[]): Promise<number>;
  upsertSyncCommitBatch(repoId: string, commits: CommitData[]): Promise<number>;
  updateSyncState(repoId: string, options: { cursor?: string; backfilled?: boolean; resetBackfill?: boolean; error?: string }): Promise<void>;
