      github_login: string;
      github_token_enc: string | null;
      github_refresh_token_enc: string | null;
      github_token_expires_at: string | null;
    };
    installations: Installation[];
  } | null>;
  syncForUser(userId: string, installations: GitHubInstallationData[]): Promise<{ added: number; removed: number; addedInstallationIds: number[] }>;
  userHasPersonal(userId: string, githubLogin: string): Promise<boolean>;
  existsByGitHubId(githubInstallationId: number): Promise<boolean>;
  findIdByGitHubId(githubInstallationId: number): Promise<string | null>;
  getGithubId(installationId: string): Promise<number | null>;
  getGithubIdByOwner(owner: string): Promise<number | null>;
}

