// Shared checkpoint types decoupled from the database backend.

import type { Json } from "../../types/database";
import type { Repo } from "./repos";

// --- Types ---

// Per-file stats for a commit
export interface FileStats {
  filename: string;
  status: "added" | "removed" | "modified" | "renamed" | "copied" | "changed" | "unchanged";
  additions: number;
  deletions: number;
  patch?: string | null;      // Unified diff for this file
  patchTruncated?: boolean;   // True if patch was truncated due to size limits
}

export interface RepoCheckpoint {
  id: string;
  repo_id: string;
  checkpoint_id: string;
  prompt: string | null;
  agent: string;
  steps: number;
  session_count: number;
  strategy: string | null;
  branch: string | null;
  session_id: string | null;
  files_touched: Json | null;
  session_ids: Json | null;
  transcript_uuid_at_start: string | null;
  transcript_lines_at_start: number | null;
  checkpoint_transcript_start: number | null;
  input_tokens: number | null;
  cache_creation_tokens: number | null;
  cache_read_tokens: number | null;
  output_tokens: number | null;
  api_call_count: number | null;
  attribution_agent_lines: number | null;
  attribution_human_added: number | null;
  attribution_human_modified: number | null;
  attribution_human_removed: number | null;
  attribution_total_committed: number | null;
  attribution_agent_percentage: number | null;
  attribution_calculated_at: string | null;
  sessions: Json | null;
  created_at: string | null;
  synced_at: string;
}

