}

// Result type for getRepoWithCheckpoints
export interface RepoWithCheckpointsResult {
  repo: Repo;
  checkpoints: CheckpointWithCommit[];
}

// Find a checkpoint by ID across all branches (for redirect when original branch is deleted)
// Returns the checkpoint data and list of branches it exists on
export interface CheckpointLocation {
  checkpoint_id: string;
