  input_tokens: number | null;
  cache_creation_tokens: number | null;
  cache_read_tokens: number | null;
  output_tokens: number | null;
  api_call_count: number | null;
  attribution_agent_lines: number | null;
  attribution_human_added: number | null;
  attribution_human_modified: number | null;
  attribution_human_removed: number | null;
  attribution_total_committed: number | null;
  attribution_agent_percentage: number | null;
  attribution_calculated_at: string | null;
  sessions: Json | null;
}

export interface CommitWebhookData {
  checkpoint_id: string;
  commit_sha: string;
  commit_message: string;
  commit_author: string;
  commit_author_username: string | null;
  commit_author_github_id: number | null;
  commit_date: string;
