 49→
 50→  const flushAssistant = () => {
 51→    if (pendingAssistantParts.length === 0) return;
 52→    const content = pendingAssistantParts.join("\n\n").trim();
 53→    if (content) {
 54→      result.push({
 55→        id: crypto.randomUUID(),
 56→        role: "assistant",
 57→        content,
 58→        timestamp: new Date().toISOString(),
 59→      });
 60→    }
 61→    pendingAssistantParts = [];
 62→  };
 63→
 64→  for (const line of lines) {
 65→    let parsed: Record<string, unknown>;
 66→    try {
 67→      parsed = JSON.parse(line);
 68→    } catch {
 69→      continue;
 70→    }
 71→
 72→    const role = parsed.role as string | undefined;
 73→    const message = parsed.message as Record<string, unknown> | undefined;
 74→    if (!role || !message?.content) continue;
 75→
 76→    const rawText = extractText(message.content);
 77→    if (!rawText.trim()) continue;
 78→
 79→    if (role === "user") {
 80→      flushAssistant();
 81→      const content = extractUserQuery(rawText);
 82→      if (content) {
 83→        result.push({
 84→          id: crypto.randomUUID(),
 85→          role: "user",
 86→          content,
 87→          timestamp: new Date().toISOString(),
 88→        });
 89→      }
 90→    } else if (role === "assistant") {
 91→      pendingAssistantParts.push(rawText.trim());
 92→    }
 93→  }
 94→
 95→  // Flush any remaining assistant content
 96→  flushAssistant();
 97→
 98→  return result;
 99→}
