  1→import type { TranscriptMessage, ToolCall } from "../../types";
  2→import type { TranscriptParser, TranscriptParseResult } from "./types";
  3→
  4→interface OpenCodePart {
  5→  type: string;
  6→  text?: string;
  7→  tool?: string;
  8→  state?: {
  9→    input?: unknown;
 10→    output?: string;
 11→    status?: string;
 12→    time?: { start?: number; end?: number };
 13→  };
 14→  time?: { start?: number; end?: number };
 15→}
 16→
 17→interface OpenCodeMessage {
 18→  info: {
 19→    role: "user" | "assistant";
 20→    time?: { created?: number; completed?: number };
 21→    id?: string;
 22→  };
 23→  parts: OpenCodePart[];
 24→}
 25→
 26→interface OpenCodeLog {
 27→  info?: {
 28→    time?: {
 29→      created?: number;
 30→    };
 31→  };
 32→  messages: OpenCodeMessage[];
 33→}
 34→
 35→function msToISO(ms: number | undefined, fallback: string): string {
 36→  return ms != null ? new Date(ms).toISOString() : fallback;
 37→}
 38→
 39→function parseOpenCodeTranscript(content: string): TranscriptMessage[] {
 40→  let log: OpenCodeLog;
 41→  try {
 42→    log = JSON.parse(content);
 43→  } catch {
 44→    return [];
 45→  }
 46→
 47→  if (!Array.isArray(log.messages)) return [];
 48→
 49→  const sessionCreated = msToISO(
 50→    log.info?.time?.created,
 51→    new Date().toISOString(),
 52→  );
 53→
 54→  const result: TranscriptMessage[] = [];
 55→
 56→  // Group consecutive assistant messages into a single turn
 57→  let i = 0;
 58→  while (i < log.messages.length) {
 59→    const msg = log.messages[i];
 60→    const role = msg.info?.role;
 61→
 62→    if (role === "user") {
 63→      const text = msg.parts
 64→        .filter((p) => p.type === "text")
 65→        .map((p) => p.text ?? "")
 66→        .join("\n")
 67→        .trim();
 68→
 69→      if (text) {
 70→        result.push({
 71→          id: msg.info.id ?? crypto.randomUUID(),
 72→          role: "user",
 73→          content: text,
 74→          timestamp: msToISO(msg.info.time?.created, sessionCreated),
 75→        });
 76→      }
 77→      i++;
 78→    } else if (role === "assistant") {
 79→      // Collect consecutive assistant messages as one turn
 80→      const toolCalls: ToolCall[] = [];
 81→      let assistantText = "";
 82→      const turnTimestamp = msToISO(msg.info.time?.created, sessionCreated);
 83→      let turnId = msg.info.id ?? crypto.randomUUID();
 84→
 85→      while (
 86→        i < log.messages.length &&
 87→        log.messages[i].info?.role === "assistant"
 88→      ) {
 89→        const assistantMsg = log.messages[i];
 90→        const msgTs = msToISO(
 91→          assistantMsg.info.time?.created,
 92→          sessionCreated,
 93→        );
 94→
 95→        // Use the last assistant message's id if it has one
 96→        if (assistantMsg.info.id) {
 97→          turnId = assistantMsg.info.id;
 98→        }
 99→
100→        for (const part of assistantMsg.parts) {
101→          if (part.type === "tool" && part.tool) {
102→            const toolTs = msToISO(part.state?.time?.start, msgTs);
103→            toolCalls.push({
104→              id: crypto.randomUUID(),
105→              name: part.tool,
106→              input: (part.state?.input as Record<string, unknown>) ?? {},
107→              timestamp: toolTs,
108→              result: part.state?.status
109→                ? {
110→                    type:
111→                      part.state.status === "error" ? "error" : "text",
112→                    output: part.state.output ?? "",
113→                    error:
114→                      part.state.status === "error"
115→                        ? part.state.output
116→                        : undefined,
117→                  }
118→                : undefined,
119→            });
120→          } else if (part.type === "text" && part.text) {
121→            // Last text part wins as the final assistant response
122→            assistantText = part.text;
123→          }
124→        }
125→        i++;
126→      }
127→
128→      result.push({
129→        id: turnId,
130→        role: "assistant",
131→        content: assistantText.trim(),
132→        timestamp: turnTimestamp,
133→        toolCalls,
134→      });
135→    } else {
136→      i++;
137→    }
138→  }
139→
140→  return result;
141→}
