143→/**
144→ * Parser for OpenCode session logs (single JSON with messages array).
145→ */
146→export class OpenCodeParser implements TranscriptParser {
147→  readonly name = "OpenCode";
148→
149→  parse(content: string): TranscriptParseResult {
150→    const messages = parseOpenCodeTranscript(content);
151→
152→    return {
153→      messages,
154→      isFallback: false,
155→    };
156→  }
157→}
