// Get checkpoints for a specific repo
// ALWAYS serves from D1 - background sync populates the data
// Pass ?source=github to trigger a sync from GitHub before returning data (for local dev)
repoRoutes.get("/:org/:repo/checkpoints", optionalAuth, rateLimitUnauthenticated, async (c) => {
  const userId = c.get("userId") as string | undefined;

  const org = c.req.param("org");
  const repo = c.req.param("repo");
  const repoFullName = `${org}/${repo}`;

  // Optional query params
  const branch = c.req.query("branch") || "main";
  const limitParam = c.req.query("limit");
  const limit = limitParam ? parseInt(limitParam, 10) : 100;
  const source = c.req.query("source"); // "github" to trigger sync

  // Validate branch name format to prevent cache key issues and unexpected behavior
  if (!isValidBranchName(branch)) {
    return c.json({ error: "Invalid branch name format" }, 400);
  }

  try {
    const db = getDb(c.env);
    let repoRecord: Repo | null = null;

    // Helper to get GitHub token only when needed (for source=github or branch validation)
    // Uses undefined as "not yet fetched" so null can be cached as "fetched, no token"
    let cachedToken: string | null | undefined = undefined;
    const getGitHubToken = async (): Promise<string | null> => {
      if (cachedToken !== undefined) return cachedToken;
      const tokenResult = await getGitHubTokenForRepoRequest(c, db, userId, repoRecord);
      if (tokenResult.response) {
        const err = new Error("User not found");
        (err as any).status = 404;
        throw err;
      }
      cachedToken = tokenResult.token;
      return tokenResult.token;
    };

    // For source=github (local dev), use multi-query path since we may need to create/sync.
    // For normal requests, resolve repo access first, then fetch branch checkpoints separately.
    // This avoids false 404s when a repo exists but has zero checkpoints on the branch.
    let dbCheckpoints: CheckpointWithCommit[] = [];

    if (source === "github" && isLocalDev(c.env)) {
      // Local dev path: requires auth (webhooks don't fire in local dev)
      if (!userId) return c.json({ error: "Authentication required" }, 401);

      // Also invalidate branches cache since webhooks don't fire in local dev
      await c.env.ENTIRE_CACHE.delete(`branches:${repoFullName}`);
      console.log(`source=github: invalidated branches cache for ${repoFullName}`);

      const result = await fetchRepoWithSyncForLocalDev(
        db,
        repoFullName,
        userId,
        branch,
        limit,
        getGitHubToken,
      );
      if (result instanceof Response) return result;
      repoRecord = result.repoRecord;
      dbCheckpoints = result.checkpoints;
    } else {
      const repoAccess = await checkRepoAccess(
        db,
        repoFullName,
        userId,
        { requireRepo: true },
      );
      if (repoAccess instanceof Response) return repoAccess;

      repoRecord = repoAccess;
      dbCheckpoints = await db.checkpoints.getForBranch(repoRecord.id, branch, { limit });
    }

    // null = unknown (repo not in DB), true/false = definitive from DB
    const appHasAccess = repoRecord ? repoRecord.app_has_access : null;

    // Validate branch existence when we have no checkpoints
    // This catches non-existent branches even if repo hasn't been synced yet
    if (dbCheckpoints.length === 0) {
      // If repo exists in DB, check if it has any commits for this branch
      const hasCommitsInDb = repoRecord
        ? await db.checkpoints.branchHasCommits(repoRecord.id, branch)
        : false;

      if (!hasCommitsInDb) {
        // If app doesn't have access, skip branch check and show "no access" state
        // (User's token might also not have access, giving false 404s)
        if (appHasAccess !== false) {
          // No commits in DB - verify with GitHub API (only fetches token if needed)
          const token = await getGitHubToken();
          const branchExists = await checkBranchExists(
            repoFullName,
            branch,
            token,
          );

          // If GitHub definitively says branch doesn't exist, return 404
          if (branchExists === false) {
            return c.json({ error: `Branch '${branch}' not found` }, 404);
          }
          // If branchExists is true or null, continue - let component show appropriate empty state
        }
        // If appHasAccess === false, skip branch check and return empty checkpoints
      }
    }

    // Build response from DB data
    const checkpoints: CheckpointInfo[] = dbCheckpoints.map(mapCheckpointToInfo);

    // session_branch_exists is true if repo has been backfilled (branch was checked during sync)
    // null if we haven't checked yet (repo not synced)
    const sessionBranchExists = repoRecord?.checkpoints_backfilled_at
      ? true
      : null;

    return c.json({
      checkpoints,
      repo_full_name: repoFullName,
      updated_at: new Date().toISOString(),
      source: "db",
      app_has_access: appHasAccess,
      session_branch_exists: sessionBranchExists,
    });
  } catch (err) {
    if ((err as any)?.status === 404) {
      return c.json({ error: (err as Error).message }, 404);
    }
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error(`Failed to fetch checkpoints for ${repoFullName}:`, err);
    recordSpanError(err);
    return c.json({ error: "Failed to fetch checkpoints" }, 500);
  }
});

