      token = result.token;
    }

    if (!token) {
      return c.json({ error: "GitHub token required" }, 401);
    }

    // Fetch collaborators from GitHub
    const response = await fetch(
      `https://api.github.com/repos/${repoFullName}/collaborators?per_page=100`,
      {
        headers: {
