// Repo-level checkpoint sync service
// Syncs checkpoints for a single repository (shared across all users)
// Uses CHECKPOINT_BRANCH as source of truth for checkpoint discovery

import {
  checkBranchExists,
  discoverCheckpointsFromBranch,
  fetchCommitStatsBatch,
  fetchSessionDataBatch,
  parseSquashCommitTitles,
  GitHubRateLimitError,
  discoverTrailsFromBranch,
  fetchTrailDataBatch,
} from "./github";
import { CHECKPOINT_BRANCH, TRAILS_BRANCH } from "./constants";
import { getValidGitHubToken } from "./token";
import type { Db } from "./db/db-types";
import type { Json, RepoTrailInsert } from "../types/database";
import type { Trail } from "../types";
import { errorString } from "./telemetry";

const LOG_PREFIX = "[repo-sync]";

// Log with consistent prefix
function log(event: string, data: Record<string, unknown>): void {
  console.log(`${LOG_PREFIX} ${event}`, JSON.stringify(data));
}

// Queue message for repo checkpoint sync
export interface RepoSyncMessage {
  repoId: string;
  reason: "installation" | "reconciliation" | "manual" | "user_sync";
  priority: number; // 10 = immediate (installation, user_sync), 5 = manual, 1 = reconciliation
  queuedAt: string;
}

// Result of syncing a repo
export interface RepoSyncResult {
  status: "ok" | "skipped" | "error";
  reason?: string;
  checkpointsDiscovered?: number;
  checkpointsWithCommits?: number;
  isBackfill?: boolean;
  discoveredCheckpointIds?: string[];
}

// Re-export shared types and dedup functions for backward compatibility
export type { CheckpointData, CommitData } from "./db/sync-types";
export { deduplicateCheckpoints, deduplicateCommits } from "./db/sync-types";
import type { CheckpointData, CommitData } from "./db/sync-types";

// Sync checkpoints for a single repo
// Called by queue consumer
export async function syncRepoCheckpoints(
  db: Db,
  repoId: string,
  token: string,
  options: { fullBackfill?: boolean; skipAppInstallationCheck?: boolean; extraBranches?: string[] } = {}
): Promise<RepoSyncResult> {
  const repoData = await db.repos.getById(repoId);

  if (!repoData) {
    return { status: "skipped", reason: "repo_not_found" };
  }

  // Apply defaults for fields that may be null in the database
  const repo = {
    ...repoData,
    default_branch: repoData.default_branch ?? "main",
    app_has_access: repoData.app_has_access ?? false,
  };

  // Skip app installation check when explicitly requested (e.g., local dev "Fetch from GitHub" button)
  // In local dev, webhooks don't fire so app_has_access is never set
  if (!repo.app_has_access && !options.skipAppInstallationCheck) {
    return { status: "skipped", reason: "no_app_access" };
  }

  // Check if CHECKPOINT_BRANCH exists (quick "is this repo Entire-enabled?" check)
  const branchExists = await checkBranchExists(repo.full_name, CHECKPOINT_BRANCH, token);
  if (branchExists === null) {
    return { status: "skipped", reason: "branch_check_error" };
  }
  if (branchExists === false) {
    await db.checkpoints.updateSyncState(repoId, {});
    return { status: "skipped", reason: "no_sessions_branch" };
  }

  const isBackfill = !repo.checkpoints_backfilled_at || options.fullBackfill;
  const since = isBackfill ? undefined : (repo.checkpoints_sync_cursor ?? undefined);

  log("sync_started", {
    repoId,
    fullName: repo.full_name,
    isBackfill,
    since,
  });

  try {
    // Step 1: Discover checkpoints from default branch via Entire-Checkpoint trailers
    const discovered = await discoverCheckpointsFromBranch(
      repo.full_name,
      repo.default_branch,
      token,
      since
    );

    // Track which branch each checkpoint was discovered on (for commit data)
    const discoveredBranch = new Map<string, string>();
    for (const d of discovered) {
      discoveredBranch.set(d.checkpointId, repo.default_branch);
    }

    // Also scan extra branches (e.g., local dev where webhooks don't fire)
    // No `since` filter — cursor is from the default branch and doesn't apply here
    const extraBranches = (options.extraBranches ?? []).filter(
      (b) => b !== repo.default_branch
    );
    for (const branch of extraBranches) {
      const branchDiscovered = await discoverCheckpointsFromBranch(
        repo.full_name,
        branch,
        token
      );
      log("extra_branch_scan", {
        repoId,
        branch,
        found: branchDiscovered.length,
        alreadyKnown: branchDiscovered.filter((d) => discoveredBranch.has(d.checkpointId)).length,
      });
      for (const d of branchDiscovered) {
        if (!discoveredBranch.has(d.checkpointId)) {
          discovered.push(d);
          discoveredBranch.set(d.checkpointId, branch);
        }
      }
    }

    if (discovered.length === 0) {
      await db.checkpoints.updateSyncState(repoId, {});
      if (isBackfill) {
        await db.checkpoints.updateSyncState(repoId, { backfilled: true });
      }
      log("sync_complete_no_checkpoints", { repoId, fullName: repo.full_name });
      return { status: "ok", checkpointsDiscovered: 0, isBackfill };
    }

    const checkpointIds = discovered.map((d) => d.checkpointId);
    // Cursor: latest commit date from the default branch only
    // Extra branches may have different dates that shouldn't affect the default branch cursor
    const defaultBranchDiscovered = discovered.filter(
      (d) => discoveredBranch.get(d.checkpointId) === repo.default_branch
    );
    const latestCursor = defaultBranchDiscovered[0]?.commit.date;

    log("checkpoints_discovered", {
      repoId,
      fullName: repo.full_name,
      count: checkpointIds.length,
    });

    // Step 2: Fetch session metadata from CHECKPOINT_BRANCH tree
    const sessionDataResult = await fetchSessionDataBatch(repo.full_name, checkpointIds, token);

    if (sessionDataResult.failedItems.length > 0) {
      log("session_data_partial_failure", {
        repoId,
        failed: sessionDataResult.failedItems.length,
      });
    }

    // Step 3: Upsert checkpoint metadata (before commits due to FK constraint)
    const checkpointData: CheckpointData[] = checkpointIds.map((cpId) => {
      const session = sessionDataResult.data.get(cpId);
      return {
        checkpoint_id: cpId,
        prompt: session?.prompt ?? null,
        agent: session?.agent ?? null,
        steps: session?.steps ?? null,
        session_count: session?.sessionCount ?? null,
        strategy: session?.strategy ?? null,
        branch: session?.branch ?? null,
        session_id: session?.sessionId ?? null,
        files_touched: session?.filesTouched ? JSON.stringify(session.filesTouched) : null,
        session_ids: session?.sessionIds ? JSON.stringify(session.sessionIds) : null,
        transcript_uuid_at_start: session?.transcriptUuidAtStart ?? null,
        transcript_lines_at_start: session?.transcriptLinesAtStart ?? null,
        checkpoint_transcript_start: session?.checkpointTranscriptStart ?? null,
        input_tokens: session?.inputTokens ?? null,
        cache_creation_tokens: session?.cacheCreationTokens ?? null,
        cache_read_tokens: session?.cacheReadTokens ?? null,
        output_tokens: session?.outputTokens ?? null,
        api_call_count: session?.apiCallCount ?? null,
        sessions: session?.sessions ? JSON.stringify(session.sessions) : null,
        created_at: session?.createdAt ?? new Date().toISOString(),
      };
    });

    await db.checkpoints.upsertSyncCheckpointBatch(repoId, checkpointData);

    // Step 4: Upsert commit data (commit info already available from discovery)
    // For non-backfill, skip checkpoints that already have commits on their respective branch
    let discoveredToProcess = discovered;

    if (!isBackfill) {
      // Group checkpoints by branch to check per-branch commit existence
      const checkpointsByBranch = new Map<string, string[]>();
      for (const d of discovered) {
        const branch = discoveredBranch.get(d.checkpointId) ?? repo.default_branch;
        const existing = checkpointsByBranch.get(branch) ?? [];
        existing.push(d.checkpointId);
        checkpointsByBranch.set(branch, existing);
      }

      // Check which checkpoints already have commits on their respective branch
      const existingWithCommitsOnBranch = new Set<string>();
      for (const [branch, cpIds] of checkpointsByBranch) {
        const existingOnBranch = await db.checkpoints.getIdsWithCommits(repoId, cpIds, branch);
        for (const cpId of existingOnBranch) {
          existingWithCommitsOnBranch.add(cpId);
        }
      }

      if (existingWithCommitsOnBranch.size > 0) {
        discoveredToProcess = discovered.filter(
          (d) => !existingWithCommitsOnBranch.has(d.checkpointId)
        );

        log("reconciliation_optimization", {
          repoId,
          totalCheckpoints: checkpointIds.length,
          alreadyHaveCommits: existingWithCommitsOnBranch.size,
          needToProcess: discoveredToProcess.length,
        });
      }
    }

    let commitsFound = 0;

    if (discoveredToProcess.length > 0) {
      // Fetch commit stats for new checkpoints
      const shas = discoveredToProcess.map((d) => d.commit.sha);
      const statsResult = await fetchCommitStatsBatch(repo.full_name, shas, token);

      // Parse squash commit titles for each unique commit message
      const squashTitlesByMessage = new Map<string, Map<string, string>>();
      for (const d of discoveredToProcess) {
        if (!squashTitlesByMessage.has(d.commit.message)) {
          squashTitlesByMessage.set(d.commit.message, parseSquashCommitTitles(d.commit.message));
        }
      }

      const commitData: CommitData[] = discoveredToProcess.map((d) => {
        const stats = statsResult.data.get(d.commit.sha);
        const squashTitles = squashTitlesByMessage.get(d.commit.message);
        const commitTitle = squashTitles?.get(d.checkpointId) ?? d.commit.message.split("\n")[0];
        return {
          checkpoint_id: d.checkpointId,
          branch: discoveredBranch.get(d.checkpointId) ?? repo.default_branch,
          commit_sha: d.commit.sha,
          commit_message: commitTitle,
          commit_author: d.commit.author,
          commit_author_username: d.commit.authorUsername ?? null,
          commit_author_github_id: d.commit.authorId ?? null,
          commit_date: d.commit.date,
          additions: stats?.additions ?? 0,
          deletions: stats?.deletions ?? 0,
          files_changed: stats?.filesChanged ?? 0,
          file_stats: stats?.files ?? null,
        };
      });

      commitsFound = await db.checkpoints.upsertSyncCommitBatch(repoId, commitData);

      log("commits_processed", {
        repoId,
        branch: repo.default_branch,
        commitsFound,
      });
    }

    // Step 5: Reconcile stale checkpoint commits (backfill only)
    // During a full backfill we have the complete picture of what's on each branch,
    // so we can safely remove checkpoint commits that are no longer reachable
    // (e.g., after force pushes that rewrote history).
    let staleDeleted = 0;
    if (isBackfill) {
      // Group discovered checkpoint IDs by branch
      const validByBranch = new Map<string, string[]>();
      for (const d of discovered) {
        const branch = discoveredBranch.get(d.checkpointId) ?? repo.default_branch;
        const existing = validByBranch.get(branch) ?? [];
        existing.push(d.checkpointId);
        validByBranch.set(branch, existing);
      }

      // Reconcile each branch we scanned
      const branchesToReconcile = new Set([repo.default_branch, ...extraBranches]);
      for (const branch of branchesToReconcile) {
        const validIds = validByBranch.get(branch) ?? [];
        const deleted = await db.checkpoints.deleteStaleCommitsForBranch(repoId, branch, validIds);
        staleDeleted += deleted;
      }

      if (staleDeleted > 0) {
        await db.checkpoints.deleteOrphaned(repoId);
        log("stale_commits_reconciled", { repoId, staleDeleted });
      }
    }

    // Step 6: Update sync state
    await db.checkpoints.updateSyncState(repoId, {
      cursor: latestCursor,
      backfilled: isBackfill,
    });

    // Step 6: Recalculate checkpoint count
    await db.checkpoints.recalculateCount(repoId);

    const totalSessions = checkpointData.reduce((sum, cp) => sum + (cp.session_count ?? 0), 0);
    const checkpointsWithSessions = checkpointData.filter((cp) => cp.sessions != null).length;

    log("sync_complete", {
      repoId,
      fullName: repo.full_name,
      checkpointsDiscovered: checkpointIds.length,
      checkpointsWithCommits: commitsFound,
      totalSessions,
      checkpointsWithSessions,
      isBackfill,
    });

    return {
      status: "ok",
      checkpointsDiscovered: checkpointIds.length,
      checkpointsWithCommits: commitsFound,
      isBackfill,
    };
  } catch (err) {
    if (err instanceof GitHubRateLimitError) {
      throw err;
    }

    const errorMessage = errorString(err);
    await db.checkpoints.updateSyncState(repoId, { error: errorMessage });

    log("sync_error", {
      repoId,
      fullName: repo.full_name,
      error: errorMessage,
    });

    return { status: "error", reason: errorMessage };
  }
}

// Cloudflare Queue sendBatch limits
const QUEUE_BATCH_MAX_MESSAGES = 100;

// Queue multiple repos for checkpoint sync using sendBatch
// Respects Cloudflare Queue limits: max 100 messages per batch
export async function queueRepoSyncBatch(
  queue: Queue<RepoSyncMessage>,
  repos: { id: string }[],
  reason: RepoSyncMessage["reason"],
  priority: number = 5
): Promise<number> {
  if (repos.length === 0) return 0;

  const queuedAt = new Date().toISOString();
  let totalQueued = 0;

  // Process in batches of 100 (Cloudflare Queue limit)
  for (let i = 0; i < repos.length; i += QUEUE_BATCH_MAX_MESSAGES) {
    const batch = repos.slice(i, i + QUEUE_BATCH_MAX_MESSAGES);
    const messages = batch.map((repo) => ({
      body: {
        repoId: repo.id,
        reason,
        priority,
        queuedAt,
      },
    }));

    await queue.sendBatch(messages);
    totalQueued += batch.length;
  }

  log("repos_queued_batch", { count: totalQueued, reason, priority, batches: Math.ceil(repos.length / QUEUE_BATCH_MAX_MESSAGES) });
  return totalQueued;
}

// Environment required for user-level checkpoint sync
export interface CheckpointSyncEnv {
  db: Db;
  cache: KVNamespace;
  clientId: string;
  clientSecret: string;
  encryptionKey: string;
}

// Result of syncing checkpoints for a user
export interface UserCheckpointSyncResult {
  reposChecked: number;
  reposWithAccess: number;
  reposSynced: number;
  errors: number;
}

// Sync checkpoints for all repos a user has access to
// This is the repo-centric replacement for the legacy syncCheckpointsForUser
export async function syncCheckpointsForUser(
  userId: string,
  env: CheckpointSyncEnv
): Promise<UserCheckpointSyncResult> {
  const result: UserCheckpointSyncResult = {
    reposChecked: 0,
    reposWithAccess: 0,
    reposSynced: 0,
    errors: 0,
  };

  // Get user and their token
  const user = await env.db.users.findById(userId);

  if (!user || !user.github_token_enc) {
    log("skip_no_token", { userId });
    return result;
  }

  // Get valid token
  let token: string;
  try {
    const tokenResult = await getValidGitHubToken(env.db, user, {
      clientId: env.clientId,
      clientSecret: env.clientSecret,
      encryptionKey: env.encryptionKey,
    }, env.cache);
    token = tokenResult.token;
  } catch (err) {
    log("token_error", { userId, error: errorString(err) });
    return result;
  }

  // Get all repos for this user from the repo-centric schema
  const repos = await env.db.repos.getForUser(userId);
  result.reposChecked = repos.length;

  log("user_sync_started", {
    userId,
    totalRepos: repos.length,
  });

  // Filter to repos where app has access
  const accessibleRepos = repos.filter((r) => r.app_has_access);
  result.reposWithAccess = accessibleRepos.length;

  // Process repos in batches to avoid rate limits
  const BATCH_SIZE = 5;
  for (let i = 0; i < accessibleRepos.length; i += BATCH_SIZE) {
    const batch = accessibleRepos.slice(i, i + BATCH_SIZE);

    await Promise.all(
      batch.map(async (repo) => {
        try {
          const syncResult = await syncRepoCheckpoints(env.db, repo.id, token);
          if (syncResult.status === "ok") {
            result.reposSynced++;
          }
        } catch (err) {
          result.errors++;
          log("repo_sync_error", {
            repoId: repo.id,
            fullName: repo.full_name,
            error: errorString(err),
          });
        }
      })
    );
  }

  log("user_sync_completed", { userId, ...result });
  return result;
}

// ============================================================================
// Trail sync functions
// ============================================================================

export interface TrailSyncResult {
  status: "ok" | "skipped" | "error";
  reason?: string;
  trailsDiscovered?: number;
  trailsSynced?: number;
}

/**
 * Sync trails for a repository
 * Discovers trails from entire/trails/v1 branch and upserts to database
 */
export async function syncRepoTrails(
  db: Db,
  repoId: string,
  repoFullName: string,
  token: string,
): Promise<TrailSyncResult> {
  log("trails_sync_start", { repoId, repoFullName });

  // Check if trails branch exists
  const branchExists = await checkBranchExists(repoFullName, TRAILS_BRANCH, token);
  if (!branchExists) {
    log("trails_sync_skip", { repoId, reason: "no_trails_branch" });
    return { status: "skipped", reason: "no_trails_branch" };
  }

  // Discover all trail IDs
  const trailIds = await discoverTrailsFromBranch(repoFullName, token);
  if (trailIds.length === 0) {
    log("trails_sync_skip", { repoId, reason: "no_trails" });
    return { status: "skipped", reason: "no_trails" };
  }

  log("trails_discovered", { repoId, count: trailIds.length });

  // Fetch trail data in batches
  const trailData = await fetchTrailDataBatch(repoFullName, trailIds, token);

  // Upsert trails to database
  let synced = 0;
  for (const [trailId, trail] of trailData) {
    try {
      await upsertTrail(db, repoId, trail);
      synced++;
    } catch (err) {
      log("trail_upsert_error", {
        repoId,
        trailId,
        error: errorString(err),
      });
    }
  }

  log("trails_sync_completed", {
    repoId,
    discovered: trailIds.length,
    synced,
  });

  return {
    status: "ok",
    trailsDiscovered: trailIds.length,
    trailsSynced: synced,
  };
}

/**
 * Upsert a trail to the database.
 * Uses the optional trails namespace (available on Supabase, not yet on PlanetScale).
 */
async function upsertTrail(
  db: Db,
  repoId: string,
  trail: Trail,
): Promise<void> {
  if (!db.trails) {
    // PlanetScale doesn't have repo_trails table yet - skip DB sync
    return;
  }

  const { metadata, discussion } = trail;

  // Calculate comment counts
  let commentCount = 0;
  let unresolvedCount = 0;
  for (const comment of discussion.comments ?? []) {
    commentCount += 1 + (comment.replies?.length ?? 0);
    if (!comment.resolved) {
      unresolvedCount++;
    }
  }

  const row: RepoTrailInsert = {
    repo_id: repoId,
    trail_id: metadata.trail_id,
    branch: metadata.branch,
    base: metadata.base,
    title: metadata.title,
    body: metadata.body || null,
    status: metadata.status,
    author: metadata.author,
    assignees: metadata.assignees,
    labels: metadata.labels,
    created_at: metadata.created_at,
    updated_at: metadata.updated_at,
    merged_at: metadata.merged_at,
    discussion: discussion as unknown as Json,
    comment_count: commentCount,
    unresolved_count: unresolvedCount,
  };

  await db.trails.upsert(row);
}

