  1→// Search index queue consumer
  2→// Processes checkpoint indexing messages for Turbopuffer vector search
  3→
  4→import type { Env } from "../env";
  5→import { getDb } from "./db";
  6→import type { Db } from "./db/db-types";
  7→import { indexCheckpoints } from "./turbopuffer";
  8→import { avgMs, generateBatchId } from "./telemetry";
  9→import { getInstallationToken } from "./token";
 10→import { fetchFileAtCommit } from "./github";
 11→import { getParserForAgent } from "./transcript-parsers/registry";
 12→import { CHECKPOINT_BRANCH } from "./constants";
 13→import { stripTranscript } from "./strip-transcript";
 14→
 15→const MAX_TRANSCRIPT_CHARS = 200_000;
 16→const TRANSCRIPT_CONCURRENCY = 10;
 17→
 18→// Queue message sent after checkpoint data is upserted into PlanetScale
 19→export interface SearchIndexMessage {
 20→  repoId: string;
 21→  checkpointIds: string[];
 22→  queuedAt: string;
 23→}
 24→
 25→// Type guard to check if a message is a SearchIndexMessage
 26→export function isSearchIndexMessage(
 27→  msg: unknown,
 28→): msg is SearchIndexMessage {
 29→  return (
 30→    typeof msg === "object" &&
 31→    msg !== null &&
 32→    "repoId" in msg &&
 33→    "checkpointIds" in msg &&
 34→    "queuedAt" in msg &&
 35→    typeof (msg as SearchIndexMessage).repoId === "string" &&
 36→    Array.isArray((msg as SearchIndexMessage).checkpointIds)
 37→  );
 38→}
 39→
 40→// Log with consistent prefix
 41→function log(event: string, data: Record<string, unknown>): void {
 42→  console.log(`[search-index-queue] ${event}`, JSON.stringify(data));
 43→}
 44→
 45→// Fetch transcript from GitHub, strip it, and return the stripped JSONL
 46→// Returns a per-session map: { "0": "stripped jsonl...", "1": "..." }
 47→async function fetchAndStripTranscript(
 48→  repoFullName: string,
 49→  checkpointId: string,
 50→  sessionCount: number,
 51→  token: string,
 52→): Promise<Record<string, string> | null> {
 53→  try {
 54→    const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
 55→    const sessions: Record<string, string> = {};
 56→    const count = Math.max(sessionCount, 1);
 57→
 58→    for (let i = 0; i < count; i++) {
 59→      const path = `${folder}/${i}/full.jsonl`;
 60→      const content = await fetchFileAtCommit(repoFullName, path, CHECKPOINT_BRANCH, token);
 61→      if (content) {
 62→        sessions[String(i)] = stripTranscript(content);
 63→      }
 64→    }
 65→
 66→    return Object.keys(sessions).length > 0 ? sessions : null;
 67→  } catch {
 68→    return null;
 69→  }
 70→}
 71→
 72→// Parse stripped transcript JSONL into a searchable text excerpt
 73→function parseTranscriptExcerpt(
 74→  strippedJsonl: string,
 75→  agent: string,
 76→): string | null {
 77→  try {
 78→    const parser = getParserForAgent(agent);
 79→    const result = parser.parse(strippedJsonl);
 80→    if (result.messages.length === 0) return null;
 81→
 82→    const parts: string[] = [];
 83→    let charsUsed = 0;
 84→
 85→    for (const msg of result.messages) {
 86→      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;
 87→      if (msg.role === "assistant" && msg.toolCalls?.length && !msg.content.trim()) continue;
 88→
 89→      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
 90→      const text = msg.content.slice(0, remaining);
 91→      parts.push(`[${msg.role}]: ${text}`);
 92→      charsUsed += text.length;
 93→    }
 94→
 95→    return parts.join("\n") || null;
 96→  } catch {
 97→    return null;
 98→  }
 99→}
100→
101→// Ensure transcripts are stored in DB, fetching from GitHub if needed.
102→// Returns a map of checkpoint_id → searchable transcript text.
103→async function ensureTranscriptsStored(
104→  db: Db,
105→  repoId: string,
106→  repoFullName: string,
107→  installationId: string | null,
108→  checkpoints: Array<{ checkpoint_id: string; agent: string; session_count: number }>,
109→  env: Env,
110→  batchId: string,
111→): Promise<Map<string, string | null>> {
112→  const transcripts = new Map<string, string | null>();
113→
114→  // Check which checkpoints already have transcripts in DB
115→  const dbResults = new Map<string, Record<string, string> | null>();
116→  const missingIds: string[] = [];
117→
118→  for (const cp of checkpoints) {
119→    const row = await db.checkpoints.getTranscript(repoId, cp.checkpoint_id);
120→    if (row?.transcript_stripped) {
121→      try {
122→        const parsed = JSON.parse(row.transcript_stripped) as Record<string, string>;
123→        dbResults.set(cp.checkpoint_id, parsed);
124→      } catch {
125→        missingIds.push(cp.checkpoint_id);
126→      }
127→    } else {
128→      missingIds.push(cp.checkpoint_id);
129→    }
130→  }
131→
132→  if (dbResults.size > 0) {
133→    log("transcripts_from_db", { batchId, repoId, count: dbResults.size });
134→  }
135→
136→  // Parse DB transcripts into searchable text
137→  for (const cp of checkpoints) {
138→    const sessions = dbResults.get(cp.checkpoint_id);
139→    if (sessions) {
140→      // Use session 0 for search indexing (primary session)
141→      const primaryJsonl = sessions["0"];
142→      if (primaryJsonl) {
143→        transcripts.set(cp.checkpoint_id, parseTranscriptExcerpt(primaryJsonl, cp.agent));
144→      }
145→    }
146→  }
147→
148→  // Fetch missing transcripts from GitHub
149→  if (missingIds.length > 0 && installationId) {
150→    try {
151→      const token = await getInstallationToken(
152→        Number(installationId),
153→        { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
154→        env.ENTIRE_CACHE,
155→      );
156→
157→      const missingCheckpoints = checkpoints.filter((cp) => missingIds.includes(cp.checkpoint_id));
158→      const dbUpdates: Array<{ checkpoint_id: string; transcript_stripped: string }> = [];
159→
160→      // Fetch in parallel with concurrency limit
161→      for (let i = 0; i < missingCheckpoints.length; i += TRANSCRIPT_CONCURRENCY) {
162→        const batch = missingCheckpoints.slice(i, i + TRANSCRIPT_CONCURRENCY);
163→        const results = await Promise.all(
164→          batch.map((cp) =>
165→            fetchAndStripTranscript(repoFullName, cp.checkpoint_id, cp.session_count, token),
166→          ),
167→        );
168→
169→        for (let j = 0; j < results.length; j++) {
170→          const cp = batch[j];
171→          const sessions = results[j];
172→          if (sessions) {
173→            dbUpdates.push({
174→              checkpoint_id: cp.checkpoint_id,
175→              transcript_stripped: JSON.stringify(sessions),
176→            });
177→
178→            // Parse for search indexing
179→            const primaryJsonl = sessions["0"];
180→            if (primaryJsonl) {
181→              transcripts.set(cp.checkpoint_id, parseTranscriptExcerpt(primaryJsonl, cp.agent));
182→            }
183→          }
184→        }
185→      }
186→
187→      // Store stripped transcripts in DB
188→      if (dbUpdates.length > 0) {
189→        const stored = await db.checkpoints.updateTranscriptBatch(repoId, dbUpdates);
190→        log("transcripts_stored", { batchId, repoId, stored, attempted: dbUpdates.length });
191→      }
192→    } catch (err) {
193→      log("transcript_fetch_error", {
194→        batchId,
195→        repoId,
196→        error: err instanceof Error ? err.message : String(err),
197→      });
198→      // Continue without transcripts — prompt/commit/files still get indexed
199→    }
200→  }
201→
202→  return transcripts;
203→}
204→
205→// Process a batch of search index messages
206→export async function processSearchIndexBatch(
207→  batch: MessageBatch<SearchIndexMessage>,
208→  env: Env,
209→): Promise<void> {
210→  const batchStartTime = Date.now();
211→  const batchId = generateBatchId();
212→
213→  const queueWaitTimes = batch.messages.map(
214→    (msg) => Date.now() - msg.timestamp.getTime(),
215→  );
216→  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;
217→
218→  log("batch_started", {
219→    batchId,
220→    queue: batch.queue,
221→    count: batch.messages.length,
222→    avgQueueWaitMs: avgMs(queueWaitTimes),
223→    maxQueueWaitMs: maxWaitMs,
224→  });
225→
226→  const processingTimes: number[] = [];
227→  let successCount = 0;
228→  let errorCount = 0;
229→  let skippedCount = 0;
230→
231→  for (const msg of batch.messages) {
232→    const msgStartTime = Date.now();
233→    const { repoId, checkpointIds } = msg.body;
234→
235→    // Early return if API keys are missing — don't retry messages that can never succeed
236→    if (!env.TURBOPUFFER_API_KEY || !env.OPENAI_API_KEY) {
237→      log("skip_missing_api_keys", {
238→        batchId,
239→        repoId,
240→        hasTurbopuffer: !!env.TURBOPUFFER_API_KEY,
241→        hasOpenai: !!env.OPENAI_API_KEY,
242→      });
243→      msg.ack();
244→      skippedCount++;
245→      continue;
246→    }
247→
248→    try {
249→      const db = getDb(env);
250→
251→      const repo = await db.repos.getById(repoId);
252→      if (!repo) {
253→        log("skip_repo_not_found", { batchId, repoId });
254→        msg.ack();
255→        skippedCount++;
256→        continue;
257→      }
258→
259→      const checkpoints = await db.checkpoints.getByIds(repoId, checkpointIds);
260→
261→      if (checkpoints.length === 0) {
262→        log("skip_no_checkpoints", { batchId, repoId, requestedIds: checkpointIds.length });
263→        msg.ack();
264→        skippedCount++;
265→        continue;
266→      }
267→
268→      // Ensure transcripts are stored in DB, fetching from GitHub if needed
269→      const transcripts = await ensureTranscriptsStored(
270→        db,
271→        repoId,
272→        repo.full_name,
273→        repo.installation_id,
274→        checkpoints.map((cp) => ({
275→          checkpoint_id: cp.checkpoint_id,
276→          agent: cp.agent ?? "Claude Code",
277→          session_count: cp.session_count ?? 1,
278→        })),
279→        env,
280→        batchId,
281→      );
282→
283→      const indexed = await indexCheckpoints(
284→        env.TURBOPUFFER_API_KEY,
285→        env.OPENAI_API_KEY,
286→        repo.github_id,
287→        checkpoints.map((cp) => ({
288→          checkpoint_id: cp.checkpoint_id,
289→          branch: cp.branch,
290→          agent: cp.agent,
291→          commit_author_username: cp.commit_author_username,
292→          created_at: cp.created_at,
293→          commit_sha: cp.commit_sha,
294→          commit_message: cp.commit_message,
295→          prompt: cp.prompt,
296→          files_touched: cp.files_touched,
297→          transcript: transcripts.get(cp.checkpoint_id) ?? null,
298→        })),
299→      );
300→
301→      const processingMs = Date.now() - msgStartTime;
302→      processingTimes.push(processingMs);
303→
304→      log("message_processed", {
305→        batchId,
306→        repoId,
307→        requested: checkpointIds.length,
308→        found: checkpoints.length,
309→        indexed,
310→        processingMs,
311→        attempt: msg.attempts,
312→      });
313→
314→      msg.ack();
315→      successCount++;
316→    } catch (err) {
317→      const processingMs = Date.now() - msgStartTime;
318→      processingTimes.push(processingMs);
319→      errorCount++;
320→
321→      log("message_error", {
322→        batchId,
323→        repoId,
324→        checkpointCount: checkpointIds.length,
325→        attempt: msg.attempts,
326→        processingMs,
327→        error: err instanceof Error ? err.message : String(err),
328→      });
329→
330→      // Retry on transient failures (max_retries configured in wrangler.jsonc)
331→      msg.retry();
332→    }
333→  }
334→
335→  const totalBatchTimeMs = Date.now() - batchStartTime;
336→
337→  log("batch_complete", {
338→    batchId,
339→    count: batch.messages.length,
340→    successCount,
341→    errorCount,
342→    skippedCount,
343→    totalBatchTimeMs,
344→    avgProcessingMs: avgMs(processingTimes),
345→    throughputPerMin:
346→      totalBatchTimeMs > 0
347→        ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
348→        : 0,
349→  });
350→}
