375→// Daily reconciliation cron handler
376→// Queues stale repos for checkpoint sync and identifies stale users
377→export async function handleReconciliationCron(
378→  env: Env,
379→  options: ReconciliationOptions = {},
380→): Promise<ReconciliationResult> {
381→  const now = new Date();
382→  const staleThreshold = new Date(
383→    now.getTime() - 24 * 60 * 60 * 1000,
384→  ).toISOString();
385→  const isTargeted = !!(options.repoFullName || options.repoIds?.length);
386→
387→  log("cron_started", {
388→    threshold: staleThreshold,
389→    force: options.force ?? false,
390→    targeted: isTargeted,
391→    repoFullName: options.repoFullName,
392→    repoIds: options.repoIds,
393→  });
394→
395→  const db = getDb(env);
396→
397→  // A. Queue repos for checkpoint reconciliation
398→  let reposToQueue: { id: string; full_name: string }[];
399→  try {
400→    reposToQueue = await db.repos.getForReconciliation({
401→      repoFullName: options.repoFullName,
402→      repoIds: options.repoIds,
403→      force: options.force,
404→      staleThreshold,
405→    });
406→  } catch (err) {
407→    if (options.repoFullName) {
408→      log("cron_error_repo_not_found", {
409→        repoFullName: options.repoFullName,
410→        error: errorString(err),
411→      });
412→      return { reposQueued: 0, usersQueued: 0, targetedRepo: options.repoFullName };
413→    }
414→    log("cron_error_fetching_repos", { error: errorString(err) });
415→    return { reposQueued: 0, usersQueued: 0 };
416→  }
417→
418→  const reposQueued = await queueRepoSyncBatch(
419→    env.REPO_SYNC_QUEUE,
420→    reposToQueue,
421→    "reconciliation",
422→    1,
423→  );
424→
425→  // B. Queue stale users for repo sync (skip if targeting specific repos)
426→  let usersQueued = 0;
427→  if (!isTargeted) {
428→    try {
429→      const staleUsers = await db.refreshState.getStaleUsers(staleThreshold, 100);
430→      usersQueued = await queueUserRepoSyncBatch(
431→        env.USER_REPO_SYNC_QUEUE,
432→        staleUsers,
433→        "reconciliation",
434→      );
435→    } catch (err) {
436→      log("cron_error_fetching_users", { error: errorString(err) });
437→    }
438→  }
439→
440→  const result: ReconciliationResult = {
441→    reposQueued,
442→    usersQueued,
443→    targetedRepo: options.repoFullName,
444→  };
445→
446→  log("cron_complete", { ...result });
447→
448→  return result;
449→}
