162→async function checkRepoAccess(
163→  db: Db,
164→  repoFullName: string,
165→  userId: string | undefined,
166→  options: { requireRepo?: boolean } = {},
167→): Promise<RepoRecord | null | Response> {
168→  if (userId) {
169→    // Authenticated: check user_repos join (existing behavior)
170→    const result = await db.repos.getByFullNameWithAccess(repoFullName, userId);
171→
172→    if (result.status === "found") {
173→      return result.repo;
174→    }
175→
176→    if (result.status === "not_found") {
177→      if (options.requireRepo) {
178→        return new Response(JSON.stringify({ error: "Repository not found" }), {
179→          status: 404,
180→          headers: { "Content-Type": "application/json" },
181→        });
182→      }
183→      return null;
184→    }
185→
186→    // status === "no_access"
187→    // Fall back to public repo access for authenticated users too.
188→    // This ensures signed-in users can view public repos they don't explicitly own.
189→    const publicRepo = await db.repos.getPublicByFullName(repoFullName);
190→    if (publicRepo) return publicRepo;
191→
192→    // Private repo with no access: return 404 to prevent repo fishing.
193→    return new Response(JSON.stringify({ error: "Repository not found" }), {
194→      status: 404,
195→      headers: { "Content-Type": "application/json" },
196→    });
197→  }
198→
199→  // Unauthenticated: only serve public repos (hardcoded is_private = false)
200→  const repo = await db.repos.getPublicByFullName(repoFullName);
201→  if (!repo) {
202→    if (options.requireRepo) {
203→      return new Response(JSON.stringify({ error: "Repository not found" }), {
204→        status: 404,
205→        headers: { "Content-Type": "application/json" },
206→      });
207→    }
208→    return null;
209→  }
210→  return repo;
211→}
