273→// Helper for local dev: fetches repo from GitHub if needed, syncs checkpoints, returns data
274→// Used when ?source=github is passed (webhooks don't fire in local dev)
275→async function fetchRepoWithSyncForLocalDev(
276→  db: Db,
277→  repoFullName: string,
278→  userId: string,
279→  branch: string,
280→  limit: number,
281→  getGitHubToken: () => Promise<string | null>,
282→): Promise<LocalDevSyncResult | Response> {
283→  // Check repo access first
284→  const repoAccess = await checkRepoAccess(db, repoFullName, userId);
285→  if (repoAccess instanceof Response) return repoAccess;
286→  let repoRecord = repoAccess;
287→
288→  // If repo not in DB, create it from GitHub API
289→  if (!repoRecord) {
290→    const token = await getGitHubToken();
291→    if (!token) {
292→      return new Response(
293→        JSON.stringify({ error: "GitHub token required for this operation" }),
294→        { status: 403, headers: { "Content-Type": "application/json" } },
295→      );
296→    }
297→
298→    const repoResponse = await fetch(
299→      `https://api.github.com/repos/${repoFullName}`,
300→      {
301→        headers: {
302→          Authorization: `Bearer ${token}`,
303→          Accept: "application/vnd.github+json",
304→          "User-Agent": "entire-api",
305→        },
306→      },
307→    );
308→
309→    if (repoResponse.ok) {
310→      const ghRepo = (await repoResponse.json()) as {
311→        id: number;
312→        name: string;
313→        full_name: string;
314→        description: string | null;
315→        html_url: string;
316→        language: string | null;
317→        stargazers_count: number;
318→        fork: boolean;
319→        private: boolean;
320→        pushed_at: string | null;
321→      };
322→
323→      await db.repos.upsert({
324→        github_id: ghRepo.id,
325→        full_name: ghRepo.full_name,
326→        name: ghRepo.name,
327→        description: ghRepo.description,
328→        html_url: ghRepo.html_url,
329→        language: ghRepo.language,
330→        stargazers_count: ghRepo.stargazers_count,
331→        is_fork: ghRepo.fork,
332→        is_private: ghRepo.private,
333→        pushed_at: ghRepo.pushed_at,
334→      });
335→
336→      repoRecord = await db.repos.getByFullName(repoFullName);
337→    }
338→  }
339→
340→  // Trigger sync and fetch checkpoints
341→  if (repoRecord) {
342→    const token = await getGitHubToken();
343→    if (!token) {
344→      return new Response(
345→        JSON.stringify({ error: "GitHub token required for this operation" }),
346→        { status: 403, headers: { "Content-Type": "application/json" } },
347→      );
348→    }
349→

350→    const { syncRepoCheckpoints } = await import("../lib/repo-sync-service");
351→    await syncRepoCheckpoints(db, repoRecord.id, token, {
352→      skipAppInstallationCheck: true,
353→      extraBranches: [branch],
354→    });
355→
356→    const checkpoints = await db.checkpoints.getForBranch(
357→      repoRecord.id,
358→      branch,
359→      { limit },
360→    );
361→    return { repoRecord, checkpoints };
362→  }
363→
364→  return { repoRecord: null, checkpoints: [] };
365→}
