// Public endpoint: GitHub star count for entireio/cli (cached in KV)
const STARS_CACHE_KEY = "github-stars:entireio/cli";
const STARS_CACHE_TTL_SECONDS = 60 * 60; // 1 hour

cacheRoutes.get("/github-stars", async (c) => {
  // Try KV cache first
  const cached = await c.env.ENTIRE_CACHE.get<{ stars: number }>(STARS_CACHE_KEY, "json");
  if (cached) {
    return c.json(cached);
  }

  // Fetch from GitHub
  let res: Response;
  try {
    res = await fetch("https://api.github.com/repos/entireio/cli", {
      headers: { "User-Agent": "entire-api" },
    });
  } catch {
    return c.json({ stars: null }, 502);
  }
  if (!res.ok) {
    res.body?.cancel();
    return c.json({ stars: null }, 502);
  }

  let data: { stargazers_count?: number } | null;
  try {
    data = await res.json();
  } catch {
    return c.json({ stars: null }, 502);
  }

  if (data == null || typeof data !== "object") {
    return c.json({ stars: null }, 502);
  }

  const stars = typeof data.stargazers_count === "number" ? data.stargazers_count : null;
  if (stars === null) {
    return c.json({ stars: null }, 502);
  }

  const result = { stars };

  // Cache in KV
  await c.env.ENTIRE_CACHE.put(STARS_CACHE_KEY, JSON.stringify(result), {
    expirationTtl: STARS_CACHE_TTL_SECONDS,
  });

  return c.json(result);
});

// Mount sub-routers on the main cache router
// userRoutes requires authentication, repoRoutes allows optional auth
cacheRoutes.route("/", userRoutes);
cacheRoutes.route("/", repoRoutes);

