195→// Now iterates by installation (not by user) to properly handle org installations.
196→adminRoutes.post("/refresh-app-access", async (c) => {
197→
198→  const body = await c.req
199→    .json<{ userLogin?: string }>()
200→    .catch(() => ({ userLogin: undefined }));
201→
202→  const db = getDb(c.env);
203→
204→  // If userLogin is provided, only process that user's installations
205→  const isUserSpecific = !!body.userLogin;
206→  let installationsWithTokens: Array<{
207→    installation: { id: string; github_installation_id: number; account_login: string };
208→    user: {
209→      id: string;
210→      github_login: string | null;
211→      github_token_enc: string | null;
212→      github_refresh_token_enc: string | null;
213→      github_token_expires_at: string | null;
214→    };
215→  }>;
216→
217→  try {
218→    if (body.userLogin) {
219→      const userResult = await db.installations.getForUser(body.userLogin);
220→      if (!userResult) {
221→        return c.json({ error: `User "${body.userLogin}" not found` }, 404);
222→      }
223→      if (!userResult.user.github_token_enc) {
224→        return c.json(
225→          { error: `User "${body.userLogin}" has no GitHub token` },
226→          400,
227→        );
228→      }
229→      // Convert to the same format as getInstallationsWithTokens
230→      installationsWithTokens = userResult.installations.map((installation) => ({
231→        installation,
232→        user: userResult.user,
233→      }));
234→    } else {
235→      installationsWithTokens = await db.installations.getWithTokens();
236→    }
237→  } catch (err) {
238→    console.error("refresh-app-access: error fetching installations:", err);
239→    return c.json(
240→      {
241→        error: "Failed to fetch installations",
242→        details: err instanceof Error ? err.message : String(err),
243→      },
244→      500,
245→    );
246→  }
247→
248→  if (installationsWithTokens.length === 0) {
249→    return c.json({
250→      success: true,
251→      message: body.userLogin
252→        ? `No installations found for user "${body.userLogin}"`
253→        : "No installations with tokens found",
254→      stats: {
255→        usersProcessed: 0,
256→        usersSkipped: 0,
257→        reposWithAccess: 0,
258→        reposUpdated: 0,
259→        userRepoLinksCreated: 0,
260→      },
261→    });
262→  }
263→
264→  // Track all repos that have app access (across all installations)
265→  const reposWithAccess = new Map<number, InstallationRepo>();
266→  // Track installation -> repos for creating user links later
267→  const installationRepos = new Map<number, InstallationRepo[]>();
268→
269→  let usersProcessed = 0;
270→  let usersSkipped = 0;
271→  const errors: string[] = [];
272→
273→  for (const { installation, user } of installationsWithTokens) {
274→    try {
275→      // Get valid token for this user
276→      const tokenResult = await getValidGitHubTokenFromContext(c, db, user);
277→
278→      // Fetch repos for this installation
279→      const repos = await fetchInstallationRepos(
280→        installation.github_installation_id,
281→        tokenResult.token,
282→      );
283→
284→      if (repos === null) {
285→        errors.push(
286→          `Installation ${installation.account_login} (${installation.github_installation_id}): failed to fetch repos`,
287→        );
288→        usersSkipped++;
289→        continue;
290→      }
291→
292→      // Track repos for this installation
293→      installationRepos.set(installation.github_installation_id, repos);
294→
295→      for (const repo of repos) {
296→        reposWithAccess.set(repo.github_id, repo);
297→      }
298→
299→      usersProcessed++;
300→      console.log(
301→        `refresh-app-access: processed installation ${installation.account_login}, found ${repos.length} repos`,
302→      );
303→    } catch (err) {
304→      const errorMsg = err instanceof Error ? err.message : String(err);
305→      errors.push(`Installation ${installation.account_login}: ${errorMsg}`);
306→      usersSkipped++;
307→    }
308→  }
309→
310→  // Safety check: don't wipe existing access data if we failed to gather any new data
311→  if (usersProcessed === 0) {
312→    const message = isUserSpecific
313→      ? `Failed to refresh access for user "${body.userLogin}". Check if GitHub API is available and user token is valid.`
314→      : "Aborting to prevent wiping existing app access data. Check if GitHub API is available and user tokens are valid.";
315→    return c.json(
316→      {
317→        error: "No installations were successfully processed",
318→        message,
319→        stats: {
320→          usersProcessed: 0,
321→          usersSkipped,
322→        },
323→        errors: errors.length > 0 ? errors : undefined,
324→      },
325→      500,
326→    );
327→  }
328→
329→  // Reset all app_has_access to false first (only for full refresh, not user-specific)
330→  if (!isUserSpecific) {
331→    const { error: resetError } = await db.admin.resetAppHasAccess();
332→
333→    if (resetError) {
334→      console.error(
335→        "refresh-app-access: error resetting app_has_access:",
336→        resetError,
337→      );
338→      return c.json(
339→        { error: "Failed to reset app access", details: resetError.message },
340→        500,
341→      );
342→    }
343→  }
344→
345→  // Build a map from github_id -> installation UUID for repos
346→  // A repo may appear in multiple installations; use the first one found
347→  const repoInstallationMap = new Map<number, string>();
348→  for (const { installation: inst } of installationsWithTokens) {
349→    const repos = installationRepos.get(inst.github_installation_id);
350→    if (!repos) continue;
351→    for (const repo of repos) {
352→      if (!repoInstallationMap.has(repo.github_id)) {
353→        repoInstallationMap.set(repo.github_id, inst.id);
354→      }
355→    }
356→  }
357→
358→  // Upsert repos and set app_has_access = true
359→  let reposUpdated = 0;
360→  for (const [githubId, repoData] of reposWithAccess) {
361→    try {
362→      await db.repos.upsert({
363→        github_id: githubId,
364→        full_name: repoData.full_name,
365→        name: repoData.name,
366→        description: repoData.description,
367→        html_url: repoData.html_url,
368→        language: repoData.language,
369→        stargazers_count: repoData.stargazers_count,
370→        is_fork: repoData.is_fork,
371→        is_private: repoData.is_private,
372→        pushed_at: repoData.pushed_at,
373→        app_has_access: true,
374→        installation_id: repoInstallationMap.get(githubId) ?? null,
375→      });
376→      reposUpdated++;
377→    } catch (err) {
378→      console.error(
379→        `refresh-app-access: error upserting repo ${repoData.full_name}:`,
380→        err,
381→      );
382→    }
383→  }
384→
385→  // Create user_repos links
386→  let linksCreated = 0;
387→  let linkErrors = 0;
388→
389→  if (isUserSpecific && body.userLogin) {
390→    // For user-specific refresh, only create links for that user
391→    const targetUserId = installationsWithTokens[0]?.user.id;
392→    if (targetUserId) {
393→      for (const repos of installationRepos.values()) {
394→        for (const repoData of repos) {
395→          try {
396→            const repo = await db.repos.getByGithubId(repoData.github_id);
397→
398→            if (repo) {
399→              await db.repos.addUserRepo(targetUserId, repo.id);
400→              linksCreated++;
401→            }
402→          } catch (err) {
403→            linkErrors++;
404→          }
405→        }
406→      }
407→    }
408→  } else {
409→    // For full refresh, create links for all users of each installation
410→    for (const [githubInstallationId, repos] of installationRepos) {
411→      const users = await db.installations.findUsersByGitHubId(
412→        githubInstallationId,
413→      );
414→
415→      for (const user of users) {
416→        for (const repoData of repos) {
417→          try {
418→            const repo = await db.repos.getByGithubId(repoData.github_id);
419→
420→            if (repo) {
421→              await db.repos.addUserRepo(user.id, repo.id);
422→              linksCreated++;
423→            }
424→          } catch (err) {
425→            linkErrors++;
426→          }
427→        }
428→      }
429→    }
430→  }
431→
432→  const message = isUserSpecific
433→    ? `App access refreshed for user "${body.userLogin}"`
434→    : "App access refreshed from GitHub installations";
435→
436→  return c.json({
437→    success: true,
438→    message,
439→    stats: {
440→      usersProcessed,
441→      usersSkipped,
442→      reposWithAccess: reposWithAccess.size,
443→      reposUpdated,
444→      userRepoLinksCreated: linksCreated,
445→      userRepoLinkErrors: linkErrors,
446→    },
447→    errors: errors.length > 0 ? errors : undefined,
448→  });
449→});
