490→// Admin: Replay a missed installation by fetching directly from GitHub App API
491→// Use when installation.created webhook was never received/processed
492→adminRoutes.post("/replay-installation", async (c) => {
493→
494→  const body = await c.req
495→    .json<{ installation_id: number }>()
496→    .catch(() => ({ installation_id: 0 }));
497→
498→  const installationId = body.installation_id;
499→  if (!installationId || typeof installationId !== "number") {
500→    return c.json({ error: "installation_id (number) is required" }, 400);
501→  }
502→
503→  const appConfig = {
504→    appId: c.env.GITHUB_CLIENT_ID,
505→    privateKey: c.env.GITHUB_APP_PRIVATE_KEY,
506→  };
507→
508→  // Step 1: Fetch installation details from GitHub (authenticate as the App)
509→  let installationData: {
510→    id: number;
511→    account: { login: string; type: string; id: number };
512→    app_slug: string | null;
513→  };
514→
515→  try {
516→    const jwt = await createAppJWT(appConfig.appId, appConfig.privateKey);
517→    const response = await fetch(
518→      `https://api.github.com/app/installations/${installationId}`,
519→      {
520→        headers: {
521→          Authorization: `Bearer ${jwt}`,
522→          Accept: "application/vnd.github+json",
523→          "User-Agent": "entire-api",
524→          "X-GitHub-Api-Version": "2022-11-28",
525→        },
526→      }
527→    );
528→
529→    if (!response.ok) {
530→      const errorText = await response.text();
531→      return c.json(
532→        { error: `GitHub API error fetching installation: ${response.status} - ${errorText}` },
533→        response.status === 404 ? 404 : 500
534→      );
535→    }
536→
537→    installationData = await response.json();
538→  } catch (err) {
539→    return c.json(
540→      { error: "Failed to fetch installation from GitHub", details: err instanceof Error ? err.message : String(err) },
541→      500
542→    );
543→  }
544→
545→  // Step 2: Get an installation access token to list repos
546→  let installationToken: string;
547→  try {
548→    installationToken = await getInstallationToken(installationId, appConfig, c.env.ENTIRE_CACHE);
549→  } catch (err) {
550→    return c.json(
551→      { error: "Failed to get installation token", details: err instanceof Error ? err.message : String(err) },
552→      500
553→    );
554→  }
555→
556→  // Step 3: Fetch all repos for this installation (paginated)
557→  const allRepos: Array<{ id: number; full_name: string; private?: boolean; default_branch?: string }> = [];
558→  let page = 1;
559→  while (true) {
560→    const reposResponse = await fetch(
561→      `https://api.github.com/installation/repositories?per_page=100&page=${page}`,
562→      {
563→        headers: {
564→          Authorization: `token ${installationToken}`,
565→          Accept: "application/vnd.github+json",
566→          "User-Agent": "entire-api",
567→          "X-GitHub-Api-Version": "2022-11-28",
568→        },
569→      }
570→    );
571→
572→    if (!reposResponse.ok) {
573→      const errorText = await reposResponse.text();
574→      return c.json(
575→        { error: `GitHub API error listing repos: ${reposResponse.status} - ${errorText}` },
576→        500
577→      );
578→    }
579→
580→    const data = await reposResponse.json<{
581→      total_count: number;
582→      repositories: Array<{ id: number; full_name: string; private?: boolean; default_branch?: string }>;
583→    }>();
584→
585→    allRepos.push(...data.repositories);
586→
587→    if (allRepos.length >= data.total_count || data.repositories.length === 0) {
588→      break;
589→    }
590→    page++;
591→  }
592→
593→  const db = getDb(c.env);
594→
595→  // Step 4: Upsert the installation record
596→  const installationUuid = await db.installations.upsert({
597→    github_installation_id: installationId,
598→    account_login: installationData.account.login,
599→    account_type: installationData.account.type,
600→    account_id: installationData.account.id,
601→    app_slug: installationData.app_slug ?? null,
602→    suspended_at: null,
603→  });
604→
605→  // Step 5: Batch upsert all repos with app_has_access=true
606→  const repoIds = await db.repos.upsertBatch(
607→    allRepos.map((repo) => ({
608→      github_id: repo.id,
609→      full_name: repo.full_name,
610→      app_has_access: true,
611→      installation_id: installationUuid,
612→      default_branch: repo.default_branch,
613→      is_private: repo.private,
614→    }))
615→  );
616→
617→  // Step 6: Queue repos for checkpoint sync if queue is available
618→  let reposQueued = 0;
619→  try {
620→    if (c.env.REPO_SYNC_QUEUE) {
621→      reposQueued = await queueRepoSyncBatch(
622→        c.env.REPO_SYNC_QUEUE,
623→        repoIds.map((id) => ({ id })),
624→        "installation",
625→        10
626→      );
627→    }
628→  } catch (err) {
629→    console.error("replay-installation: failed to queue repos for sync:", err);
630→  }
631→
632→  console.log(
633→    `replay-installation: installation ${installationId} (${installationData.account.login}): ` +
634→    `${allRepos.length} repos upserted, ${reposQueued} queued for sync`
635→  );
636→
637→  return c.json({
638→    success: true,
639→    message: `Installation ${installationId} replayed: ${allRepos.length} repos upserted, ${reposQueued} queued for sync`,
640→    installation: {
641→      id: installationId,
642→      account_login: installationData.account.login,
643→      account_type: installationData.account.type,
644→    },
645→    repos_count: allRepos.length,
646→    repos_queued: reposQueued,
647→  });
648→});
