 21→// TTL for sync:lastUpdate KV entries (7 days)
 22→const SYNC_LAST_UPDATE_TTL = 60 * 60 * 24 * 7;
 23→
 24→// Log with consistent prefix
 25→function log(event: string, data: Record<string, unknown>): void {
 26→  console.log(`[repo-sync-queue] ${event}`, JSON.stringify(data));
 27→}
 28→
 29→// KV key for per-installation rate limit state
 30→function rateLimitKey(installationId: number): string {
 31→  return `github:ratelimit:installation:${installationId}:resetAt`;
 32→}
 33→
 34→// Check if a specific installation is currently rate limited
 35→async function isRateLimited(cache: KVNamespace, installationId: number): Promise<boolean> {
 36→  const key = rateLimitKey(installationId);
 37→  const resetAt = await cache.get(key);
 38→  if (!resetAt) return false;
 39→
 40→  const resetTime = parseInt(resetAt, 10);
 41→  if (Date.now() < resetTime) {
 42→    return true;
 43→  }
 44→
 45→  // Rate limit has expired, clean up
 46→  await cache.delete(key);
 47→  return false;
 48→}
 49→
 50→// Set rate limit marker for a specific installation (called when we hit a rate limit)
 51→async function setRateLimitMarker(
 52→  cache: KVNamespace,
 53→  installationId: number,
 54→  resetAt?: number,
 55→): Promise<void> {
 56→  // Default to 15 minutes from now if no reset time provided
 57→  const resetTime = resetAt ?? Date.now() + 15 * 60 * 1000;
 58→  // Store with TTL of 1 hour (self-cleaning)
 59→  await cache.put(rateLimitKey(installationId), String(resetTime), {
 60→    expirationTtl: 60 * 60,
 61→  });
 62→  log("rate_limit_set", { installationId, resetAt: new Date(resetTime).toISOString() });
 63→}
 64→
 65→// Notify users with access to a repo that data has been updated
 66→// This triggers frontend polling to detect the change and refresh
 67→// Note: This function never throws - errors are logged and swallowed
 68→// to avoid affecting the main sync flow (notification is best-effort)
 69→async function notifyUsersOfRepoUpdate(
 70→  db: Db,
 71→  cache: KVNamespace,
 72→  repoId: string
 73→): Promise<number> {
 74→  try {
 75→    // Get all users with access to this repo (reuse existing utility)
 76→    const userIds = await db.repos.getUsersForRepo(repoId);
 77→
 78→    if (userIds.length === 0) {
 79→      return 0;
 80→    }
 81→
 82→    // Update sync:lastUpdate for each user
 83→    const now = String(Date.now());
 84→    await Promise.all(
 85→      userIds.map((userId) =>
 86→        cache.put(`sync:lastUpdate:${userId}`, now, {
 87→          expirationTtl: SYNC_LAST_UPDATE_TTL,
 88→        })
 89→      )
 90→    );
 91→
 92→    return userIds.length;
 93→  } catch (err) {
 94→    log("notify_users_error", {
 95→      repoId,
 96→      error: errorString(err),
 97→    });
 98→    return 0;
 99→  }
100→}
