117→// Look up the GitHub App installation ID for a repo
118→async function getRepoInstallationId(
119→  db: Db,
120→  repoId: string,
121→): Promise<number | null> {
122→  const repo = await db.repos.getById(repoId);
123→
124→  if (!repo) {
125→    log("repo_not_found", { repoId });
126→    return null;
127→  }
128→
129→  // Fast path: use the direct FK if available
130→  if (repo.installation_id) {
131→    const githubInstallationId = await db.installations.getGithubId(repo.installation_id);
132→    if (githubInstallationId) {
133→      return githubInstallationId;
134→    }
135→  }
136→
137→  // NB: This fallback shouldn't be required for long.
138→  // Fallback: look up by owner name (for repos not yet backfilled)
139→  const owner = repo.full_name.split("/")[0];
140→  const githubInstallationId = await db.installations.getGithubIdByOwner(owner);
141→  if (!githubInstallationId) {
142→    log("no_installation_for_repo", { repoId, owner });
143→    return null;
144→  }
145→
146→  return githubInstallationId;
147→}
