172→// Process a batch of repo sync messages
173→export async function processRepoSyncBatch(
174→  batch: MessageBatch<RepoSyncMessage>,
175→  env: Env,
176→): Promise<void> {
177→  const batchStartTime = Date.now();
178→  const batchId = generateBatchId();
179→
180→  // Calculate queue wait times for all messages in batch
181→  const queueWaitTimes = batch.messages.map(
182→    (msg) => Date.now() - msg.timestamp.getTime(),
183→  );
184→  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;
185→
186→  log("batch_started", {
187→    batchId,
188→    queue: batch.queue,
189→    count: batch.messages.length,
190→    avgQueueWaitMs: avgMs(queueWaitTimes),
191→    maxQueueWaitMs: maxWaitMs,
192→  });
193→
194→  const db = getDb(env);
195→  const processingTimes: number[] = [];
196→  let successCount = 0;
197→  let errorCount = 0;
198→  let skippedCount = 0;
199→
200→  for (let i = 0; i < batch.messages.length; i++) {
201→    const msg = batch.messages[i];
202→    const msgStartTime = Date.now();
203→    const { repoId, reason } = msg.body;
204→    const queueWaitMs = Date.now() - msg.timestamp.getTime();
205→
206→    let installationId: number | null = null;
207→    try {
208→      // Look up installation for rate limit checks
209→      installationId = await getRepoInstallationId(db, repoId);
210→
211→      if (!installationId) {
212→        log("no_installation_for_repo", { batchId, repoId, reason });
213→        msg.ack();
214→        skippedCount++;
215→        continue;
216→      }
217→
218→      // Check if this installation is rate limited
219→      if (await isRateLimited(env.ENTIRE_CACHE, installationId)) {
220→        log("message_skipped_rate_limited", { batchId, repoId, installationId, reason });
221→        msg.retry();
222→        skippedCount++;
223→        continue;
224→      }
225→
226→      // Get a token for this installation
227→      const token = await getTokenForInstallation(installationId, env);
228→
229→      if (!token) {
230→        log("no_token_for_repo", { batchId, repoId, installationId, reason });
231→        // Can't sync without a token - ack to avoid infinite retries
232→        // The repo will be picked up again on next reconciliation
233→        msg.ack();
234→        skippedCount++;
235→        continue;
236→      }
237→
238→      // For user_sync, skip if repo was already synced (another job got there first)
239→      // This prevents duplicate work when multiple users log in for the same repo
240→      if (reason === "user_sync" && await db.repos.isCheckpointsSynced(repoId)) {
241→        log("skip_already_synced", { batchId, repoId, reason });
242→        msg.ack();
243→        skippedCount++;
244→        continue;
245→      }
246→
247→      const result = await traced("repo-sync-queue.processMessage", async () => {
248→        const span = trace.getActiveSpan();
249→        span?.setAttribute("queue.message_wait_ms", queueWaitMs);
250→        span?.setAttribute("github.installation_id", installationId!);
251→
252→        return await syncRepoCheckpoints(db, repoId, token);
253→      });
254→      const processingMs = Date.now() - msgStartTime;
255→      processingTimes.push(processingMs);
256→
257→      log("message_processed", {
258→        batchId,
259→        messageIndex: i + 1,
260→        totalMessages: batch.messages.length,
261→        repoId,
262→        reason,
263→        result: result.status,
264→        skipReason: result.reason,
265→        checkpoints: result.checkpointsDiscovered,
266→        queueWaitMs,
267→        processingMs,
268→        attempt: msg.attempts,
269→      });
270→
271→      msg.ack();
272→      if (result.status === "ok") {
273→        successCount++;
274→        // Notify users so frontend refreshes
275→        const usersNotified = await notifyUsersOfRepoUpdate(db, env.ENTIRE_CACHE, repoId);
276→        if (usersNotified > 0) {
277→          log("users_notified", { repoId, usersNotified });
278→        }
279→        // Queue discovered checkpoints for transcript storage + search indexing
280→        const cpIds = result.discoveredCheckpointIds;
281→        if (cpIds && cpIds.length > 0 && env.SEARCH_INDEX_QUEUE) {
282→          const SEARCH_BATCH_SIZE = 50;
283→          for (let j = 0; j < cpIds.length; j += SEARCH_BATCH_SIZE) {
284→            await env.SEARCH_INDEX_QUEUE.send({
285→              repoId,
286→              checkpointIds: cpIds.slice(j, j + SEARCH_BATCH_SIZE),
287→              queuedAt: new Date().toISOString(),
288→            } satisfies SearchIndexMessage);
289→          }
290→          log("search_index_queued", { repoId, checkpointCount: cpIds.length });
291→        }
292→      } else if (result.status === "error") {
293→        errorCount++;
294→      } else {
295→        skippedCount++;
296→      }
297→    } catch (err) {
298→      const processingMs = Date.now() - msgStartTime;
299→      processingTimes.push(processingMs);
300→      errorCount++;
301→
302→      // Check if this is a rate limit error
303→      if (err instanceof GitHubRateLimitError) {
304→        log("rate_limit_hit", {
305→          batchId,
306→          repoId,
307→          installationId,
308→          reason,
309→          resetAt: err.resetAt
310→            ? new Date(err.resetAt * 1000).toISOString()
311→            : undefined,
312→          processingMs,
313→        });
314→
315→        // Set the rate limit marker for this installation only
316→        if (installationId) {
317→          await setRateLimitMarker(
318→            env.ENTIRE_CACHE,
319→            installationId,
320→            err.resetAt ? err.resetAt * 1000 : undefined,
321→          );
322→        }
323→
324→        // Retry only this message; continue processing remaining
325→        // (they may belong to different installations)
326→        msg.retry();
327→        continue;
328→      }
329→
330→      log("message_error", {
331→        batchId,
332→        repoId,
333→        reason,
334→        attempt: msg.attempts,
335→        processingMs,
336→        error: errorString(err),
337→      });
338→
339→      // Retry if not at max attempts (max_retries is configured in wrangler.jsonc)
340→      msg.retry();
341→    }
342→  }
343→
344→  const totalBatchTimeMs = Date.now() - batchStartTime;
345→
346→  log("batch_complete", {
347→    batchId,
348→    count: batch.messages.length,
349→    successCount,
350→    errorCount,
351→    skippedCount,
352→    totalBatchTimeMs,
353→    avgProcessingMs: avgMs(processingTimes),
354→    throughputPerMin:
355→      totalBatchTimeMs > 0
356→        ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
357→        : 0,
358→  });
359→}
