  1→/**
  2→ * Backfill script: Index checkpoints into Turbopuffer for full-text + semantic search.
  3→ *
  4→ * Usage:
  5→ *   npx tsx scripts/backfill-search.ts [options]
  6→ *
  7→ * Options:
  8→ *   --repo <full_name>     Only backfill a specific repo (e.g., "entireio/cli")
  9→ *   --with-transcripts     Fetch transcript excerpts from GitHub (slower, needs GITHUB_TOKEN)
 10→ *   --dry-run              Show what would be indexed without writing to Turbopuffer
 11→ *   --limit <n>            Max checkpoints per repo (for testing)
 12→ *
 13→ * Environment:
 14→ *   DATABASE_URL           MySQL connection string (defaults to local Docker MySQL)
 15→ *   TURBOPUFFER_API_KEY    Turbopuffer API key (required unless --dry-run)
 16→ *   OPENAI_API_KEY         OpenAI API key for embeddings (required unless --dry-run)
 17→ *   GITHUB_TOKEN           GitHub PAT with repo read access (required for --with-transcripts)
 18→ */
 19→
 20→import { Kysely, MysqlDialect } from "kysely";
 21→import { createPool } from "mysql2";
 22→import type { DB } from "../db/types";
 23→import OpenAI from "openai";
 24→import { getParserForAgent } from "../src/lib/transcript-parsers/registry";
 25→
 26→// --- Config ---
 27→
 28→const EMBEDDING_MODEL = "text-embedding-3-small";
 29→const EMBEDDING_DIMENSIONS = 1536;
 30→const CHUNK_SIZE = 50; // process checkpoints in chunks of 50 (fetch transcripts + embed + upsert per chunk)
 31→const CHECKPOINT_BRANCH = "entire/checkpoints/v1";
 32→const GITHUB_API = "https://api.github.com";
 33→const TRANSCRIPT_CONCURRENCY = 15; // parallel GitHub API fetches per chunk
 34→const MAX_TRANSCRIPT_CHARS = 200_000; // generous limit for user prompts + AI responses
 35→const MAX_FILTERABLE_BYTES = 3800; // Turbopuffer 4 KiB limit on filterable attributes
 36→const MAX_TEXT_BYTES = 500_000; // text field is non-filterable (8 MiB limit), generous cap for BM25
 37→const MAX_EMBEDDING_CHARS = 25000; // ~8K tokens, text-embedding-3-small limit is 8192 tokens
 38→const MAX_RETRIES = 3;
 39→const RETRY_BASE_DELAY_MS = 1000;
 40→
 41→// --- CLI Argument Parsing ---
 42→
 43→interface CliOptions {
 44→  repo: string | null;
 45→  withTranscripts: boolean;
 46→  dryRun: boolean;
 47→  limit: number | null;
 48→}
 49→
 50→function parseArgs(): CliOptions {
 51→  const args = process.argv.slice(2);
 52→  const options: CliOptions = {
 53→    repo: null,
 54→    withTranscripts: false,
 55→    dryRun: false,
 56→    limit: null,
 57→  };
 58→
 59→  for (let i = 0; i < args.length; i++) {
 60→    switch (args[i]) {
 61→      case "--repo":
 62→        options.repo = args[++i];
 63→        if (!options.repo) {
 64→          console.error("Error: --repo requires a value (e.g., 'entireio/cli')");
 65→          process.exit(1);
 66→        }
 67→        break;
 68→      case "--with-transcripts":
 69→        options.withTranscripts = true;
 70→        break;
 71→      case "--dry-run":
 72→        options.dryRun = true;
 73→        break;
 74→      case "--limit":
 75→        options.limit = parseInt(args[++i], 10);
 76→        if (isNaN(options.limit) || options.limit <= 0) {
 77→          console.error("Error: --limit requires a positive integer");
 78→          process.exit(1);
 79→        }
 80→        break;
 81→      default:
 82→        console.error(`Unknown option: ${args[i]}`);
 83→        console.error("Usage: npx tsx scripts/backfill-search.ts [--repo <name>] [--with-transcripts] [--dry-run] [--limit <n>]");
 84→        process.exit(1);
 85→    }
 86→  }
 87→
 88→  return options;
 89→}
 90→
 91→// --- Database Setup ---
 92→
 93→function createDb(): Kysely<DB> {
 94→  const url = process.env.DATABASE_URL ?? "mysql://entire:entire@localhost:3306/entire";
 95→  const parsed = new URL(url);
 96→  const isLocalhost = parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1";
 97→
 98→  return new Kysely<DB>({
 99→    dialect: new MysqlDialect({
100→      pool: createPool({
101→        host: parsed.hostname,
102→        port: Number(parsed.port) || 3306,
103→        user: decodeURIComponent(parsed.username),
104→        password: decodeURIComponent(parsed.password),
105→        database: parsed.pathname.replace("/", ""),
106→        ssl: isLocalhost ? undefined : { rejectUnauthorized: true },
107→      }),
108→    }),
109→  });
110→}
111→
112→// --- Text Construction ---
113→
114→function buildSearchText(
115→  checkpoint: CheckpointRow,
116→  transcriptExcerpt?: string,
117→): string {
118→  const parts: string[] = [];
119→
120→  if (checkpoint.prompt) {
121→    parts.push(`Prompt: ${checkpoint.prompt}`);
122→  }
123→  if (checkpoint.commit_message) {
124→    parts.push(`Commit: ${checkpoint.commit_message}`);
125→  }
126→  if (checkpoint.files_touched_str) {
127→    parts.push(`Files: ${checkpoint.files_touched_str}`);
128→  }
129→  if (transcriptExcerpt) {
130→    parts.push(`Transcript: ${transcriptExcerpt}`);
131→  }
132→
133→  return parts.join("\n");
134→}
135→
136→// --- Embedding Generation ---
137→
138→async function generateEmbeddings(
139→  openai: OpenAI,
140→  texts: string[],
141→): Promise<number[][]> {
142→  const response = await openai.embeddings.create({
143→    model: EMBEDDING_MODEL,
144→    input: texts,
145→    dimensions: EMBEDDING_DIMENSIONS,
146→  });
147→
148→  // Sort by index to maintain order
149→  return response.data
150→    .sort((a, b) => a.index - b.index)
151→    .map((item) => item.embedding);
152→}
153→
154→// --- Attribute Truncation ---
155→
156→function truncateToBytes(str: string | null, maxBytes: number): string | null {
157→  if (str === null) return null;
158→  // Fast path: ASCII strings where 1 char = 1 byte
159→  if (str.length <= maxBytes) return str;
160→  // Truncate by encoding to bytes
161→  const encoder = new TextEncoder();
162→  const encoded = encoder.encode(str);
163→  if (encoded.length <= maxBytes) return str;
164→  // Find the last valid UTF-8 boundary within maxBytes
165→  const truncated = encoded.slice(0, maxBytes);
166→  const decoder = new TextDecoder("utf-8", { fatal: false });
167→  return decoder.decode(truncated);
168→}
169→
170→// --- Fetch with Retry ---
171→
172→async function fetchWithRetry(
173→  url: string,
174→  options: RequestInit,
175→): Promise<Response> {
176→  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
177→    try {
178→      const response = await fetch(url, options);
179→      // Retry on transient server errors and rate limits
180→      if (response.status >= 500 || response.status === 429) {
181→        if (attempt < MAX_RETRIES - 1) {
182→          const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
183→          await sleep(delay);
184→          continue;
185→        }
186→      }
187→      return response;
188→    } catch (err) {
189→      if (attempt < MAX_RETRIES - 1) {
190→        const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
191→        await sleep(delay);
192→        continue;
193→      }
194→      throw err;
195→    }
196→  }
197→  throw new Error("fetchWithRetry: exhausted retries");
198→}
199→
200→// --- Transcript Fetching ---
201→
202→async function fetchTranscriptExcerpt(
203→  repoFullName: string,
204→  checkpointId: string,
205→  agent: string,
206→  token: string,
207→): Promise<string | null> {
208→  const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
209→  const path = `${folder}/0/full.jsonl`;
210→
211→  // Encode each path segment individually (preserves / separators)
212→  const encodedPath = path.split("/").map(encodeURIComponent).join("/");
213→  const url = `${GITHUB_API}/repos/${repoFullName}/contents/${encodedPath}?ref=${CHECKPOINT_BRANCH}`;
214→
215→  try {
216→    const response = await fetchWithRetry(url, {
217→      headers: {
218→        Accept: "application/vnd.github.raw+json",
219→        Authorization: `Bearer ${token}`,
220→        "User-Agent": "entire-backfill",
221→        "X-GitHub-Api-Version": "2022-11-28",
222→      },
223→    });
224→
225→    if (!response.ok) {
226→      if (response.status === 404) {
227→        return null;
228→      }
229→      return null;
230→    }
231→
232→    const content = await response.text();
233→
234→    const parser = getParserForAgent(agent);
235→    const result = parser.parse(content);
236→
237→    if (result.messages.length === 0) {
238→      return null;
239→    }
240→
241→    // Extract all user prompts + assistant responses, excluding tool-only messages
242→    const parts: string[] = [];
243→    let charsUsed = 0;
244→
245→    for (const msg of result.messages) {
246→      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;
247→
248→      // Skip assistant messages that are just tool calls with no text
249→      if (msg.role === "assistant" && msg.toolCalls?.length && !msg.content.trim()) {
250→        continue;
251→      }
252→
253→      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
254→      const text = msg.content.slice(0, remaining);
255→      parts.push(`[${msg.role}]: ${text}`);
256→      charsUsed += text.length;
257→    }
258→
259→    return parts.join("\n") || null;
260→  } catch {
261→    return null;
262→  }
263→}
264→
265→function sleep(ms: number): Promise<void> {
266→  return new Promise((resolve) => setTimeout(resolve, ms));
267→}
