269→// --- Types ---
270→
271→interface CheckpointRow {
272→  checkpoint_id: string;
273→  branch: string;
274→  agent: string;
275→  commit_author_username: string | null;
276→  created_at: string | null;
277→  commit_sha: string | null;
278→  commit_message: string | null;
279→  prompt: string | null;
280→  files_touched_str: string | null;
281→}
282→
283→interface RepoRow {
284→  id: string;
285→  github_id: number;
286→  full_name: string;
287→  checkpoint_count: number;
288→}
289→
290→// --- Per-Repo Processing ---
291→
292→async function fetchCheckpointsForRepo(
293→  db: Kysely<DB>,
294→  repoId: string,
295→  limit: number | null,
296→): Promise<CheckpointRow[]> {
297→  // Use the same deferred-join pattern as getCheckpointsForBranch
298→  let idQuery = db
299→    .selectFrom("repo_checkpoint_commits")
300→    .select("id")
301→    .where("repo_id", "=", repoId)
302→    .orderBy("commit_date", "desc");
303→
304→  if (limit) {
305→    idQuery = idQuery.limit(limit);
306→  }
307→
308→  const idRows = await idQuery.execute();
309→  if (idRows.length === 0) return [];
310→
311→  const rows = await db
312→    .selectFrom("repo_checkpoint_commits as cc")
313→    .leftJoin("repo_checkpoints as cp", (join) =>
314→      join
315→        .onRef("cp.repo_id", "=", "cc.repo_id")
316→        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
317→    )
318→    .select([
319→      "cc.checkpoint_id",
320→      "cc.branch",
321→      "cc.commit_sha",
322→      "cc.commit_message",
323→      "cc.commit_author_username",
324→      "cc.commit_date",
325→      "cp.prompt",
326→      "cp.agent",
327→      "cp.created_at",
328→      "cp.files_touched",
329→    ])
330→    .where(
331→      "cc.id",
332→      "in",
333→      idRows.map((r) => r.id),
334→    )
335→    .execute();
336→
337→  return rows.map((row) => {
338→    const filesTouched = row.files_touched as string[] | null;
339→    return {
340→      checkpoint_id: row.checkpoint_id,
341→      branch: row.branch,
342→      agent: row.agent ?? "Claude Code",
343→      commit_author_username: row.commit_author_username,
344→      created_at: row.created_at?.toISOString() ?? row.commit_date?.toISOString() ?? null,
345→      commit_sha: row.commit_sha,
346→      commit_message: row.commit_message,
347→      prompt: row.prompt,
348→      files_touched_str: filesTouched?.join(", ") ?? null,
349→    };
350→  });
351→}
352→
353→function formatElapsed(ms: number): string {
354→  const s = Math.floor(ms / 1000);
355→  if (s < 60) return `${s}s`;
356→  const m = Math.floor(s / 60);
357→  return `${m}m${s % 60}s`;
358→}
359→
360→async function processRepo(
361→  db: Kysely<DB>,
362→  openai: OpenAI,
363→  repo: RepoRow,
364→  options: CliOptions,
365→): Promise<{ indexed: number; skipped: number }> {
366→  const start = Date.now();
367→  const total = repo.checkpoint_count;
368→  console.log(`\n--- ${repo.full_name} (${total} checkpoints) ---`);
369→
370→  const checkpoints = await fetchCheckpointsForRepo(db, repo.id, options.limit);
371→  if (checkpoints.length === 0) {
372→    console.log(`  No checkpoint commits found, skipping.`);
373→    return { indexed: 0, skipped: 0 };
374→  }
375→
376→  console.log(`  Fetched ${checkpoints.length} checkpoint rows from DB.`);
377→
378→  const githubToken = process.env.GITHUB_TOKEN;
379→  const namespaceName = `checkpoints-gh-${repo.github_id}`;
380→  const turbopufferApiKey = process.env.TURBOPUFFER_API_KEY ?? "";
381→  let totalIndexed = 0;
382→  let totalSkipped = 0;
383→  let totalTranscripts = 0;
384→
385→  // Process in chunks: for each chunk, fetch transcripts -> build text -> embed -> upsert
386→  const numChunks = Math.ceil(checkpoints.length / CHUNK_SIZE);
387→
388→  for (let chunkIdx = 0; chunkIdx < numChunks; chunkIdx++) {
389→    const chunkStart = chunkIdx * CHUNK_SIZE;
390→    const chunkEnd = Math.min(chunkStart + CHUNK_SIZE, checkpoints.length);
391→    const chunk = checkpoints.slice(chunkStart, chunkEnd);
392→    const chunkNum = chunkIdx + 1;
393→    const elapsed = formatElapsed(Date.now() - start);
394→
395→    console.log(`  [${chunkNum}/${numChunks}] Processing checkpoints ${chunkStart + 1}-${chunkEnd} of ${checkpoints.length} (${elapsed})`);
396→
397→    // 1. Fetch transcripts for this chunk (parallel with concurrency limit)
398→    let transcripts: (string | undefined)[];
399→    if (options.withTranscripts && githubToken) {
400→      transcripts = new Array(chunk.length).fill(undefined);
401→      let found = 0;
402→
403→      // Process in batches of TRANSCRIPT_CONCURRENCY
404→      for (let batchStart = 0; batchStart < chunk.length; batchStart += TRANSCRIPT_CONCURRENCY) {
405→        const batchEnd = Math.min(batchStart + TRANSCRIPT_CONCURRENCY, chunk.length);
406→        const batch = chunk.slice(batchStart, batchEnd);
407→        const results = await Promise.all(
408→          batch.map((cp) =>
409→            fetchTranscriptExcerpt(repo.full_name, cp.checkpoint_id, cp.agent, githubToken),
410→          ),
411→        );
412→        for (let i = 0; i < results.length; i++) {
413→          transcripts[batchStart + i] = results[i] ?? undefined;
414→          if (results[i]) found++;
415→        }
416→      }
417→
418→      totalTranscripts += found;
419→      console.log(`    Transcripts: ${found}/${chunk.length} found`);
420→    } else {
421→      transcripts = new Array(chunk.length).fill(undefined);
422→    }
423→
424→    // 2. Build search text for each checkpoint
425→    const texts: string[] = [];
426→    const validIndices: number[] = []; // indices within this chunk that have non-empty text
427→    let chunkSkipped = 0;
428→
429→    for (let i = 0; i < chunk.length; i++) {
430→      const text = buildSearchText(chunk[i], transcripts[i]);
431→      if (!text.trim()) {
432→        chunkSkipped++;
433→        continue;
434→      }
435→      texts.push(text);
436→      validIndices.push(i);
437→    }
438→
439→    totalSkipped += chunkSkipped;
440→
441→    if (texts.length === 0) {
442→      console.log(`    All empty, skipped.`);
443→      continue;
444→    }
445→
446→    if (options.dryRun) {
447→      console.log(`    [DRY RUN] Would index ${texts.length} (${chunkSkipped} skipped)`);
448→      totalIndexed += texts.length;
449→      continue;
450→    }
451→
452→    // 3. Truncate texts to stay under embedding model token limit
453→    const embeddingTexts = texts.map((t) => t.slice(0, MAX_EMBEDDING_CHARS));
454→
455→    // 4. Generate embeddings
456→    let embeddings: number[][];
457→    try {
458→      embeddings = await generateEmbeddings(openai, embeddingTexts);
459→    } catch (err) {
460→      const msg = err instanceof Error ? err.message : String(err);
461→      console.error(`    Embedding failed for chunk ${chunkNum}: ${msg.slice(0, 200)}`);
462→      console.error(`    Skipping chunk, continuing...`);
463→      totalSkipped += texts.length;
464→      continue;
465→    }
466→    console.log(`    Embedded ${texts.length} checkpoints`);
467→
468→    // 5. Upsert to Turbopuffer
469→    const vectors = validIndices.map((localIdx, j) => {
470→      const cp = chunk[localIdx];
471→      const globalId = chunkStart + localIdx + 1; // unique ID across all chunks
472→      return {
473→        id: globalId,
474→        vector: embeddings[j],
475→        attributes: {
476→          checkpoint_id: cp.checkpoint_id,
477→          branch: cp.branch,
478→          agent: cp.agent,
479→          author: cp.commit_author_username,
480→          created_at: cp.created_at,
481→          commit_sha: cp.commit_sha,
482→          commit_message: truncateToBytes(cp.commit_message, MAX_FILTERABLE_BYTES),
483→          prompt: truncateToBytes(cp.prompt, MAX_FILTERABLE_BYTES),
484→          files_touched: truncateToBytes(cp.files_touched_str, MAX_FILTERABLE_BYTES),
485→          text: truncateToBytes(texts[j], MAX_TEXT_BYTES),
486→        },
487→      };
488→    });
489→
490→    // Use raw API instead of SDK — the SDK doesn't pass schema through
491→    const upsertUrl = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespaceName)}`;
492→    try {
493→      const resp = await fetchWithRetry(upsertUrl, {
494→        method: "POST",
495→        headers: {
496→          Authorization: `Bearer ${turbopufferApiKey}`,
497→          "Content-Type": "application/json",
498→        },
499→        body: JSON.stringify({
500→          upserts: vectors,
501→          distance_metric: "cosine_distance",
502→          schema: {
503→            text: {
504→              type: "string",
505→              filterable: false,
506→              full_text_search: {
507→                language: "english",
508→                stemming: true,
509→                remove_stopwords: true,
510→              },
511→            },
512→          },
513→        }),
514→      });
515→      if (!resp.ok) {
516→        const errText = await resp.text().catch(() => "");
517→        throw new Error(errText);
518→      }
519→      totalIndexed += texts.length;
520→      console.log(`    Upserted ${texts.length} to Turbopuffer (${totalIndexed} total)`);
521→    } catch (err) {
522→      const msg = err instanceof Error ? err.message : String(err);
523→      console.error(`    Upsert failed for chunk ${chunkNum}: ${msg.slice(0, 200)}`);
524→      console.error(`    Skipping chunk, continuing...`);
525→      totalSkipped += texts.length;
526→    }
527→  }
528→
529→  const elapsed = formatElapsed(Date.now() - start);
530→  console.log(`  Done: ${totalIndexed} indexed, ${totalSkipped} skipped, ${totalTranscripts} transcripts (${elapsed})`);
531→
532→  return { indexed: totalIndexed, skipped: totalSkipped };
533→}
534→
535→// --- Main ---
536→
537→async function main() {
538→  const options = parseArgs();
539→
540→  // Validate env vars
541→  if (!options.dryRun) {
542→    if (!process.env.TURBOPUFFER_API_KEY) {
543→      console.error("Error: TURBOPUFFER_API_KEY is required (or use --dry-run)");
544→      process.exit(1);
545→    }
546→    if (!process.env.OPENAI_API_KEY) {
547→      console.error("Error: OPENAI_API_KEY is required (or use --dry-run)");
548→      process.exit(1);
549→    }
550→  }
551→
552→  if (options.withTranscripts && !process.env.GITHUB_TOKEN) {
553→    console.error("Error: GITHUB_TOKEN is required when using --with-transcripts");
554→    process.exit(1);
555→  }
556→
557→  const db = createDb();
558→
559→  const openai = new OpenAI({
560→    apiKey: process.env.OPENAI_API_KEY ?? "",
561→  });
562→
563→  console.log("Backfill Search Index");
564→  console.log("=====================");
565→  if (options.dryRun) console.log("[DRY RUN MODE]");
566→  if (options.repo) console.log(`Repo filter: ${options.repo}`);
567→  if (options.limit) console.log(`Limit: ${options.limit} checkpoints per repo`);
568→  if (options.withTranscripts) console.log("Transcript fetching: enabled");
569→
570→  // Fetch repos that have actual checkpoint commit rows (not just checkpoint_count > 0,
571→  // which can be stale). This ensures we only index repos with real data.
572→  let repoQuery = db
573→    .selectFrom("repos")
574→    .innerJoin("repo_checkpoint_commits", "repo_checkpoint_commits.repo_id", "repos.id")
575→    .select([
576→      "repos.id",
577→      "repos.github_id",
578→      "repos.full_name",
579→      db.fn.countAll<number>().as("checkpoint_count"),
580→    ])
581→    .groupBy(["repos.id", "repos.github_id", "repos.full_name"]);
582→
583→  if (options.repo) {
584→    repoQuery = repoQuery.where("repos.full_name", "=", options.repo);
585→  }
586→
587→  const repos = (await repoQuery.execute()) as RepoRow[];
588→
589→  if (repos.length === 0) {
590→    console.log("\nNo repos with checkpoints found.");
591→    await db.destroy();
592→    return;
593→  }
594→
595→  console.log(`\nFound ${repos.length} repo(s) with checkpoints.`);
596→
597→  // Process each repo
598→  let totalIndexed = 0;
599→  let totalSkipped = 0;
600→
601→  for (const repo of repos) {
602→    try {
603→      const result = await processRepo(db, openai, repo, options);
604→      totalIndexed += result.indexed;
605→      totalSkipped += result.skipped;
606→    } catch (err) {
607→      console.error(`\nError processing ${repo.full_name}:`, err);
608→      console.error("Continuing with next repo...");
609→    }
610→  }
611→
612→  // Summary
613→  console.log("\n=====================");
614→  console.log("Summary:");
615→  console.log(`  Repos processed: ${repos.length}`);
616→  console.log(`  Checkpoints indexed: ${totalIndexed}`);
617→  console.log(`  Checkpoints skipped: ${totalSkipped}`);
618→
619→  await db.destroy();
620→}
621→
622→main();
