}

// Build checkpoint data array
const checkpointDataArray = buildCheckpointDataFromSessions(checkpointIds, sessionDataResult);

// Upsert checkpoints for the global repo (once, not per-user)
const successCount = await db.checkpoints.upsertBatch(repoRecord.id, checkpointDataArray);

// Queue checkpoints for search indexing (non-blocking, best-effort)
if (env.SEARCH_INDEX_QUEUE) {
  await env.SEARCH_INDEX_QUEUE.send({
    repoId: repoRecord.id,
    checkpointIds,
    queuedAt: new Date().toISOString(),
  } satisfies SearchIndexMessage);
}

// Invalidate transcript cache for affected checkpoints
// Session data changes mean transcripts may have changed
await Promise.all(
  checkpointIds.map((id) =>
    env.ENTIRE_CACHE.delete(buildTranscriptCacheKey(repoFullName, id))
  )
);

