  1→// Strips transcript JSONL to only the fields needed by transcript parsers.
  2→// Reduces size by ~60-80% for efficient DB storage.
  3→//
  4→// The parsers read:
  5→// - type, timestamp, requestId, uuid, message.id, message.content, toolUseResult
  6→// We drop: progress, file-history-snapshot, queue-operation, system entries
  7→// We strip: thinking blocks, tool_use caller field, unnecessary assistant fields
  8→
  9→// Entry types that carry no parser-relevant data
 10→const DROPPED_TYPES = new Set([
 11→  "progress",
 12→  "file-history-snapshot",
 13→  "queue-operation",
 14→  "system",
 15→]);
 16→
 17→/**
 18→ * Strip a JSONL transcript to only the fields the parsers need.
 19→ * Processes line-by-line. Returns stripped JSONL string.
 20→ */
 21→export function stripTranscript(jsonlContent: string): string {
 22→  const lines = jsonlContent.split("\n");
 23→  const result: string[] = [];
 24→
 25→  for (const line of lines) {
 26→    const trimmed = line.trim();
 27→    if (!trimmed) continue;
 28→
 29→    let parsed: Record<string, unknown>;
 30→    try {
 31→      parsed = JSON.parse(trimmed);
 32→    } catch {
 33→      // Skip malformed lines
 34→      continue;
 35→    }
 36→
 37→    const entryType = parsed.type as string | undefined;
 38→
 39→    // Drop entry types that parsers ignore
 40→    if (entryType && DROPPED_TYPES.has(entryType)) {
 41→      continue;
 42→    }
 43→
 44→    const stripped = stripEntry(parsed, entryType);
 45→    if (stripped) {
 46→      result.push(JSON.stringify(stripped));
 47→    }
 48→  }
 49→
 50→  return result.join("\n");
 51→}
 52→
 53→function stripEntry(
 54→  parsed: Record<string, unknown>,
 55→  entryType: string | undefined,
 56→): Record<string, unknown> | null {
 57→  if (entryType === "assistant") {
 58→    return stripAssistantEntry(parsed);
 59→  }
 60→
 61→  if (entryType === "user") {
 62→    return stripUserEntry(parsed);
 63→  }
 64→
 65→  // Unknown entry type — pass through with just type/timestamp/message to be safe
 66→  // This handles future entry types or non-Claude agents
 67→  const out: Record<string, unknown> = {};
 68→  if (parsed.type !== undefined) out.type = parsed.type;
 69→  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp;
 70→  if (parsed.message !== undefined) out.message = parsed.message;
 71→  if (parsed.uuid !== undefined) out.uuid = parsed.uuid;
 72→  if (parsed.requestId !== undefined) out.requestId = parsed.requestId;
 73→  return out;
 74→}
 75→
 76→function stripAssistantEntry(
 77→  parsed: Record<string, unknown>,
 78→): Record<string, unknown> {
 79→  const out: Record<string, unknown> = {
 80→    type: "assistant",
 81→  };
 82→
 83→  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp;
 84→  if (parsed.requestId !== undefined) out.requestId = parsed.requestId;
 85→
 86→  const message = parsed.message as Record<string, unknown> | undefined;
 87→  if (message) {
 88→    const strippedMessage: Record<string, unknown> = {};
 89→    if (message.id !== undefined) strippedMessage.id = message.id;
 90→
 91→    // Strip content: remove thinking blocks, strip caller from tool_use
 92→    if (message.content !== undefined) {
 93→      strippedMessage.content = stripAssistantContent(message.content);
 94→    }
 95→
 96→    out.message = strippedMessage;
 97→  }
 98→
 99→  return out;
100→}
101→
102→function stripAssistantContent(content: unknown): unknown {
103→  // String content — keep as-is
104→  if (typeof content === "string") return content;
105→
106→  // Array of content blocks
107→  if (Array.isArray(content)) {
108→    const stripped: unknown[] = [];
109→    for (const block of content) {
110→      if (typeof block !== "object" || block === null) {
111→        stripped.push(block);
112→        continue;
113→      }
114→
115→      const b = block as Record<string, unknown>;
116→
117→      // Drop thinking blocks
118→      if (b.type === "thinking" || b.type === "redacted_thinking") {
119→        continue;
120→      }
121→
122→      // Strip tool_use: keep id, name, input — drop caller
123→      if (b.type === "tool_use") {
124→        const toolUse: Record<string, unknown> = {
125→          type: "tool_use",
126→        };
127→        if (b.id !== undefined) toolUse.id = b.id;
128→        if (b.name !== undefined) toolUse.name = b.name;
129→        if (b.input !== undefined) toolUse.input = b.input;
130→        stripped.push(toolUse);
131→        continue;
132→      }
133→
134→      // Other block types (text, image) — keep as-is
135→      stripped.push(block);
136→    }
137→    return stripped;
138→  }
139→
140→  return content;
141→}
142→
143→function stripUserEntry(
144→  parsed: Record<string, unknown>,
145→): Record<string, unknown> {
146→  const out: Record<string, unknown> = {
147→    type: "user",
148→  };
149→
150→  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp;
151→  if (parsed.uuid !== undefined) out.uuid = parsed.uuid;
152→
153→  // Keep toolUseResult but minimize it
154→  if (parsed.toolUseResult !== undefined) {
155→    out.toolUseResult = stripToolUseResult(parsed.toolUseResult);
156→  }
157→
158→  const message = parsed.message as Record<string, unknown> | undefined;
159→  if (message) {
160→    const strippedMessage: Record<string, unknown> = {};
161→
162→    if (message.content !== undefined) {
163→      strippedMessage.content = stripUserContent(message.content);
164→    }
165→
166→    out.message = strippedMessage;
167→  }
168→
169→  return out;
170→}
171→
172→function stripUserContent(content: unknown): unknown {
173→  // String content — keep as-is
174→  if (typeof content === "string") return content;
175→
176→  // Array of content blocks
177→  if (Array.isArray(content)) {
178→    const stripped: unknown[] = [];
179→    for (const block of content) {
180→      if (typeof block !== "object" || block === null) {
181→        stripped.push(block);
182→        continue;
183→      }
184→
185→      const b = block as Record<string, unknown>;
186→
187→      // tool_result: keep type and tool_use_id only (content is in toolUseResult)
188→      if (b.type === "tool_result") {
189→        const toolResult: Record<string, unknown> = {
190→          type: "tool_result",
191→        };
192→        if (b.tool_use_id !== undefined) toolResult.tool_use_id = b.tool_use_id;
193→        stripped.push(toolResult);
194→        continue;
195→      }
196→
197→      // Other block types (text, image) — keep as-is
198→      stripped.push(block);
199→    }
200→    return stripped;
201→  }
202→
203→  return content;
204→}
205→
206→function stripToolUseResult(result: unknown): unknown {
207→  if (typeof result !== "object" || result === null) return result;
208→
209→  const r = result as Record<string, unknown>;
210→  const out: Record<string, unknown> = {};
211→
212→  if (r.type !== undefined) out.type = r.type;
213→  if (r.file !== undefined) out.file = r.file;
214→  if (r.error !== undefined) out.error = r.error;
215→  if (r.answers !== undefined) out.answers = r.answers;
216→
217→  return out;
218→}
