  1→// Search index queue consumer
  2→// Processes checkpoint indexing messages for Turbopuffer vector search
  3→
  4→import type { Env } from "../env";
  5→import { getDb } from "./db";
  6→import type { Db } from "./db/db-types";
  7→import { indexCheckpoints } from "./turbopuffer";
  8→import { avgMs, generateBatchId } from "./telemetry";
  9→import { getInstallationToken } from "./token";
 10→import { fetchFileAtCommit } from "./github";
 11→import { getParserForAgent } from "./transcript-parsers/registry";
 12→import { CHECKPOINT_BRANCH } from "./constants";
 13→import { stripTranscript } from "./strip-transcript";
 14→
 15→const MAX_TRANSCRIPT_CHARS = 200_000;
 16→const TRANSCRIPT_CONCURRENCY = 10;
 17→
 18→// Queue message sent after checkpoint data is upserted into PlanetScale
 19→export interface SearchIndexMessage {
 20→  repoId: string;
 21→  checkpointIds: string[];
 22→  queuedAt: string;
 23→}
 24→
 25→// Type guard to check if a message is a SearchIndexMessage
 26→export function isSearchIndexMessage(
 27→  msg: unknown,
 28→): msg is SearchIndexMessage {
 29→  return (
 30→    typeof msg === "object" &&
 31→    msg !== null &&
 32→    "repoId" in msg &&
 33→    "checkpointIds" in msg &&
 34→    "queuedAt" in msg &&
 35→    typeof (msg as SearchIndexMessage).repoId === "string" &&
 36→    Array.isArray((msg as SearchIndexMessage).checkpointIds)
 37→  );
 38→}
 39→
 40→// Log with consistent prefix
 41→function log(event: string, data: Record<string, unknown>): void {
 42→  console.log(`[search-index-queue] ${event}`, JSON.stringify(data));
 43→}
 44→
 45→// Fetch transcript from GitHub, strip it, and return the stripped JSONL
 46→// Returns a per-session map: { "0": "stripped jsonl...", "1": "..." }
 47→async function fetchAndStripTranscript(
 48→  repoFullName: string,
 49→  checkpointId: string,
 50→  sessionCount: number,
 51→  token: string,
 52→): Promise<Record<string, string> | null> {
 53→  try {
 54→    const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
 55→    const sessions: Record<string, string> = {};
 56→    const count = Math.max(sessionCount, 1);
 57→
 58→    for (let i = 0; i < count; i++) {
 59→      const path = `${folder}/${i}/full.jsonl`;
 60→      const content = await fetchFileAtCommit(repoFullName, path, CHECKPOINT_BRANCH, token);
 61→      if (content) {
 62→        sessions[String(i)] = stripTranscript(content);
 63→      }
 64→    }
 65→
 66→    return Object.keys(sessions).length > 0 ? sessions : null;
 67→  } catch {
 68→    return null;
 69→  }
 70→}
 71→
 72→// Parse stripped transcript JSONL into a searchable text excerpt
 73→function parseTranscriptExcerpt(
 74→  strippedJsonl: string,
 75→  agent: string,
 76→): string | null {
 77→  try {
 78→    const parser = getParserForAgent(agent);
 79→    const result = parser.parse(strippedJsonl);
 80→    if (result.messages.length === 0) return null;
 81→
 82→    const parts: string[] = [];
 83→    let charsUsed = 0;
 84→
 85→    for (const msg of result.messages) {
 86→      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;
 87→      if (msg.role === "assistant" && msg.toolCalls?.length && !msg.content.trim()) continue;
 88→
 89→      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
 90→      const text = msg.content.slice(0, remaining);
 91→      parts.push(`[${msg.role}]: ${text}`);
 92→      charsUsed += text.length;
 93→    }
 94→
 95→    return parts.join("\n") || null;
 96→  } catch {
 97→    return null;
 98→  }
 99→}
