 52→// Sync checkpoints for a single repo
 53→// Called by queue consumer
 54→export async function syncRepoCheckpoints(
 55→  db: Db,
 56→  repoId: string,
 57→  token: string,
 58→  options: { fullBackfill?: boolean; skipAppInstallationCheck?: boolean; extraBranches?: string[] } = {}
 59→): Promise<RepoSyncResult> {
 60→  const repoData = await db.repos.getById(repoId);
 61→
 62→  if (!repoData) {
 63→    return { status: "skipped", reason: "repo_not_found" };
 64→  }
 65→
 66→  // Apply defaults for fields that may be null in the database
 67→  const repo = {
 68→    ...repoData,
 69→    default_branch: repoData.default_branch ?? "main",
 70→    app_has_access: repoData.app_has_access ?? false,
 71→  };
 72→
 73→  // Skip app installation check when explicitly requested (e.g., local dev "Fetch from GitHub" button)
 74→  // In local dev, webhooks don't fire so app_has_access is never set
 75→  if (!repo.app_has_access && !options.skipAppInstallationCheck) {
 76→    return { status: "skipped", reason: "no_app_access" };
 77→  }
 78→
 79→  // Check if CHECKPOINT_BRANCH exists (quick "is this repo Entire-enabled?" check)
 80→  const branchExists = await checkBranchExists(repo.full_name, CHECKPOINT_BRANCH, token);
 81→  if (branchExists === null) {
 82→    return { status: "skipped", reason: "branch_check_error" };
 83→  }
 84→  if (branchExists === false) {
 85→    await db.checkpoints.updateSyncState(repoId, {});
 86→    return { status: "skipped", reason: "no_sessions_branch" };
 87→  }
 88→
 89→  const isBackfill = !repo.checkpoints_backfilled_at || options.fullBackfill;
 90→  const since = isBackfill ? undefined : (repo.checkpoints_sync_cursor ?? undefined);
 91→
 92→  log("sync_started", {
 93→    repoId,
 94→    fullName: repo.full_name,
 95→    isBackfill,
 96→    since,
 97→  });
 98→
 99→  try {
100→    // Step 1: Discover checkpoints from default branch via Entire-Checkpoint trailers
101→    const discovered = await discoverCheckpointsFromBranch(
102→      repo.full_name,
103→      repo.default_branch,
104→      token,
105→      since
106→    );
107→
108→    // Track which branch each checkpoint was discovered on (for commit data)
109→    const discoveredBranch = new Map<string, string>();
110→    for (const d of discovered) {
111→      discoveredBranch.set(d.checkpointId, repo.default_branch);
112→    }
113→
114→    // Also scan extra branches (e.g., local dev where webhooks don't fire)
115→    // No `since` filter — cursor is from the default branch and doesn't apply here
116→    const extraBranches = (options.extraBranches ?? []).filter(
117→      (b) => b !== repo.default_branch
118→    );
119→    for (const branch of extraBranches) {
120→      const branchDiscovered = await discoverCheckpointsFromBranch(
121→        repo.full_name,
122→        branch,
123→        token
124→      );
125→      log("extra_branch_scan", {
126→        repoId,
127→        branch,
128→        found: branchDiscovered.length,
129→        alreadyKnown: branchDiscovered.filter((d) => discoveredBranch.has(d.checkpointId)).length,
130→      });
131→      for (const d of branchDiscovered) {
132→        if (!discoveredBranch.has(d.checkpointId)) {
133→          discovered.push(d);
134→          discoveredBranch.set(d.checkpointId, branch);
135→        }
136→      }
137→    }
138→
139→    if (discovered.length === 0) {
140→      await db.checkpoints.updateSyncState(repoId, {});
141→      if (isBackfill) {
142→        await db.checkpoints.updateSyncState(repoId, { backfilled: true });
143→      }
144→      log("sync_complete_no_checkpoints", { repoId, fullName: repo.full_name });
145→      return { status: "ok", checkpointsDiscovered: 0, isBackfill };
146→    }
