281→
282→    // Step 5: Reconcile stale checkpoint commits (backfill only)
283→    // During a full backfill we have the complete picture of what's on each branch,
284→    // so we can safely remove checkpoint commits that are no longer reachable
285→    // (e.g., after force pushes that rewrote history).
286→    let staleDeleted = 0;
287→    if (isBackfill) {
288→      // Group discovered checkpoint IDs by branch
289→      const validByBranch = new Map<string, string[]>();
290→      for (const d of discovered) {
291→        const branch = discoveredBranch.get(d.checkpointId) ?? repo.default_branch;
292→        const existing = validByBranch.get(branch) ?? [];
293→        existing.push(d.checkpointId);
294→        validByBranch.set(branch, existing);
295→      }
296→
297→      // Reconcile each branch we scanned
298→      const branchesToReconcile = new Set([repo.default_branch, ...extraBranches]);
299→      for (const branch of branchesToReconcile) {
300→        const validIds = validByBranch.get(branch) ?? [];
301→        const deleted = await db.checkpoints.deleteStaleCommitsForBranch(repoId, branch, validIds);
302→        staleDeleted += deleted;
303→      }
304→
305→      if (staleDeleted > 0) {
306→        await db.checkpoints.deleteOrphaned(repoId);
307→        log("stale_commits_reconciled", { repoId, staleDeleted });
308→      }
309→    }
310→
311→    // Step 6: Update sync state
312→    await db.checkpoints.updateSyncState(repoId, {
313→      cursor: latestCursor,
314→      backfilled: isBackfill,
315→    });
316→
317→    // Step 6: Recalculate checkpoint count
318→    await db.checkpoints.recalculateCount(repoId);
319→
320→    const totalSessions = checkpointData.reduce((sum, cp) => sum + (cp.session_count ?? 0), 0);
321→    const checkpointsWithSessions = checkpointData.filter((cp) => cp.sessions != null).length;
322→
323→    log("sync_complete", {
324→      repoId,
325→      fullName: repo.full_name,
326→      checkpointsDiscovered: checkpointIds.length,
327→      checkpointsWithCommits: commitsFound,
328→      totalSessions,
329→      checkpointsWithSessions,
330→      isBackfill,
331→    });
332→
333→    return {
334→      status: "ok",
335→      checkpointsDiscovered: checkpointIds.length,
336→      checkpointsWithCommits: commitsFound,
337→      isBackfill,
338→      discoveredCheckpointIds: checkpointIds,
339→    };
340→  } catch (err) {
341→    if (err instanceof GitHubRateLimitError) {
342→      throw err;
343→    }
344→
345→    const errorMessage = errorString(err);
346→    await db.checkpoints.updateSyncState(repoId, { error: errorMessage });
347→
348→    log("sync_error", {
349→      repoId,
350→      fullName: repo.full_name,
351→      error: errorMessage,
352→    });
353→
354→    return { status: "error", reason: errorMessage };
355→  }
356→}
