358→// Cloudflare Queue sendBatch limits
359→const QUEUE_BATCH_MAX_MESSAGES = 100;
360→
361→// Queue multiple repos for checkpoint sync using sendBatch
362→// Respects Cloudflare Queue limits: max 100 messages per batch
363→export async function queueRepoSyncBatch(
364→  queue: Queue<RepoSyncMessage>,
365→  repos: { id: string }[],
366→  reason: RepoSyncMessage["reason"],
367→  priority: number = 5
368→): Promise<number> {
369→  if (repos.length === 0) return 0;
370→
371→  const queuedAt = new Date().toISOString();
372→  let totalQueued = 0;
373→
374→  // Process in batches of 100 (Cloudflare Queue limit)
375→  for (let i = 0; i < repos.length; i += QUEUE_BATCH_MAX_MESSAGES) {
376→    const batch = repos.slice(i, i + QUEUE_BATCH_MAX_MESSAGES);
377→    const messages = batch.map((repo) => ({
378→      body: {
379→        repoId: repo.id,
380→        reason,
381→        priority,
382→        queuedAt,
383→      },
384→    }));
385→
386→    await queue.sendBatch(messages);
387→    totalQueued += batch.length;
388→  }
389→
390→  log("repos_queued_batch", { count: totalQueued, reason, priority, batches: Math.ceil(repos.length / QUEUE_BATCH_MAX_MESSAGES) });
391→  return totalQueued;
392→}
