394→// Environment required for user-level checkpoint sync
395→export interface CheckpointSyncEnv {
396→  db: Db;
397→  cache: KVNamespace;
398→  clientId: string;
399→  clientSecret: string;
400→  encryptionKey: string;
401→}
402→
403→// Result of syncing checkpoints for a user
404→export interface UserCheckpointSyncResult {
405→  reposChecked: number;
406→  reposWithAccess: number;
407→  reposSynced: number;
408→  errors: number;
409→}
410→
411→// Sync checkpoints for all repos a user has access to
412→// This is the repo-centric replacement for the legacy syncCheckpointsForUser
413→export async function syncCheckpointsForUser(
414→  userId: string,
415→  env: CheckpointSyncEnv
416→): Promise<UserCheckpointSyncResult> {
417→  const result: UserCheckpointSyncResult = {
418→    reposChecked: 0,
419→    reposWithAccess: 0,
420→    reposSynced: 0,
421→    errors: 0,
422→  };
423→
424→  // Get user and their token
425→  const user = await env.db.users.findById(userId);
426→
427→  if (!user || !user.github_token_enc) {
428→    log("skip_no_token", { userId });
429→    return result;
430→  }
431→
432→  // Get valid token
433→  let token: string;
434→  try {
435→    const tokenResult = await getValidGitHubToken(env.db, user, {
436→      clientId: env.clientId,
437→      clientSecret: env.clientSecret,
438→      encryptionKey: env.encryptionKey,
439→    }, env.cache);
440→    token = tokenResult.token;
441→  } catch (err) {
442→    log("token_error", { userId, error: errorString(err) });
443→    return result;
444→  }
445→
446→  // Get all repos for this user from the repo-centric schema
447→  const repos = await env.db.repos.getForUser(userId);
448→  result.reposChecked = repos.length;
449→
450→  log("user_sync_started", {
451→    userId,
452→    totalRepos: repos.length,
453→  });
454→
455→  // Filter to repos where app has access
456→  const accessibleRepos = repos.filter((r) => r.app_has_access);
457→  result.reposWithAccess = accessibleRepos.length;
458→
459→  // Process repos in batches to avoid rate limits
460→  const BATCH_SIZE = 5;
461→  for (let i = 0; i < accessibleRepos.length; i += BATCH_SIZE) {
462→    const batch = accessibleRepos.slice(i, i + BATCH_SIZE);
463→
464→    await Promise.all(
465→      batch.map(async (repo) => {
466→        try {
467→          const syncResult = await syncRepoCheckpoints(env.db, repo.id, token);
468→          if (syncResult.status === "ok") {
469→            result.reposSynced++;
470→          }
471→        } catch (err) {
472→          result.errors++;
473→          log("repo_sync_error", {
474→            repoId: repo.id,
475→            fullName: repo.full_name,
476→            error: errorString(err),
477→          });
478→        }
479→      })
480→    );
481→  }
482→
483→  log("user_sync_completed", { userId, ...result });
484→  return result;
485→}
