498→/**
499→ * Sync trails for a repository
500→ * Discovers trails from entire/trails/v1 branch and upserts to database
501→ */
502→export async function syncRepoTrails(
503→  db: Db,
504→  repoId: string,
505→  repoFullName: string,
506→  token: string,
507→): Promise<TrailSyncResult> {
508→  log("trails_sync_start", { repoId, repoFullName });
509→
510→  // Check if trails branch exists
511→  const branchExists = await checkBranchExists(repoFullName, TRAILS_BRANCH, token);
512→  if (!branchExists) {
513→    log("trails_sync_skip", { repoId, reason: "no_trails_branch" });
514→    return { status: "skipped", reason: "no_trails_branch" };
515→  }
516→
517→  // Discover all trail IDs
518→  const trailIds = await discoverTrailsFromBranch(repoFullName, token);
519→  if (trailIds.length === 0) {
520→    log("trails_sync_skip", { repoId, reason: "no_trails" });
521→    return { status: "skipped", reason: "no_trails" };
522→  }
523→
524→  log("trails_discovered", { repoId, count: trailIds.length });
525→
526→  // Fetch trail data in batches
527→  const trailData = await fetchTrailDataBatch(repoFullName, trailIds, token);
528→
529→  // Upsert trails to database
530→  let synced = 0;
531→  for (const [trailId, trail] of trailData) {
532→    try {
533→      await upsertTrail(db, repoId, trail);
534→      synced++;
535→    } catch (err) {
536→      log("trail_upsert_error", {
537→        repoId,
538→        trailId,
539→        error: errorString(err),
540→      });
541→    }
542→  }
543→
544→  log("trails_sync_completed", {
545→    repoId,
546→    discovered: trailIds.length,
547→    synced,
548→  });
549→
550→  return {
551→    status: "ok",
552→    trailsDiscovered: trailIds.length,
553→    trailsSynced: synced,
554→  };
555→}
