557→/**
558→ * Upsert a trail to the database.
559→ * Uses the optional trails namespace (available on Supabase, not yet on PlanetScale).
560→ */
561→async function upsertTrail(
562→  db: Db,
563→  repoId: string,
564→  trail: Trail,
565→): Promise<void> {
566→  if (!db.trails) {
567→    // PlanetScale doesn't have repo_trails table yet - skip DB sync
568→    return;
569→  }
570→
571→  const { metadata, discussion } = trail;
572→
573→  // Calculate comment counts
574→  let commentCount = 0;
575→  let unresolvedCount = 0;
576→  for (const comment of discussion.comments ?? []) {
577→    commentCount += 1 + (comment.replies?.length ?? 0);
578→    if (!comment.resolved) {
579→      unresolvedCount++;
580→    }
581→  }
582→
583→  const row: RepoTrailInsert = {
584→    repo_id: repoId,
585→    trail_id: metadata.trail_id,
586→    branch: metadata.branch,
587→    base: metadata.base,
588→    title: metadata.title,
589→    body: metadata.body || null,
590→    status: metadata.status,
591→    author: metadata.author,
592→    assignees: metadata.assignees,
593→    labels: metadata.labels,
594→    created_at: metadata.created_at,
595→    updated_at: metadata.updated_at,
596→    merged_at: metadata.merged_at,
597→    discussion: discussion as unknown as Json,
598→    comment_count: commentCount,
599→    unresolved_count: unresolvedCount,
600→  };
601→
602→  await db.trails.upsert(row);
603→}
