1208→export async function updateTranscriptBatch(
1209→  db: Kysely<DB>,
1210→  repoId: string,
1211→  updates: Array<{ checkpoint_id: string; transcript_stripped: string }>,
1212→): Promise<number> {
1213→  if (updates.length === 0) return 0;
1214→
1215→  let updated = 0;
1216→  for (let i = 0; i < updates.length; i += BATCH_SIZE) {
1217→    const batch = updates.slice(i, i + BATCH_SIZE);
1218→    for (const { checkpoint_id, transcript_stripped } of batch) {
1219→      try {
1220→        const result = await db
1221→          .updateTable("repo_checkpoints")
1222→          .set({ transcript_stripped: transcript_stripped as unknown as string })
1223→          .where("repo_id", "=", repoId)
1224→          .where("checkpoint_id", "=", checkpoint_id)
1225→          .execute();
1226→        if (result[0] && Number(result[0].numUpdatedRows) > 0) {
1227→          updated++;
1228→        }
1229→      } catch (e) {
1230→        console.log(`${LOG_PREFIX} update_transcript_error`, JSON.stringify({
1231→          checkpoint_id,
1232→          error: String(e),
1233→        }));
1234→      }
1235→    }
1236→  }
1237→  return updated;
1238→}
