205→// Process a batch of search index messages
206→export async function processSearchIndexBatch(
207→  batch: MessageBatch<SearchIndexMessage>,
208→  env: Env,
209→): Promise<void> {
210→  const batchStartTime = Date.now();
211→  const batchId = generateBatchId();
212→
213→  const queueWaitTimes = batch.messages.map(
214→    (msg) => Date.now() - msg.timestamp.getTime(),
215→  );
216→  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;
217→
218→  log("batch_started", {
219→    batchId,
220→    queue: batch.queue,
221→    count: batch.messages.length,
222→    avgQueueWaitMs: avgMs(queueWaitTimes),
223→    maxQueueWaitMs: maxWaitMs,
224→  });
225→
226→  const processingTimes: number[] = [];
227→  let successCount = 0;
228→  let errorCount = 0;
229→  let skippedCount = 0;
230→
231→  for (const msg of batch.messages) {
232→    const msgStartTime = Date.now();
233→    const { repoId, checkpointIds } = msg.body;
234→
235→    // Early return if API keys are missing — don't retry messages that can never succeed
236→    if (!env.TURBOPUFFER_API_KEY || !env.OPENAI_API_KEY) {
237→      log("skip_missing_api_keys", {
238→        batchId,
239→        repoId,
240→        hasTurbopuffer: !!env.TURBOPUFFER_API_KEY,
241→        hasOpenai: !!env.OPENAI_API_KEY,
242→      });
243→      msg.ack();
244→      skippedCount++;
245→      continue;
246→    }
247→
248→    try {
249→      const db = getDb(env);
250→
251→      const repo = await db.repos.getById(repoId);
252→      if (!repo) {
253→        log("skip_repo_not_found", { batchId, repoId });
254→        msg.ack();
255→        skippedCount++;
256→        continue;
257→      }
258→
259→      const checkpoints = await db.checkpoints.getByIds(repoId, checkpointIds);
260→
261→      if (checkpoints.length === 0) {
262→        log("skip_no_checkpoints", { batchId, repoId, requestedIds: checkpointIds.length });
263→        msg.ack();
264→        skippedCount++;
265→        continue;
266→      }
267→
268→      // Ensure transcripts are stored in DB, fetching from GitHub if needed
269→      const transcripts = await ensureTranscriptsStored(
270→        db,
271→        repoId,
272→        repo.full_name,
273→        repo.installation_id,
274→        checkpoints.map((cp) => ({
275→          checkpoint_id: cp.checkpoint_id,
276→          agent: cp.agent ?? "Claude Code",
277→          session_count: cp.session_count ?? 1,
278→        })),
279→        env,
280→        batchId,
281→      );
282→
283→      const indexed = await indexCheckpoints(
284→        env.TURBOPUFFER_API_KEY,
285→        env.OPENAI_API_KEY,
286→        repo.github_id,
287→        checkpoints.map((cp) => ({
288→          checkpoint_id: cp.checkpoint_id,
289→          branch: cp.branch,
290→          agent: cp.agent,
291→          commit_author_username: cp.commit_author_username,
292→          created_at: cp.created_at,
293→          commit_sha: cp.commit_sha,
294→          commit_message: cp.commit_message,
295→          prompt: cp.prompt,
296→          files_touched: cp.files_touched,
297→          transcript: transcripts.get(cp.checkpoint_id) ?? null,
298→        })),
299→      );
300→
301→      const processingMs = Date.now() - msgStartTime;
302→      processingTimes.push(processingMs);
303→
304→      log("message_processed", {
305→        batchId,
306→        repoId,
307→        requested: checkpointIds.length,
308→        found: checkpoints.length,
309→        indexed,
310→        processingMs,
311→        attempt: msg.attempts,
312→      });
313→
314→      msg.ack();
315→      successCount++;
316→    } catch (err) {
317→      const processingMs = Date.now() - msgStartTime;
318→      processingTimes.push(processingMs);
319→      errorCount++;
320→
321→      log("message_error", {
322→        batchId,
323→        repoId,
324→        checkpointCount: checkpointIds.length,
325→        attempt: msg.attempts,
326→        processingMs,
327→        error: err instanceof Error ? err.message : String(err),
328→      });
329→
330→      // Retry on transient failures (max_retries configured in wrangler.jsonc)
331→      msg.retry();
332→    }
333→  }
334→
335→  const totalBatchTimeMs = Date.now() - batchStartTime;
336→
337→  log("batch_complete", {
338→    batchId,
339→    count: batch.messages.length,
340→    successCount,
341→    errorCount,
342→    skippedCount,
343→    totalBatchTimeMs,
344→    avgProcessingMs: avgMs(processingTimes),
345→    throughputPerMin:
346→      totalBatchTimeMs > 0
347→        ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
348→        : 0,
349→  });
350→}
