2343→// Search checkpoints using Turbopuffer BM25 full-text search
2344→repoRoutes.get("/:org/:repo/checkpoints/search", optionalAuth, rateLimitUnauthenticated, async (c) => {
2345→  const userId = c.get("userId") as string | undefined;
2346→
2347→  const org = c.req.param("org");
2348→  const repo = c.req.param("repo");
2349→  const repoFullName = `${org}/${repo}`;
2350→
2351→  const query = c.req.query("q");
2352→  const branch = c.req.query("branch");
2353→
2354→  if (!query || query.trim().length === 0) {
2355→    return c.json({ error: "Query parameter 'q' is required" }, 400);
2356→  }
2357→
2358→  if (branch && !isValidBranchName(branch)) {
2359→    return c.json({ error: "Invalid branch name format" }, 400);
2360→  }
2361→
2362→  try {
2363→    const turbopufferKey = c.env.TURBOPUFFER_API_KEY;
2364→    const openaiKey = c.env.OPENAI_API_KEY;
2365→    if (!turbopufferKey || !openaiKey) {
2366→      return c.json({ error: "Search is not configured" }, 503);
2367→    }
2368→
2369→    const db = getDb(c.env);
2370→
2371→    const repoAccess = await checkRepoAccess(
2372→      db,
2373→      repoFullName,
2374→      userId,
2375→      { requireRepo: true },
2376→    );
2377→    if (repoAccess instanceof Response) return repoAccess;
2378→
2379→    const repoRecord = repoAccess;
2380→
2381→    const searchResults = await searchCheckpoints(
2382→      turbopufferKey,
2383→      openaiKey,
2384→      repoRecord.github_id,
2385→      query.trim(),
2386→      branch ? { branch } : undefined,
2387→    );
2388→
2389→    if (searchResults.length === 0) {
2390→      return c.json({
2391→        checkpoints: [],
2392→        repo_full_name: repoFullName,
2393→        updated_at: new Date().toISOString(),
2394→        from_cache: false,
2395→        app_has_access: repoRecord.app_has_access ?? null,
2396→        session_branch_exists: repoRecord.checkpoints_backfilled_at ? true : null,
2397→      });
2398→    }
2399→
2400→    const checkpointIds = searchResults.map((r) => r.checkpoint_id);
2401→    const dbCheckpoints = await db.checkpoints.getByIds(repoRecord.id, checkpointIds);
2402→
2403→    // Build search metadata from RRF results
2404→    const searchMeta: Record<string, { matchType: "semantic" | "keyword" | "both"; score: number }> = {};
2405→    for (const r of searchResults) {
2406→      const matchType = r.vectorRank != null && r.bm25Rank != null ? "both"
2407→        : r.vectorRank != null ? "semantic" : "keyword";
2408→      searchMeta[r.checkpoint_id] = { matchType, score: r.rrf };
2409→    }
2410→
2411→    // Preserve Turbopuffer relevance ordering
2412→    const byId = new Map(dbCheckpoints.map((row) => [row.checkpoint_id, row]));
2413→    const ordered = checkpointIds
2414→      .map((id) => byId.get(id))
2415→      .filter((row): row is CheckpointWithCommit => row != null);
2416→
2417→    const checkpoints: CheckpointInfo[] = ordered.map(mapCheckpointToInfo);
2418→
2419→    return c.json({
2420→      checkpoints,
2421→      searchMeta,
2422→      repo_full_name: repoFullName,
2423→      updated_at: new Date().toISOString(),
2424→      from_cache: false,
2425→      app_has_access: repoRecord.app_has_access ?? null,
2426→      session_branch_exists: repoRecord.checkpoints_backfilled_at ? true : null,
2427→    });
2428→  } catch (err) {
2429→    if ((err as any)?.status === 404) {
2430→      return c.json({ error: (err as Error).message }, 404);
2431→    }
2432→    if (isGitHubAuthError(err)) {
2433→      return c.json({ error: "GitHub token expired" }, 401);
2434→    }
2435→    console.error(`Failed to search checkpoints for ${repoFullName}:`, err);
2436→    recordSpanError(err);
2437→    return c.json({ error: "Failed to search checkpoints" }, 500);
2438→  }
2439→});
