  1→import {
  2→  useCallback,
  3→  useEffect,
  4→  useMemo,
  5→  useState,
  6→  type ReactNode,
  7→} from "react";
  8→import { useQuery, useQueryClient } from "@tanstack/react-query";
  9→import {
 10→  fetchCurrentUser,
 11→  startGitHubAuth,
 12→  logoutRequest,
 13→  type AuthUser,
 14→} from "./api";
 15→import { AuthContext, type AuthContextValue } from "./hooks/useAuth";
 16→
 17→export function AuthProvider({ children }: { children: ReactNode }) {
 18→  const queryClient = useQueryClient();
 19→
 20→  const [user, setUser] = useState<AuthUser | null>(null);
 21→  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
 22→  const [shouldCheckSession, setShouldCheckSession] = useState<boolean>(true);
 23→
 24→  const persistAuth = useCallback(
 25→    (authUser: AuthUser) => {
 26→      setUser(authUser);
 27→      setIsAuthenticated(true);
 28→      setShouldCheckSession(false);
 29→      queryClient.setQueryData(["auth", "me"], authUser);
 30→    },
 31→    [queryClient],
 32→  );
 33→
 34→  const clearAuth = useCallback(() => {
 35→    setUser(null);
 36→    setIsAuthenticated(false);
 37→    setShouldCheckSession(false);
 38→    queryClient.removeQueries({ queryKey: ["auth"] });
 39→    queryClient.cancelQueries({ queryKey: ["auth"] });
 40→  }, [queryClient]);
 41→
 42→  // GitHub OAuth login - just redirect, no mutation needed
 43→  const login = useCallback(() => {
 44→    startGitHubAuth();
 45→  }, []);
 46→
 47→  const logout = useCallback(async () => {
 48→    try {
 49→      await logoutRequest();
 50→    } catch (error) {
 51→      console.error("Logout error:", error);
 52→    } finally {
 53→      clearAuth();
 54→    }
 55→  }, [clearAuth]);
 56→
 57→  // Check if we have an active session on mount (only once)
 58→  const meQuery = useQuery<AuthUser, Error>({
 59→    queryKey: ["auth", "me"],
 60→    queryFn: fetchCurrentUser,
 61→    enabled: shouldCheckSession,
 62→    retry: false,
 63→    staleTime: Infinity,
 64→    refetchOnMount: false,
 65→    refetchOnWindowFocus: false,
 66→  });
 67→
 68→  // Update auth state when user data is fetched
 69→  useEffect(() => {
 70→    if (meQuery.data && shouldCheckSession) {
 71→      persistAuth(meQuery.data);
 72→    } else if (meQuery.isError && shouldCheckSession) {
 73→      clearAuth();
 74→    }
 75→  }, [
 76→    meQuery.data,
 77→    meQuery.isError,
 78→    shouldCheckSession,
 79→    persistAuth,
 80→    clearAuth,
 81→  ]);
 82→
 83→  const isVerifying = shouldCheckSession || meQuery.isFetching;
 84→
 85→  const value = useMemo<AuthContextValue>(
 86→    () => ({
 87→      isAuthenticated,
 88→      user,
 89→      login,
 90→      logout,
 91→      isLoggingIn: false, // No loading state for redirect-based auth
 92→      loginError: null, // Errors handled by OAuth flow
 93→      isVerifying,
 94→    }),
 95→    [isAuthenticated, user, login, logout, isVerifying],
 96→  );
 97→
 98→  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
 99→}
