 51→
 52→export function CheckpointsPage(props: CheckpointsPageProps) {
 53→  const { org, repo, branch } = props;
 54→  const navigate = useNavigate();
 55→  const queryClient = useQueryClient();
 56→  const [searchQuery, setSearchQuery] = useState("");
 57→  const { data: statusData, error: statusError } = useCheckpointStatusQuery(org, repo);
 58→  const { data, isLoading, error } = useCheckpointsQuery(org, repo, branch);
 59→  const { data: branchesData } = useBranchesQuery(org, repo);
 60→  const repoOptions = useRepoBreadcrumbOptions(org);
 61→
 62→  const handleBranchChange = (newBranch: string | null) => {
 63→    if (!newBranch) return;
 64→    navigate({
 65→      to: "/gh/$org/$repo/checkpoints/$branch",
 66→      params: { org, repo, branch: newBranch },
 67→    });
 68→  };
 69→
 70→  const branches = branchesData?.branches ?? [];
 71→  const defaultBranch = branchesData?.default_branch ?? "main";
 72→
 73→  // Sort branches with default branch first, then create options for Combobox
 74→  const sortedBranches = [...branches].sort((a, b) => {
 75→    if (a === defaultBranch) return -1;
 76→    if (b === defaultBranch) return 1;
 77→    return a.localeCompare(b);
 78→  });
 79→
 80→  const branchOptions: ComboboxOption[] = sortedBranches.map((b) => ({
 81→    id: b,
 82→    label: b,
 83→  }));
 84→  // Debounce search query for API calls
 85→  const [debouncedQuery, setDebouncedQuery] = useState("");
 86→  useEffect(() => {
 87→    const timer = setTimeout(() => setDebouncedQuery(searchQuery.trim()), 300);
 88→    return () => clearTimeout(timer);
 89→  }, [searchQuery]);
 90→
 91→  const { data: searchData, isFetching: isSearching } = useSearchCheckpointsQuery(
 92→    org, repo, debouncedQuery, branch,
 93→  );
 94→
 95→  const isSearchActive = debouncedQuery.length > 0;
 96→  const allCheckpoints = data?.checkpoints ?? [];
 97→  const checkpoints = isSearchActive
 98→    ? (searchData?.checkpoints ?? [])
 99→    : allCheckpoints;
100→
101→  // =============================================================================
102→  // LOCAL DEV ONLY: Fetch from GitHub button
103→  // In local development, the D1 database isn't populated with checkpoint data.
104→  // This button fetches directly from GitHub to allow testing the UI.
105→  // import.meta.env.DEV is false in production builds, so this code is tree-shaken.
106→  // =============================================================================
107→  const isDev = import.meta.env.DEV;
108→  const [isFetchingFromGitHub, setIsFetchingFromGitHub] = useState(false);
109→
110→  const handleFetchFromGitHub = async () => {
111→    setIsFetchingFromGitHub(true);
112→    try {
113→      const response = await fetchCheckpoints(org, repo, branch, {
114→        source: "github",
115→      });
116→      queryClient.setQueryData(
