126→  // =============================================================================
127→
128→  // Use whichever error arrives first (status is faster, catches 404s early)
129→  const anyError = statusError || error;
130→  const isRepoNotFound = anyError?.message.includes("Repository not found");
131→
132→  // Repo-level 404 — render the standard not-found page
133→  if (isRepoNotFound) {
134→    return (
135→      <Page noPadding>
136→        <div className="flex min-h-[calc(100dvh-var(--global-header-height))]">
137→          <NotFoundContent />
138→        </div>
139→      </Page>
140→    );
141→  }
142→
143→  if (isAuthError(anyError)) {
144→    return (
