237→          <CheckpointsList
238→            checkpoints={checkpoints}
239→            navigate={navigate}
240→            isDev={isDev}
241→            isFetchingFromGitHub={isFetchingFromGitHub}
242→            handleFetchFromGitHub={handleFetchFromGitHub}
243→            org={org}
244→            repo={repo}
245→            branch={branch}
246→            searchQuery={isSearchActive ? debouncedQuery : ""}
247→            searchMeta={isSearchActive ? searchData?.searchMeta : undefined}
248→          />
249→        </div>
250→      )}
251→
252→      {/* Empty search results */}
253→      {isSearchActive &&
254→        !isSearching &&
255→        checkpoints.length === 0 &&
256→        searchData && (
257→          <div className="border border-default rounded bg-raised p-8">
258→            <div className="text-center text-muted">
259→              <p className="text-lg font-medium">No matching checkpoints</p>
260→              <p className="mt-2 text-sm max-w-md mx-auto">
261→                No checkpoints match &ldquo;{searchQuery}&rdquo;. Try a different search
262→                term.
263→              </p>
264→            </div>
265→          </div>
266→        )}
267→
268→      {/* Empty state: App doesn't have access */}
269→      {showNoAccess && (
270→        <div className="flex items-center justify-center min-h-[calc(100vh-var(--global-header-height)-120px)]">
271→          <div className="text-center text-muted py-12 px-8">
272→            <p className="text-xl font-semibold text-default">
273→              Grant access to this repository
274→            </p>
275→            <p className="mt-3 text-sm max-w-md mx-auto">
276→              The GitHub App needs access to this repository to track your
277→              Claude Code sessions.
278→            </p>
279→            <p className="mt-6 text-sm">
280→              <a
281→                href={getGitHubInstallationUrl()}
282→                className="text-orange-500 hover:underline"
283→              >
284→                Configure GitHub App access
285→              </a>
286→            </p>
287→            {isDev && (
288→              <div className="mt-4">
289→                <Button
290→                  variant="outline"
291→                  onClick={handleFetchFromGitHub}
292→                  disabled={isFetchingFromGitHub}
293→                >
294→                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
295→                </Button>
296→              </div>
297→            )}
298→          </div>
299→        </div>
300→      )}
301→
302→      {/* Empty state: App has access but no session branch (CLI not used yet) */}
303→      {showCliInstall && (
304→        <div className="flex items-center justify-center min-h-[calc(100vh-var(--global-header-height)-120px)]">
305→          <div>
306→            <CliInstallationSteps />
307→            {isDev && (
308→              <div className="flex justify-center pb-8">
309→                <Button
310→                  variant="outline"
311→                  onClick={handleFetchFromGitHub}
312→                  disabled={isFetchingFromGitHub}
313→                >
314→                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
315→                </Button>
316→              </div>
317→            )}
318→          </div>
319→        </div>
320→      )}
321→
322→      {/* Empty state: App has access and session branch exists, but no checkpoints on this branch */}
323→      {showNoBranchCheckpoints && (
324→        <div className="border border-default rounded bg-raised p-8">
325→          <div className="text-center text-muted">
326→            <p className="text-lg font-medium">
327→              No checkpoints on this branch
328→            </p>
329→            <p className="mt-2 text-sm max-w-md mx-auto">
330→              This repository has Claude Code sessions, but none of them are
331→              linked to commits on the{" "}
332→              <code className="font-mono bg-muted px-1 rounded">
333→                {branch}
334→              </code>{" "}
335→              branch.
336→            </p>
337→            {isDev && (
338→              <div className="mt-4">
339→                <Button
340→                  variant="outline"
341→                  onClick={handleFetchFromGitHub}
342→                  disabled={isFetchingFromGitHub}
343→                >
344→                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
345→                </Button>
346→              </div>
347→            )}
348→          </div>
349→        </div>
350→      )}
351→
352→    </Page>
353→  );
354→}
