397→function CheckpointsList(props: CheckpointsListProps) {
398→  const posthog = usePostHog();
399→  const {
400→    checkpoints,
401→    navigate,
402→    isDev,
403→    handleFetchFromGitHub,
404→    isFetchingFromGitHub,
405→    org,
406→    repo,
407→    branch,
408→    searchQuery,
409→    searchMeta,
410→  } = props;
411→
412→  const isSearch = searchQuery.length > 0;
413→
414→  // Normalize scores relative to top result
415→  const maxScore = searchMeta
416→    ? Math.max(...Object.values(searchMeta).map((m) => m.score), 0)
417→    : 0;
418→
419→  const handleSelect = (index: number) => {
