452→          const checkpointTitle = checkpoint.commitMessage;
453→          const fileCount = checkpoint.fileStats?.length ?? 0;
454→          const meta = searchMeta?.[checkpoint.checkpointId];
455→          const normalizedScore = meta && maxScore > 0
456→            ? Math.round((meta.score / maxScore) * 100)
457→            : 0;
458→
459→          const checkpointHref = `${GH_PATH_PREFIX}/${encodeURIComponent(org)}/${encodeURIComponent(repo)}/checkpoints/${encodeURIComponent(branch)}/${encodeURIComponent(checkpoint.checkpointId)}`;
460→
461→          // Search mode: show filesTouched for keyword/both matches
462→          const showFiles = isSearch && meta
463→            && (meta.matchType === "both" || meta.matchType === "keyword")
464→            && checkpoint.filesTouched
