495→                  </span>
496→                  <span aria-hidden="true" className="text-muted/50">|</span>
497→                  <span className="flex items-center gap-1.5">
498→                    <GitHubAvatar
499→                      username={checkpoint.commitAuthorUsername}
500→                      className="size-4"
501→                    />
502→                    {checkpoint.commitAuthorUsername}
503→                  </span>
504→                  {uniqueAgents.length > 0 && (
505→                    <>
506→                      <span aria-hidden="true" className="text-muted/50">|</span>
507→                      {uniqueAgents.map((agent) => {
508→                        const config = getAgent(agent);
509→                        return (
