import { Hono, type Context } from "hono";
import { isAdmin, isLocalDev, type Env } from "../env";
import type { Variables } from "../env";
import { recordSpanError } from "../lib/telemetry";
import type {
  CachedContributions,
  CachedFollowers,
  CachedStarred,
  CachedWatched,
  CachedRepoCommits,
  CheckpointInfo,
  TranscriptMessage,
  SessionTranscript,
  SessionAttribution,
  CachedTranscript,
  CheckpointSummary,
  TrailMetadata,
  TrailDiscussion,
  TrailCheckpoints,
  TrailInfo,
  TrailComment,
  TrailStatus,
  TrailPriority,
  TrailType,
  TrailReviewer,
} from "../types";
import { getParserForAgent } from "../lib/transcript-parsers";
import { CHECKPOINT_BRANCH, TRAILS_BRANCH } from "../lib/constants";
import { requireAuth, optionalAuth, rateLimitUnauthenticated } from "../lib/middleware";

const VALID_PRIORITIES: TrailPriority[] = ["urgent", "high", "medium", "low", "none"];
const VALID_TYPES: TrailType[] = ["bug", "feature", "chore", "docs", "refactor"];
import {
  fetchUserReposWithForks,
  fetchUserContributions,
  fetchUserFollowers,
  fetchUserStarred,
  fetchUserWatched,
  fetchUserPRs,
  fetchRepoCommits,
  getPermissionLevel,
  fetchFileAtCommit,
  checkBranchExists,
  fetchInstallationRepos,
  fetchUserInstallations,
  isValidCheckpointId,
  isValidBranchName,
  discoverTrailsFromBranch,
  fetchTrailDataBatch,
  generateTrailId,
  generateCommentId,
  createBranchIfNotExists,
  commitTrailFiles,
  updateTrailDiscussion,
  updateTrailMetadata,
  isValidTrailId,
} from "../lib/github";
import { getValidGitHubTokenFromContext, getInstallationToken } from "../lib/token";
import { getDb } from "../lib/db";
import type { Db } from "../lib/db/db-types";
import type {
  GitHubRepoData,
  Repo,
} from "../lib/db/repos";
import type { CheckpointWithCommit } from "../lib/db/checkpoints";
import type { GitHubPRData } from "../lib/db/prs";
import { isSyncInProgress } from "../lib/sync-service";
import { runInBackground } from "../lib/context";
import { searchCheckpoints } from "../lib/turbopuffer";
import { adminRoutes } from "./admin";

/** Map a DB checkpoint row to the API CheckpointInfo shape */
function mapCheckpointToInfo(row: CheckpointWithCommit): CheckpointInfo {
  return {
    commitSha: row.commit_sha,
    commitMessage: row.commit_message,
    commitAuthor: row.commit_author,
    commitAuthorUsername: row.commit_author_username,
    commitDate: row.commit_date,
    additions: row.additions,
    deletions: row.deletions,
    filesChanged: row.files_changed,
    filesTouched: row.files_touched,
    fileStats: row.file_stats,
    checkpointId: row.checkpoint_id,
    createdAt: row.created_at ?? new Date().toISOString(),
    sessions: [
      {
        prompt: row.prompt,
        agent: row.agent ?? "Claude Code",
        steps: row.steps ?? 1,
      },
    ],
    sessionCount: row.session_count ?? 1,
    totalSteps: row.steps ?? 1,
    agents: [row.agent ?? "Claude Code"],
    inputTokens: row.input_tokens,
    cacheCreationTokens: row.cache_creation_tokens,
    cacheReadTokens: row.cache_read_tokens,
    outputTokens: row.output_tokens,
    apiCallCount: row.api_call_count,
    attribution:
      row.attribution_calculated_at != null
        ? {
          calculatedAt: row.attribution_calculated_at,
          agentLines: row.attribution_agent_lines ?? 0,
          humanAdded: row.attribution_human_added ?? 0,
          humanModified: row.attribution_human_modified ?? 0,
          humanRemoved: row.attribution_human_removed ?? 0,
          totalCommitted: row.attribution_total_committed ?? 0,
          agentPercentage: row.attribution_agent_percentage ?? 0,
        }
        : null,
  };
}

export const cacheRoutes = new Hono<{ Bindings: Env; Variables: Variables }>();

// User-specific routes — require authentication (applied per-route to avoid
// Hono middleware bleeding when both sub-routers are mounted at the same path)
const userRoutes = new Hono<{ Bindings: Env; Variables: Variables }>();

// Repo-specific routes — auth optional (public repos accessible without login)
// Middleware applied per-route for the same reason as above.
const repoRoutes = new Hono<{ Bindings: Env; Variables: Variables }>();

// Mount admin routes under /admin/* — apply requireAuth before admin's own guard
userRoutes.use("/admin", requireAuth);
userRoutes.use("/admin/*", requireAuth);
userRoutes.route("/admin", adminRoutes);

// Detect GitHub 401 errors so we can tell the frontend to re-authenticate
// rather than showing a generic 500 error.
// GitHub lib throws errors in two formats:
//   "GitHub API error: 401" / "GitHub GraphQL error: 401"
//   "Failed to fetch <thing>: 401"
function isGitHubAuthError(err: unknown): boolean {
  if (!(err instanceof Error)) return false;
  return /: 401$/.test(err.message);
}

// Helper to check repo access. Returns repo record if user has access.
// Returns null if repo doesn't exist (and requireRepo is false).
// Returns 404 response if unauthorized OR repo required but missing.
// Using 404 for unauthorized prevents fishing for private repo existence.
//
// When userId is undefined (unauthenticated), only public repos are returned.
type RepoRecord = Repo;

async function checkRepoAccess(
  db: Db,
  repoFullName: string,
  userId: string | undefined,
  options: { requireRepo: true },
): Promise<RepoRecord | Response>;
async function checkRepoAccess(
  db: Db,
  repoFullName: string,
  userId: string | undefined,
  options?: { requireRepo?: false },
): Promise<RepoRecord | null | Response>;
async function checkRepoAccess(
  db: Db,
  repoFullName: string,
  userId: string | undefined,
  options: { requireRepo?: boolean } = {},
): Promise<RepoRecord | null | Response> {
  if (userId) {
    // Authenticated: check user_repos join (existing behavior)
    const result = await db.repos.getByFullNameWithAccess(repoFullName, userId);

    if (result.status === "found") {
      return result.repo;
    }

    if (result.status === "not_found") {
      if (options.requireRepo) {
        return new Response(JSON.stringify({ error: "Repository not found" }), {
          status: 404,
          headers: { "Content-Type": "application/json" },
        });
      }
      return null;
    }

    // status === "no_access"
    // Fall back to public repo access for authenticated users too.
    // This ensures signed-in users can view public repos they don't explicitly own.
    const publicRepo = await db.repos.getPublicByFullName(repoFullName);
    if (publicRepo) return publicRepo;

    // Private repo with no access: return 404 to prevent repo fishing.
    return new Response(JSON.stringify({ error: "Repository not found" }), {
      status: 404,
      headers: { "Content-Type": "application/json" },
    });
  }

  // Unauthenticated: only serve public repos (hardcoded is_private = false)
  const repo = await db.repos.getPublicByFullName(repoFullName);
  if (!repo) {
    if (options.requireRepo) {
      return new Response(JSON.stringify({ error: "Repository not found" }), {
        status: 404,
        headers: { "Content-Type": "application/json" },
      });
    }
    return null;
  }
  return repo;
}

async function getInstallationTokenForRepo(
  db: Db,
  env: Env,
  repo: RepoRecord | null,
): Promise<string | undefined> {
  if (!repo?.installation_id) return undefined;

  const githubInstallationId = await db.installations.getGithubId(repo.installation_id);
  if (!githubInstallationId) return undefined;

  try {
    return await getInstallationToken(
      githubInstallationId,
      { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
      env.ENTIRE_CACHE,
    );
  } catch {
    return undefined;
  }
}

interface RepoRequestTokenResult {
  token: string | null;
  response?: Response;
}

async function getGitHubTokenForRepoRequest(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  db: Db,
  userId: string | undefined,
  repo: RepoRecord | null,
): Promise<RepoRequestTokenResult> {
  if (userId) {
    const user = await db.users.getWithCache(c.env.ENTIRE_CACHE, userId);
    if (!user) {
      return {
        token: null,
        response: new Response(JSON.stringify({ error: "User not found" }), {
          status: 404,
          headers: { "Content-Type": "application/json" },
        }),
      };
    }

    if (user.github_token_enc) {
      const result = await getValidGitHubTokenFromContext(c, db, user);
      return { token: result.token };
    }
  }

  const installationToken = await getInstallationTokenForRepo(db, c.env, repo);
  return { token: installationToken ?? null };
}

// Result type for local dev sync
interface LocalDevSyncResult {
  repoRecord: RepoRecord | null;
  checkpoints: CheckpointWithCommit[];
}

// Helper for local dev: fetches repo from GitHub if needed, syncs checkpoints, returns data
// Used when ?source=github is passed (webhooks don't fire in local dev)
async function fetchRepoWithSyncForLocalDev(
  db: Db,
  repoFullName: string,
  userId: string,
  branch: string,
  limit: number,
  getGitHubToken: () => Promise<string | null>,
): Promise<LocalDevSyncResult | Response> {
  // Check repo access first
  const repoAccess = await checkRepoAccess(db, repoFullName, userId);
  if (repoAccess instanceof Response) return repoAccess;
  let repoRecord = repoAccess;

  // If repo not in DB, create it from GitHub API
  if (!repoRecord) {
    const token = await getGitHubToken();
    if (!token) {
      return new Response(
        JSON.stringify({ error: "GitHub token required for this operation" }),
        { status: 403, headers: { "Content-Type": "application/json" } },
      );
    }

    const repoResponse = await fetch(
      `https://api.github.com/repos/${repoFullName}`,
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.github+json",
          "User-Agent": "entire-api",
        },
      },
    );

    if (repoResponse.ok) {
      const ghRepo = (await repoResponse.json()) as {
        id: number;
        name: string;
        full_name: string;
        description: string | null;
        html_url: string;
        language: string | null;
        stargazers_count: number;
        fork: boolean;
        private: boolean;
        pushed_at: string | null;
      };

      await db.repos.upsert({
        github_id: ghRepo.id,
        full_name: ghRepo.full_name,
        name: ghRepo.name,
        description: ghRepo.description,
        html_url: ghRepo.html_url,
        language: ghRepo.language,
        stargazers_count: ghRepo.stargazers_count,
        is_fork: ghRepo.fork,
        is_private: ghRepo.private,
        pushed_at: ghRepo.pushed_at,
      });

      repoRecord = await db.repos.getByFullName(repoFullName);
    }
  }

  // Trigger sync and fetch checkpoints
  if (repoRecord) {
    const token = await getGitHubToken();
    if (!token) {
      return new Response(
        JSON.stringify({ error: "GitHub token required for this operation" }),
        { status: 403, headers: { "Content-Type": "application/json" } },
      );
    }

    const { syncRepoCheckpoints } = await import("../lib/repo-sync-service");
    await syncRepoCheckpoints(db, repoRecord.id, token, {
      skipAppInstallationCheck: true,
      extraBranches: [branch],
    });

    const checkpoints = await db.checkpoints.getForBranch(
      repoRecord.id,
      branch,
      { limit },
    );
    return { repoRecord, checkpoints };
  }

  return { repoRecord: null, checkpoints: [] };
}

// Get repos from database (auto-fetches from GitHub on first visit)
userRoutes.get("/repos", requireAuth, async (c) => {
  const userId = c.get("userId");

  try {
    // Check if user has ever synced repos (use KV-cached user to avoid DB roundtrip)
    const db = getDb(c.env);
    const user = await db.users.getWithCache(c.env.ENTIRE_CACHE, userId);
    if (!user) {
      return c.json({ error: "User not found" }, 404);
    }
    if (!user.github_login) {
      return c.json({ error: "User has no GitHub login" }, 400);
    }

    // If never synced, handle based on environment
    if (!user.repos_synced_at) {
      // In production, background job handles this - return empty and let client poll
      if (!isLocalDev(c.env)) {
        console.log(
          `First visit for user ${user.github_login}, repos syncing in background`,
        );
        return c.json({
          repos: [],
          updated_at: new Date().toISOString(),
          from_db: false,
          syncing: true, // Indicate sync is in progress
        });
      }

      // Local development: fetch synchronously (no background jobs)
      console.log(
        `[Local dev] First visit for user ${user.github_login}, fetching repos from GitHub`,
      );

      let token: string | undefined;
      if (user.github_token_enc) {
        const result = await getValidGitHubTokenFromContext(c, db, user);
        token = result.token;
      }

      // Fetch user repos and installation repos in parallel
      const installationsResult = token
        ? await fetchUserInstallations(token)
        : { installations: [], error: false };

      // Check for installations fetch error - don't proceed with partial data
      // as this would incorrectly set app_has_access = false for all repos
      if (installationsResult.error) {
        console.error(
          `[Local dev] Failed to fetch installations for user ${user.github_login}`,
        );
        return c.json({ error: "Failed to fetch installations" }, 500);
      }

      const [githubRepos, ...installationReposResults] = await Promise.all([
        fetchUserReposWithForks(user.github_login, token),
        ...installationsResult.installations.map((inst) =>
          fetchInstallationRepos(inst.id, token!),
        ),
      ]);

      // Build map of repos by github_id, starting with user repos (they have permission info)
      const reposByGithubId = new Map<number, GitHubRepoData>();
      for (const r of githubRepos) {
        reposByGithubId.set(r.id, {
          github_id: r.id,
          name: r.name,
          full_name: r.full_name,
          description: r.description,
          html_url: r.html_url,
          language: r.language,
          stargazers_count: r.stargazers_count,
          is_fork: r.fork,
          is_private: r.private,
          pushed_at: r.pushed_at || r.updated_at,
          default_branch: r.default_branch,
          permission: getPermissionLevel(r.permissions),
        });
      }

      // Add installation repos that aren't already in the map
      const installationRepoIds = new Set<number>();
      for (const repos of installationReposResults) {
        if (repos) {
          for (const repo of repos) {
            installationRepoIds.add(repo.github_id);
            if (!reposByGithubId.has(repo.github_id)) {
              reposByGithubId.set(repo.github_id, {
                github_id: repo.github_id,
                name: repo.name,
                full_name: repo.full_name,
                description: repo.description,
                html_url: repo.html_url,
                language: repo.language,
                stargazers_count: repo.stargazers_count,
                is_fork: repo.is_fork,
                is_private: repo.is_private,
                pushed_at: repo.pushed_at,
                default_branch: repo.default_branch,
                permission: "read",
              });
            }
          }
        }
      }

      // Convert map to array for upsert
      const reposToUpsert = Array.from(reposByGithubId.values());

      // Upsert repos to database with installation repo IDs for app_has_access
      await db.repos.upsertForUser(
        userId,
        reposToUpsert,
        installationRepoIds,
        c.env.ENTIRE_CACHE,
      );

      const now = new Date().toISOString();

      // Return repos (filter out forks unless user explicitly granted app access)
      const repos = reposToUpsert
        .filter((r) => !r.is_fork || installationRepoIds.has(r.github_id))
        .map((r) => ({
          name: r.name,
          full_name: r.full_name,
          description: r.description,
          html_url: r.html_url,
          stargazers_count: r.stargazers_count,
          language: r.language,
          private: r.is_private,
          updated_at: r.pushed_at || now,
          default_branch: r.default_branch ?? "main",
          permission: r.permission,
          checkpoint_count: null, // Not yet synced
        }));

      return c.json({
        repos,
        updated_at: now,
        from_db: false, // Fetched fresh from GitHub
      });
    }

    // Normal path: read from database
    const dbRepos = await db.repos.getForUser(userId);

    // Transform DB format to API format (filter out forks unless user explicitly granted app access)
    const repos = dbRepos
      .filter((r) => !r.is_fork || r.app_has_access)
      .map((r) => ({
        name: r.name,
        full_name: r.full_name,
        description: r.description,
        html_url: r.html_url,
        stargazers_count: r.stargazers_count,
        language: r.language,
        private: r.is_private,
        updated_at: r.pushed_at || r.synced_at || new Date().toISOString(),
        default_branch: r.default_branch ?? "main",
        permission: r.permission,
        checkpoint_count: r.checkpoint_count ?? 0,
      }));

    // Get last sync time from first repo (they all have same synced_at after a sync)
    const lastSyncedAt = dbRepos.length > 0 ? dbRepos[0].synced_at : null;

    return c.json({
      repos,
      updated_at: lastSyncedAt || new Date().toISOString(),
      from_db: true,
    });
  } catch (err) {
    console.error("Failed to get repos from DB:", err);
    recordSpanError(err);
    return c.json({ error: "Failed to fetch repos" }, 500);
  }
});

// Sync repos from GitHub to database (dev only)
userRoutes.post("/repos/sync", requireAuth, async (c) => {
  if (!isLocalDev(c.env)) {
    return c.notFound();
  }

  const userId = c.get("userId");

  try {
    const db = getDb(c.env);
    const user = await db.users.getWithCache(c.env.ENTIRE_CACHE, userId);
    if (!user) {
      return c.json({ error: "User not found" }, 404);
    }
    if (!user.github_login) {
      return c.json({ error: "User has no GitHub login" }, 400);
    }

    let token: string | undefined;
    if (user.github_token_enc) {
      const result = await getValidGitHubTokenFromContext(c, db, user);
      token = result.token;
    }

    // Fetch installations to get installation repos
    // If this fails, we continue with OAuth repos only (graceful degradation)
    const installationsResult = token
      ? await fetchUserInstallations(token)
      : { installations: [], error: false };

    if (installationsResult.error) {
      console.warn(
        `Failed to fetch installations for user ${user.github_login}, continuing with OAuth repos only`,
      );
    }

    // Fetch user repos and installation repos in parallel
    const [githubRepos, ...installationReposResults] = await Promise.all([
      fetchUserReposWithForks(user.github_login, token),
      ...installationsResult.installations.map((inst) =>
        fetchInstallationRepos(inst.id, token!),
      ),
    ]);

    // Build map of repos by github_id, starting with user repos (they have permission info)
    const reposByGithubId = new Map<number, GitHubRepoData>();
    for (const r of githubRepos) {
      reposByGithubId.set(r.id, {
        github_id: r.id,
        name: r.name,
        full_name: r.full_name,
        description: r.description,
        html_url: r.html_url,
        language: r.language,
        stargazers_count: r.stargazers_count,
        is_fork: r.fork,
        is_private: r.private,
        pushed_at: r.pushed_at || r.updated_at,
        default_branch: r.default_branch,
        permission: getPermissionLevel(r.permissions),
      });
    }

    // Add installation repos that aren't already in the map
    const installationRepoIds = new Set<number>();
    for (const repos of installationReposResults) {
      if (repos) {
        for (const repo of repos) {
          installationRepoIds.add(repo.github_id);
          if (!reposByGithubId.has(repo.github_id)) {
            reposByGithubId.set(repo.github_id, {
              github_id: repo.github_id,
              name: repo.name,
              full_name: repo.full_name,
              description: repo.description,
              html_url: repo.html_url,
              language: repo.language,
              stargazers_count: repo.stargazers_count,
              is_fork: repo.is_fork,
              is_private: repo.is_private,
              pushed_at: repo.pushed_at,
              default_branch: repo.default_branch,
              permission: "read",
            });
          }
        }
      }
    }

    // Convert map to array for upsert
    const reposToUpsert = Array.from(reposByGithubId.values());

    // Upsert all repos with installation repo IDs for app_has_access
    await db.repos.upsertForUser(
      userId,
      reposToUpsert,
      installationRepoIds,
      c.env.ENTIRE_CACHE,
    );

    // Delete repos that no longer exist (include both OAuth and installation repos)
    const currentGithubIds = Array.from(reposByGithubId.keys());
    await db.repos.deleteStaleForUser(userId, currentGithubIds);

    // Get non-fork repos for PRs (include forks with explicit app access)
    const nonForkRepos = reposToUpsert.filter((r) => !r.is_fork || installationRepoIds.has(r.github_id));
    const repoNames = nonForkRepos.map((r) => r.full_name);

    // Record sync start time before fetching PRs from GitHub
    // This prevents race conditions with webhooks that may insert PRs during sync
    const syncStartTime = new Date().toISOString();

    // Fetch PRs from GitHub
    const prs = await fetchUserPRs(repoNames, token);

    // Persist PRs to database
    const prData: GitHubPRData[] = prs.map((pr) => ({
      github_pr_id: pr.id,
      number: pr.number,
      title: pr.title,
      html_url: pr.html_url,
      state: pr.state,
      draft: pr.draft,
      created_at: pr.created_at,
      updated_at: pr.updated_at,
      repo_full_name: pr.repo_full_name,
    }));
    await db.prs.upsertPRsForUser(userId, prData);

    // Delete PRs that are no longer open (only those that existed before sync started)
    const currentPRIds = prs.map((pr) => pr.id);
    await db.prs.deleteStalePRsForUser(
      userId,
      currentPRIds,
      syncStartTime,
    );

    const now = new Date().toISOString();

    // Return the synced repos with PRs
    // checkpoint_count is null until checkpoint sync runs (indicates "unknown" vs "zero")
    const repos = nonForkRepos.map((r) => ({
      name: r.name,
      full_name: r.full_name,
      description: r.description,
      html_url: r.html_url,
      stargazers_count: r.stargazers_count,
      language: r.language,
      private: r.is_private,
      updated_at: r.pushed_at || new Date().toISOString(),
      permission: r.permission,
      checkpoint_count: null,
    }));

    return c.json({
      repos,
      prs,
      updated_at: now,
      synced: true,
      total_synced: reposToUpsert.length,
    });
  } catch (err) {
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error("Failed to sync repos:", err);
    recordSpanError(err);
    return c.json({ error: "Failed to sync repos" }, 500);
  }
});

// Get cached contributions (stale-while-revalidate)
userRoutes.get("/contrib", requireAuth, async (c) => {
  const userId = c.get("userId");

  const cacheKey = `contrib:${userId}`;

  // Try cache first
  const cached = await c.env.ENTIRE_CACHE.get<CachedContributions>(
    cacheKey,
    "json",
  );

  if (cached) {
    return c.json({
      ...cached,
      from_cache: true,
    });
  }

  // No cache - fetch fresh data
  try {
    const db = getDb(c.env);
    const user = await db.users.getWithCache(c.env.ENTIRE_CACHE, userId);
    if (!user) {
      return c.json({ error: "User not found" }, 404);
    }
    if (!user.github_login) {
      return c.json({ error: "User has no GitHub login" }, 400);
    }

    let token: string | undefined;
    if (user.github_token_enc) {
      const result = await getValidGitHubTokenFromContext(c, db, user);
      token = result.token;
    }

    const contributions = await fetchUserContributions(
      user.github_login,
      token,
    );

    const data: CachedContributions = {
      ...contributions,
      updated_at: new Date().toISOString(),
    };

    await c.env.ENTIRE_CACHE.put(cacheKey, JSON.stringify(data), {
      expirationTtl: 60 * 60 * 24, // 24h TTL
    });

    return c.json({ ...data, from_cache: false });
  } catch (err) {
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error("Failed to fetch contributions:", err);
    recordSpanError(err);
    return c.json({ error: "Failed to fetch contributions" }, 500);
  }
});

