// Update trail metadata (e.g. status)
const VALID_TRAIL_STATUSES: TrailStatus[] = ["draft", "open", "in_progress", "in_review", "merged", "closed"];

repoRoutes.patch("/:org/:repo/trails/:trailId", requireAuth, requireTrailsAdmin, async (c) => {
  const userId = c.get("userId");

  const org = c.req.param("org");
  const repo = c.req.param("repo");
  const trailId = c.req.param("trailId");
  const repoFullName = `${org}/${repo}`;

  if (!isValidTrailId(trailId)) {
    return c.json({ error: "Invalid trail ID format" }, 400);
  }

  try {
    const db = getDb(c.env);

    // Check repo access
    const repoAccess = await checkRepoAccess(db, repoFullName, userId, { requireRepo: true });
    if (repoAccess instanceof Response) return repoAccess;

    const user = await db.users.findById(userId);
    if (!user) {
      return c.json({ error: "User not found" }, 404);
    }

    // Get token - prefer installation token, fall back to user's OAuth token
    let token: string | undefined;

    if (repoAccess.installation_id) {
      const githubInstallationId = await db.installations.getGithubId(repoAccess.installation_id);
      if (githubInstallationId) {
        token = await getInstallationToken(
          githubInstallationId,
          {
            appId: c.env.GITHUB_CLIENT_ID,
            privateKey: c.env.GITHUB_APP_PRIVATE_KEY,
          },
          c.env.ENTIRE_CACHE
        );
      }
    }

    if (!token && user.github_token_enc) {
      const result = await getValidGitHubTokenFromContext(c, db, user);
      token = result.token;
    }

    if (!token) {
      return c.json({ error: "GitHub token required" }, 401);
    }

    // Parse and validate request body
    const body = await c.req.json<{
      status?: string;
      title?: string;
      body?: string;
      assignees?: string[];
      priority?: string;
      type?: string;
      reviewers?: TrailReviewer[];
    }>();

    if (!body.status && body.title === undefined && body.body === undefined && body.assignees === undefined
      && body.priority === undefined && body.type === undefined && body.reviewers === undefined) {
      return c.json({ error: "At least one field is required" }, 400);
    }

    if (body.status && !VALID_TRAIL_STATUSES.includes(body.status as TrailStatus)) {
      return c.json({ error: `Invalid status. Must be one of: ${VALID_TRAIL_STATUSES.join(", ")}` }, 400);
    }

    if (body.title !== undefined && !body.title.trim()) {
      return c.json({ error: "Title cannot be empty" }, 400);
    }

    if (body.priority !== undefined && !VALID_PRIORITIES.includes(body.priority as TrailPriority)) {
      return c.json({ error: `Invalid priority. Must be one of: ${VALID_PRIORITIES.join(", ")}` }, 400);
    }

    if (body.type !== undefined && body.type !== null && !VALID_TYPES.includes(body.type as TrailType)) {
      return c.json({ error: `Invalid type. Must be one of: ${VALID_TYPES.join(", ")}` }, 400);
    }

    // Fetch current trail data
    const trailData = await fetchTrailDataBatch(repoFullName, [trailId], token);
    const trail = trailData.get(trailId);

    if (!trail) {
      return c.json({ error: "Trail not found" }, 404);
    }

    // Apply updates
    const updatedMetadata: TrailMetadata = {
      ...trail.metadata,
      updated_at: new Date().toISOString(),
    };

    const changes: string[] = [];
    if (body.status) {
      changes.push(`status: ${trail.metadata.status} → ${body.status}`);
      updatedMetadata.status = body.status as TrailStatus;
    }
    if (body.title !== undefined) {
      changes.push("title");
      updatedMetadata.title = body.title.trim();
    }
    if (body.body !== undefined) {
      changes.push("body");
      updatedMetadata.body = body.body ?? "";
    }
    if (body.assignees !== undefined) {
      changes.push("assignees");
      updatedMetadata.assignees = body.assignees;
    }
    if (body.priority !== undefined) {
      changes.push(`priority: ${body.priority}`);
      updatedMetadata.priority = body.priority as TrailPriority;
    }
    if (body.type !== undefined) {
      changes.push(`type: ${body.type}`);
      updatedMetadata.type = (body.type as TrailType) || undefined;
    }
    if (body.reviewers !== undefined) {
      if (!Array.isArray(body.reviewers)) {
        return c.json({ error: "reviewers must be an array" }, 400);
      }
      changes.push("reviewers");
      updatedMetadata.reviewers = body.reviewers;
    }

    await updateTrailMetadata(
      repoFullName,
      trailId,
      updatedMetadata,
      token,
      `Update trail ${changes.join(", ")}`
    );

    // Calculate comment counts from discussion data
    let commentCount = 0;
    let unresolvedCount = 0;
    for (const comment of trail.discussion.comments ?? []) {
      commentCount += 1 + (comment.replies?.length ?? 0);
      if (!comment.resolved) {
        unresolvedCount++;
      }
    }

    // Get checkpoint count from DB
    let checkpointCount = 0;
    try {
      checkpointCount = await db.checkpoints.countForBranch(repoAccess.id, updatedMetadata.branch);
    } catch {
      // Ignore errors - just use 0
    }

    // Return full TrailInfo with computed fields
    return c.json({
      trail: {
        trail_id: trailId,
        branch: updatedMetadata.branch,
        base: updatedMetadata.base,
        title: updatedMetadata.title,
        body: updatedMetadata.body ?? "",
        status: updatedMetadata.status,
        author: updatedMetadata.author,
        assignees: updatedMetadata.assignees,
        labels: updatedMetadata.labels,
        created_at: updatedMetadata.created_at,
        updated_at: updatedMetadata.updated_at,
        merged_at: updatedMetadata.merged_at,
        priority: updatedMetadata.priority ?? "none",
        type: updatedMetadata.type ?? null,
        reviewers: updatedMetadata.reviewers ?? [],
        comment_count: commentCount,
        unresolved_count: unresolvedCount,
        checkpoint_count: checkpointCount,
      },
    });
  } catch (err) {
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error(`Failed to update trail ${trailId}:`, err);
    recordSpanError(err);
    return c.json({ error: "Failed to update trail" }, 500);
  }
});

