import { Hono, type Context } from "hono";
import { isAdmin, isLocalDev, type Env } from "../env";
import type { Variables } from "../env";
import { recordSpanError } from "../lib/telemetry";
import type {
  CachedContributions,
  CachedFollowers,
  CachedStarred,
  CachedWatched,
  CachedRepoCommits,
  CheckpointInfo,
  TranscriptMessage,
  SessionTranscript,
  SessionAttribution,
  CachedTranscript,
  CheckpointSummary,
  TrailMetadata,
