// Also triggers background sync if needed (visit-triggered sync)
userRoutes.get("/sync-status", requireAuth, async (c) => {
  const userId = c.get("userId");

  // Update last_visited_at timestamp (for dead-user filtering)
  const db = getDb(c.env);
  await db.users.updateLastVisitedAt(userId);

  // Get last update timestamp from KV
  const lastUpdate = await c.env.ENTIRE_CACHE.get(
    `sync:lastUpdate:${userId}`,
  );

  // Check if sync is already in progress
  const syncInProgress = await isSyncInProgress(
    c.env.ENTIRE_CACHE,
    userId,
  );

  // Note: In the new repo-centric architecture, repos are synced immediately
  // via POST /repos/sync. This endpoint just reports status for frontend polling.
  // Checkpoint syncs are handled per-repo via REPO_SYNC_QUEUE.

  return c.json({
    lastUpdate: lastUpdate ? parseInt(lastUpdate, 10) : null,
    syncInProgress,
  });
});

// Get checkpoints for the current user (for dashboard)
userRoutes.get("/user/checkpoints", requireAuth, async (c) => {
  const userId = c.get("userId");

  // Parse query params
  const timeframe = c.req.query("timeframe") || "last-6-months";
  const limitParam = c.req.query("limit");
  const parsedLimit = limitParam ? parseInt(limitParam, 10) : 500;
  const limit =
    Number.isNaN(parsedLimit) || parsedLimit <= 0
      ? 500
      : Math.min(parsedLimit, 1000);

  // Calculate date range based on timeframe
  const now = new Date();
  let startDate: Date;
  const endDate = now;

  switch (timeframe) {
    case "last-month":
      startDate = new Date(now);
      startDate.setDate(startDate.getDate() - 30);
      break;
    case "last-3-months":
      startDate = new Date(now);
      startDate.setMonth(startDate.getMonth() - 3);
      break;
    case "last-6-months":
    default:
      startDate = new Date(now);
      startDate.setMonth(startDate.getMonth() - 6);
      break;
  }

  try {
    // Look up user's github_id from session userId (uses KV cache)
    const db = getDb(c.env);
    const user = await db.users.getWithCache(c.env.ENTIRE_CACHE, userId);
    if (!user) {
      return c.json({ error: "User not found" }, 404);
    }

    // Check if any repos with app access are still pending initial checkpoint sync
    const pendingSyncCount = await db.repos.countPendingSync(userId);

    const syncing = (pendingSyncCount ?? 0) > 0;

    const checkpoints = await db.checkpoints.getByUser(
      userId,
      user.github_id,
      startDate.toISOString(),
      endDate.toISOString(),
      limit,
    );

    return c.json({
      checkpoints,
      timeframe,
      updated_at: new Date().toISOString(),
      syncing,
    });
  } catch (err) {
    console.error("Failed to fetch user checkpoints:", err);
    recordSpanError(err);
    return c.json({ error: "Failed to fetch checkpoints" }, 500);
  }
});

