      return c.json({ error: "GitHub token required" }, 401);
    }

    // Fetch the specific trail
    const trailData = await fetchTrailDataBatch(repoFullName, [trailId], token);
    const trail = trailData.get(trailId);

    if (!trail) {
      return c.json({ error: "Trail not found" }, 404);
    }

    const { metadata, discussion, checkpoints: trailCheckpoints } = trail;

    // Calculate comment counts
    let commentCount = 0;
    let unresolvedCount = 0;
    for (const comment of discussion.comments ?? []) {
      commentCount += 1 + (comment.replies?.length ?? 0);
      if (!comment.resolved) {
        unresolvedCount++;
      }
    }

    // Fetch checkpoints: use explicit IDs from checkpoints.json if available,
    // otherwise fall back to branch-based lookup (same as checkpoints page)
    const checkpointIds = trailCheckpoints.checkpoints.map((cp) => cp.checkpoint_id);
    let enrichedCheckpoints: CheckpointInfo[] = [];
    try {
      let dbCheckpoints;
      if (checkpointIds.length > 0) {
        try {
          dbCheckpoints = await db.checkpoints.getByIds(repoAccess.id, checkpointIds);
        } catch {
          // getByIds not implemented (e.g. Supabase) — fall back to branch query
          dbCheckpoints = await db.checkpoints.getForBranch(repoAccess.id, metadata.branch);
        }
      } else {
        dbCheckpoints = await db.checkpoints.getForBranch(repoAccess.id, metadata.branch);
      }
      enrichedCheckpoints = dbCheckpoints.map(mapCheckpointToInfo);
    } catch {
      // Ignore errors - return empty checkpoints
    }

    const trailInfo: TrailInfo = {
      ...metadata,
      body: metadata.body ?? "",
      priority: metadata.priority ?? "none",
      type: metadata.type ?? null,
      reviewers: metadata.reviewers ?? [],
      comment_count: commentCount,
      unresolved_count: unresolvedCount,
      checkpoint_count: enrichedCheckpoints.length,
    };

    return c.json({
      trail: trailInfo,
      discussion: discussion,
      checkpoints: enrichedCheckpoints,
    });
  } catch (err) {
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error(`Failed to fetch trail ${trailId}:`, err);
    recordSpanError(err);
    return c.json({ error: "Failed to fetch trail" }, 500);
  }
});

