// Search checkpoints using Turbopuffer hybrid search (admin-only)
repoRoutes.get("/:org/:repo/checkpoints/search", requireAuth, async (c) => {
  const userId = c.get("userId");

  // Admin-only: non-admins use client-side filtering
  const db = getDb(c.env);
  const user = await db.users.findById(userId);
  if (!user || !isAdmin(c.env, user.is_admin ?? false)) {
    return c.json({ error: "Forbidden" }, 403);
  }

  const org = c.req.param("org");
  const repo = c.req.param("repo");
  const repoFullName = `${org}/${repo}`;

  const query = c.req.query("q");
  const branch = c.req.query("branch");

  if (!query || query.trim().length === 0) {
    return c.json({ error: "Query parameter 'q' is required" }, 400);
  }

  if (branch && !isValidBranchName(branch)) {
    return c.json({ error: "Invalid branch name format" }, 400);
  }

  try {
    const turbopufferKey = c.env.TURBOPUFFER_API_KEY;
    const openaiKey = c.env.OPENAI_API_KEY;
    if (!turbopufferKey || !openaiKey) {
      return c.json({ error: "Search is not configured" }, 503);
    }

    const repoAccess = await checkRepoAccess(
      db,
      repoFullName,
      userId,
      { requireRepo: true },
    );
    if (repoAccess instanceof Response) return repoAccess;

    const repoRecord = repoAccess;

    const searchResults = await searchCheckpoints(
      turbopufferKey,
      openaiKey,
      repoRecord.github_id,
      query.trim(),
      branch ? { branch } : undefined,
    );

    if (searchResults.length === 0) {
      return c.json({
        checkpoints: [],
        repo_full_name: repoFullName,
        updated_at: new Date().toISOString(),
        from_cache: false,
        app_has_access: repoRecord.app_has_access ?? null,
        session_branch_exists: repoRecord.checkpoints_backfilled_at ? true : null,
      });
    }

    const checkpointIds = searchResults.map((r) => r.checkpoint_id);
    const dbCheckpoints = await db.checkpoints.getByIds(repoRecord.id, checkpointIds);

    // Build search metadata from RRF results
    const searchMeta: Record<string, { matchType: "semantic" | "keyword" | "both"; score: number }> = {};
    for (const r of searchResults) {
      const matchType = r.vectorRank != null && r.bm25Rank != null ? "both"
        : r.vectorRank != null ? "semantic" : "keyword";
      searchMeta[r.checkpoint_id] = { matchType, score: r.rrf };
    }

    // Preserve Turbopuffer relevance ordering
    const byId = new Map(dbCheckpoints.map((row) => [row.checkpoint_id, row]));
    const ordered = checkpointIds
      .map((id) => byId.get(id))
      .filter((row): row is CheckpointWithCommit => row != null);

    const checkpoints: CheckpointInfo[] = ordered.map(mapCheckpointToInfo);

    return c.json({
      checkpoints,
      searchMeta,
      repo_full_name: repoFullName,
      updated_at: new Date().toISOString(),
      from_cache: false,
      app_has_access: repoRecord.app_has_access ?? null,
      session_branch_exists: repoRecord.checkpoints_backfilled_at ? true : null,
    });
  } catch (err) {
    if ((err as any)?.status === 404) {
      return c.json({ error: (err as Error).message }, 404);
    }
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error(`Failed to search checkpoints for ${repoFullName}:`, err);
    recordSpanError(err);
    return c.json({ error: "Failed to search checkpoints" }, 500);
  }
});

// Resolve a checkpoint by ID - finds which branches it exists on
// Useful when the original branch has been deleted (e.g., after PR merge)
// Returns redirect info if the checkpoint exists on other branches
repoRoutes.get("/:org/:repo/checkpoints/resolve/:checkpointId", optionalAuth, rateLimitUnauthenticated, async (c) => {
  const userId = c.get("userId") as string | undefined;

  const org = c.req.param("org");
  const repo = c.req.param("repo");
  const checkpointId = c.req.param("checkpointId");
  const repoFullName = `${org}/${repo}`;

  // Optional: the branch the user originally requested (for determining if redirect needed)
  const requestedBranch = c.req.query("branch");

  // Validate branch name format if provided
  if (requestedBranch && !isValidBranchName(requestedBranch)) {
    return c.json({ error: "Invalid branch name format" }, 400);
  }

  try {
    const db = getDb(c.env);

    // Check repo access (returns 404 if unauthorized or repo doesn't exist)
    const repoRecord = await checkRepoAccess(db, repoFullName, userId, {
      requireRepo: true,
    });
    if (repoRecord instanceof Response) return repoRecord;

    // Find checkpoint across all branches
    const location = await db.checkpoints.findById(repoRecord.id, checkpointId);

    if (!location) {
      return c.json({ error: "Checkpoint not found" }, 404);
    }

    // Determine if a redirect is needed
    const needsRedirect =
      requestedBranch && !location.branches.includes(requestedBranch);

    // Suggest redirect to default branch if available, otherwise first available branch
    const suggestedBranch = location.default_branch || location.branches[0];

    // Transform commit to CheckpointInfo format
    const commit = location.commit;
    const checkpoint = commit
      ? {
        commitSha: commit.commit_sha,
        commitMessage: commit.commit_message,
        commitAuthor: commit.commit_author,
        commitAuthorUsername: commit.commit_author_username,
        commitDate: commit.commit_date,
        additions: commit.additions,
        deletions: commit.deletions,
        filesChanged: commit.files_changed,
        filesTouched: commit.files_touched,
        fileStats: commit.file_stats,
        checkpointId: commit.checkpoint_id,
        createdAt: commit.created_at ?? new Date().toISOString(),
        sessions: [
          {
            prompt: commit.prompt,
            agent: commit.agent ?? "Claude Code",
            steps: commit.steps ?? 1,
          },
        ],
        sessionCount: commit.session_count ?? 1,
        totalSteps: commit.steps ?? 1,
        agents: [commit.agent ?? "Claude Code"],
        inputTokens: commit.input_tokens,
        cacheCreationTokens: commit.cache_creation_tokens,
        cacheReadTokens: commit.cache_read_tokens,
        outputTokens: commit.output_tokens,
        apiCallCount: commit.api_call_count,
        attribution:
          commit.attribution_calculated_at != null
            ? {
              calculatedAt: commit.attribution_calculated_at,
              agentLines: commit.attribution_agent_lines ?? 0,
              humanAdded: commit.attribution_human_added ?? 0,
              humanModified: commit.attribution_human_modified ?? 0,
              humanRemoved: commit.attribution_human_removed ?? 0,
              totalCommitted: commit.attribution_total_committed ?? 0,
              agentPercentage: commit.attribution_agent_percentage ?? 0,
            }
            : null,
      }
      : null;

    return c.json({
      checkpoint_id: checkpointId,
      branches: location.branches,
      default_branch: location.default_branch,
      suggested_branch: suggestedBranch,
      needs_redirect: needsRedirect,
      requested_branch: requestedBranch || null,
      checkpoint,
      repo_full_name: repoFullName,
    });
  } catch (err) {
    console.error(
      `Failed to resolve checkpoint ${checkpointId} for ${repoFullName}:`,
      err,
    );
    recordSpanError(err);
    return c.json({ error: "Failed to resolve checkpoint" }, 500);
  }
});

import { ClaudeCodeParser } from "../lib/transcript-parsers/claude-code-parser";

const _legacyParser = new ClaudeCodeParser();

/**
 * @deprecated Use getParserForAgent() from lib/transcript-parsers instead.
 * Kept for backward compatibility with existing tests.
 */
export function parseTranscript(jsonlContent: string): TranscriptMessage[] {
  return _legacyParser.parse(jsonlContent).messages;
}

/**
 * Filter messages to only include those from this session.
 * Uses transcriptIdentifierAtStart to find where prior context ends;
 * messages after that identifier are the "new" messages from this session.
 */
function filterRelevantMessages(
  messages: TranscriptMessage[],
  transcriptIdentifierAtStart: string | null,
): TranscriptMessage[] {
  if (!transcriptIdentifierAtStart) return messages;
  const startIndex = messages.findIndex(
    (msg) => msg.id === transcriptIdentifierAtStart,
  );
  if (startIndex === -1) return messages;
  return messages.slice(startIndex + 1);
}

import {
  buildTranscriptCacheKey,
  TRANSCRIPT_CACHE_TTL_SECONDS,
} from "../lib/kv";

// Get transcript for a checkpoint
// Transcripts are immutable so we cache them for 7 days
repoRoutes.get(
  "/:org/:repo/checkpoints/:checkpointId/transcript",
  optionalAuth,
  rateLimitUnauthenticated,
  async (c) => {
    const userId = c.get("userId") as string | undefined;

    const org = c.req.param("org");
    const repo = c.req.param("repo");
    const checkpointId = c.req.param("checkpointId");
    const repoFullName = `${org}/${repo}`;

    // Validate checkpointId format to prevent path traversal
    if (!isValidCheckpointId(checkpointId)) {
      return c.json({ error: "Invalid checkpoint ID format" }, 400);
    }

    const db = getDb(c.env);

    // Check repo access BEFORE cache lookup (cache is shared across users)
    const repoAccess = await checkRepoAccess(db, repoFullName, userId);
    if (repoAccess instanceof Response) return repoAccess;
    if (!repoAccess) return c.json({ error: "Repository not found" }, 404);

    // Cache key is repo + checkpoint specific (not user-specific — shared safely)
    const cacheKey = buildTranscriptCacheKey(repoFullName, checkpointId);


    const cached = await c.env.ENTIRE_CACHE.get<CachedTranscript>(
      cacheKey,
      "json",
    );
    if (cached) {
      return c.json({
        checkpointId: cached.checkpointId,
        sessions: cached.sessions,
        from_cache: true,
        cached_at: cached.cached_at,
      });
    }

    // Try DB-stored stripped transcript before fetching from GitHub
    {
      let dbRow: { transcript_stripped: string | null; sessions: string | null } | null = null;
      try {
        dbRow = await db.checkpoints.getTranscript(repoAccess.id, checkpointId);
      } catch {
        // DB lookup failed, fall through to GitHub
      }

      if (dbRow?.transcript_stripped) {
        const parsed = JSON.parse(dbRow.transcript_stripped);
        // Validate shape: must be a non-null object with string values
        const strippedSessions = typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)
          ? parsed as Record<string, string>
          : null;

        if (strippedSessions) {
          const dbSessionsMeta: Array<{
            agent: string;
            sessionId: string;
            transcriptIdentifierAtStart: string | null;
            tokenUsage?: { inputTokens: number; outputTokens: number };
            attribution?: SessionAttribution;
          }> = [];

          // Parse per-session metadata from DB sessions column
          if (dbRow.sessions) {
            try {
              const sessionsInfo = JSON.parse(dbRow.sessions) as Array<{
                agent?: string;
                sessionId?: string;
                transcriptIdentifierAtStart?: string;
                tokenUsage?: { inputTokens: number; outputTokens: number; cacheCreationTokens?: number; cacheReadTokens?: number; apiCallCount?: number };
                attribution?: { calculatedAt: string; agentLines: number; humanAdded: number; humanModified: number; humanRemoved: number; totalCommitted: number; agentPercentage: number };
              }>;
              for (const s of sessionsInfo) {
                dbSessionsMeta.push({
                  agent: s.agent ?? "Claude Code",
                  sessionId: s.sessionId ?? "0",
                  transcriptIdentifierAtStart: s.transcriptIdentifierAtStart ?? null,
                  tokenUsage: s.tokenUsage ? {
                    inputTokens: s.tokenUsage.inputTokens ?? 0,
                    outputTokens: s.tokenUsage.outputTokens ?? 0,
                  } : undefined,
                  attribution: s.attribution ? {
                    calculatedAt: s.attribution.calculatedAt ?? "",
                    agentLines: s.attribution.agentLines ?? 0,
                    humanAdded: s.attribution.humanAdded ?? 0,
                    humanModified: s.attribution.humanModified ?? 0,
                    humanRemoved: s.attribution.humanRemoved ?? 0,
                    totalCommitted: s.attribution.totalCommitted ?? 0,
                    agentPercentage: s.attribution.agentPercentage ?? 0,
                  } : undefined,
                });
              }
            } catch {
              // Invalid sessions JSON — parse transcripts without metadata
            }
          }

          const dbParsedSessions: SessionTranscript[] = [];
          const sessionIndices = Object.keys(strippedSessions).sort();
          for (const idx of sessionIndices) {
            const jsonl = strippedSessions[idx];
            if (!jsonl) continue;
            const meta = dbSessionsMeta[Number(idx)];
            const agent = meta?.agent ?? "Claude Code";
            const parseResult = getParserForAgent(agent).parse(jsonl);
            const messages = filterRelevantMessages(
              parseResult.messages,
              meta?.transcriptIdentifierAtStart ?? null,
            );
            dbParsedSessions.push({
              sessionId: meta?.sessionId ?? idx,
              agent,
              messages,
              transcriptIdentifierAtStart: meta?.transcriptIdentifierAtStart ?? null,
              tokenUsage: meta?.tokenUsage,
              attribution: meta?.attribution,
              parsingFallback: parseResult.isFallback || undefined,
              parsingWarning: parseResult.warning,
            });
          }

          if (dbParsedSessions.length > 0) {
            // Cache to KV for subsequent requests
            const cacheData: CachedTranscript = {
              checkpointId,
              sessions: dbParsedSessions,
              cached_at: new Date().toISOString(),
            };
            await c.env.ENTIRE_CACHE.put(cacheKey, JSON.stringify(cacheData), {
              expirationTtl: TRANSCRIPT_CACHE_TTL_SECONDS,
            });

            return c.json({
              checkpointId,
              sessions: dbParsedSessions,
              from_cache: false,
            });
          }
        }
      }
    }

    try {
      // Get a token: user's OAuth token if authenticated, installation token otherwise.
      // Token may be undefined for public repos without an installation — GitHub's
      // public API still works for fetching file content (rate-limited).
      const tokenResult = await getGitHubTokenForRepoRequest(c, db, userId, repoAccess);
      if (tokenResult.response) return tokenResult.response;
      const token = tokenResult.token ?? undefined;

      // Convert checkpointId to folder path
      const folderPath = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;

      // Fetch root metadata.json (CheckpointSummary in v1 format)
      const metadataContent = await fetchFileAtCommit(
        repoFullName,
        `${folderPath}/metadata.json`,
        CHECKPOINT_BRANCH,
        token,
      ).catch(() => null);

      let checkpointSummary: CheckpointSummary | null = null;
      if (metadataContent) {
        try {
          checkpointSummary = JSON.parse(metadataContent) as CheckpointSummary;
        } catch {
          // Invalid JSON
        }
      }

      const sessions: SessionTranscript[] = [];

      // V1 format: use sessions[] array from CheckpointSummary for explicit paths
      // Sessions are 0-indexed (0/, 1/, 2/, etc.)
      if (checkpointSummary?.sessions && checkpointSummary.sessions.length > 0) {
        // Fetch all sessions using paths from CheckpointSummary
        // Strip leading slashes from paths (V1 format includes them but GitHub API doesn't expect them)
        const stripLeadingSlash = (path: string) => path.replace(/^\/+/, "");
        const sessionPromises: Promise<SessionTranscript | null>[] =
          checkpointSummary.sessions.map((sessionPaths, idx) =>
            (async () => {
              try {
                const [transcriptContent, sessionMetadataContent] =
                  await Promise.all([
                    fetchFileAtCommit(
                      repoFullName,
                      stripLeadingSlash(sessionPaths.transcript),
                      CHECKPOINT_BRANCH,
                      token,
                    ).catch(() => null),
                    fetchFileAtCommit(
                      repoFullName,
                      stripLeadingSlash(sessionPaths.metadata),
                      CHECKPOINT_BRANCH,
                      token,
                    ).catch(() => null),
                  ]);

                if (!transcriptContent) return null;

                let agent = "Claude Code";
                let sessionId = String(idx);
                let transcriptIdentifierAtStart: string | null = null;
                let tokenUsage: { inputTokens: number; outputTokens: number } | undefined;
                let attribution: SessionAttribution | undefined;
                if (sessionMetadataContent) {
                  try {
                    const meta = JSON.parse(sessionMetadataContent);
                    agent = meta.agent ?? "Claude Code";
                    sessionId = meta.session_id ?? String(idx);
                    transcriptIdentifierAtStart = meta.transcript_identifier_at_start ?? null;
                    if (meta.token_usage) {
                      tokenUsage = {
                        inputTokens: meta.token_usage.input_tokens ?? 0,
                        outputTokens: meta.token_usage.output_tokens ?? 0,
                      };
                    }
                    if (meta.initial_attribution) {
                      attribution = {
                        calculatedAt: meta.initial_attribution.calculated_at ?? "",
                        agentLines: meta.initial_attribution.agent_lines ?? 0,
                        humanAdded: meta.initial_attribution.human_added ?? 0,
                        humanModified: meta.initial_attribution.human_modified ?? 0,
                        humanRemoved: meta.initial_attribution.human_removed ?? 0,
                        totalCommitted: meta.initial_attribution.total_committed ?? 0,
                        agentPercentage: meta.initial_attribution.agent_percentage ?? 0,
                      };
                    }
                  } catch {
                    // Invalid JSON
                  }
                }

                const parseResult = getParserForAgent(agent).parse(transcriptContent);
                const messages = filterRelevantMessages(
                  parseResult.messages,
                  transcriptIdentifierAtStart,
                );

                return {
                  sessionId,
                  agent,
                  messages,
                  transcriptIdentifierAtStart,
                  tokenUsage,
                  attribution,
                  parsingFallback: parseResult.isFallback || undefined,
                  parsingWarning: parseResult.warning,
                };
              } catch {
                return null;
              }
            })(),
          );

        const fetchedSessions = await Promise.all(sessionPromises);
        for (const s of fetchedSessions) {
          if (s) sessions.push(s);
        }
      } else {
        // Fallback for checkpoints without sessions array (single session in 0/ per v1 spec)
        const [transcriptContent, sessionMetadataContent] = await Promise.all([
          fetchFileAtCommit(
            repoFullName,
            `${folderPath}/0/full.jsonl`,
            CHECKPOINT_BRANCH,
            token,
          ).catch(() => null),
          fetchFileAtCommit(
            repoFullName,
            `${folderPath}/0/metadata.json`,
            CHECKPOINT_BRANCH,
            token,
          ).catch(() => null),
        ]);

        if (transcriptContent) {
          let agent = "Claude Code";
          let sessionId = "0";
          let transcriptIdentifierAtStart: string | null = null;
          let tokenUsage: { inputTokens: number; outputTokens: number } | undefined;
          let attribution: SessionAttribution | undefined;

          if (sessionMetadataContent) {
            try {
              const meta = JSON.parse(sessionMetadataContent);
              agent = meta.agent ?? "Claude Code";
              sessionId = meta.session_id ?? "0";
              transcriptIdentifierAtStart = meta.transcript_identifier_at_start ?? null;
              if (meta.token_usage) {
                tokenUsage = {
                  inputTokens: meta.token_usage.input_tokens ?? 0,
                  outputTokens: meta.token_usage.output_tokens ?? 0,
                };
              }
              if (meta.initial_attribution) {
                attribution = {
                  calculatedAt: meta.initial_attribution.calculated_at ?? "",
                  agentLines: meta.initial_attribution.agent_lines ?? 0,
                  humanAdded: meta.initial_attribution.human_added ?? 0,
                  humanModified: meta.initial_attribution.human_modified ?? 0,
                  humanRemoved: meta.initial_attribution.human_removed ?? 0,
                  totalCommitted: meta.initial_attribution.total_committed ?? 0,
                  agentPercentage: meta.initial_attribution.agent_percentage ?? 0,
                };
              }
            } catch {
              // Invalid JSON in fallback session metadata; use defaults
            }
          }

          const parseResult = getParserForAgent(agent).parse(transcriptContent);
          const messages = filterRelevantMessages(
            parseResult.messages,
            transcriptIdentifierAtStart,
          );

          sessions.push({
            sessionId,
            agent,
            messages,
            transcriptIdentifierAtStart,
            tokenUsage,
            attribution,
            parsingFallback: parseResult.isFallback || undefined,
            parsingWarning: parseResult.warning,
          });
        }
      }

      // Only cache if we have actual content (avoid caching empty results from race conditions or errors)
      if (sessions.length > 0) {
        const cacheData: CachedTranscript = {
          checkpointId,
          sessions,
          cached_at: new Date().toISOString(),
        };

        await c.env.ENTIRE_CACHE.put(cacheKey, JSON.stringify(cacheData), {
          expirationTtl: TRANSCRIPT_CACHE_TTL_SECONDS,
        });
      }

      return c.json({
        checkpointId,
        sessions,
        from_cache: false,
      });
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401);
      }
      console.error(
        `Failed to fetch transcript for checkpoint ${checkpointId}:`,
        err,
      );
      recordSpanError(err);
      return c.json({ error: "Failed to fetch transcript" }, 500);
    }
  },
);

