import { useState, useEffect, useMemo } from "react";
import { useNavigate, UseNavigateResult } from "@tanstack/react-router";
import { usePostHog } from "posthog-js/react";
import { useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/domains/platform/auth";
import {
  GitHubAvatar,
  Badge,
  LineCounts,
  Combobox,
  ComboboxTrigger,
  ComboboxContent,
  ComboboxInput,
  ComboboxList,
  ComboboxItem,
  useCombobox,
  Input,
  Skeleton,
  ListView,
  ListViewItem,
  type ComboboxOption,
} from "@/components";
import Button from "@/components/Button";
import { Page } from "@/domains/platform/components/Page";
import { getGitHubInstallationUrl } from "@/domains/platform/auth/api";
import { getAgent } from "@/lib/agents";
import { isAuthError, ApiError } from "@/lib/api";
import { ReauthenticateState } from "@/domains/platform/components/ReauthenticateState";
import { formatRelativeTime } from "@/lib/date";
import {
  useCheckpointStatusQuery,
  useCheckpointsQuery,
  useBranchesQuery,
  useSearchCheckpointsQuery,
} from "../hooks/useCommitsQuery";
import { CheckpointInfo, fetchCheckpoints, type SearchMeta } from "../api";
import { getCheckpointBreadcrumbs } from "../breadcrumbs";
import { GH_PATH_PREFIX } from "../routeConfig";
import { BranchIcon, ChevronDownIcon, SearchIcon } from "@/components/icons";
import { Clock, FileCode } from "lucide-react";
import { HighlightText } from "@/components/HighlightText";
import { CliInstallationSteps } from "../components/CliInstallationSteps";
import { NotFoundContent } from "@/domains/platform/components/NotFoundPage";
import { formatNumber } from "@/lib/format";
import { useRepoBreadcrumbOptions } from "../hooks/useRepoBreadcrumbOptions";

interface CheckpointsPageProps {
  org: string;
  repo: string;
  branch: string;
}

export function CheckpointsPage(props: CheckpointsPageProps) {
  const { org, repo, branch } = props;
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [searchQuery, setSearchQuery] = useState("");
  const { data: statusData, error: statusError } = useCheckpointStatusQuery(org, repo);
  const { data, isLoading, error } = useCheckpointsQuery(org, repo, branch);
  const { data: branchesData } = useBranchesQuery(org, repo);
  const repoOptions = useRepoBreadcrumbOptions(org);

  const handleBranchChange = (newBranch: string | null) => {
    if (!newBranch) return;
    navigate({
      to: "/gh/$org/$repo/checkpoints/$branch",
      params: { org, repo, branch: newBranch },
    });
  };

  const branches = branchesData?.branches ?? [];
  const defaultBranch = branchesData?.default_branch ?? "main";

  // Sort branches with default branch first, then create options for Combobox
  const sortedBranches = [...branches].sort((a, b) => {
    if (a === defaultBranch) return -1;
    if (b === defaultBranch) return 1;
    return a.localeCompare(b);
  });

  const branchOptions: ComboboxOption[] = sortedBranches.map((b) => ({
    id: b,
    label: b,
  }));
  // Debounce search query for API calls
  const [debouncedQuery, setDebouncedQuery] = useState("");
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(searchQuery.trim()), 300);
    return () => clearTimeout(timer);
  }, [searchQuery]);

  const { data: searchData, isFetching: isSearching } = useSearchCheckpointsQuery(
    org, repo, debouncedQuery, branch,
  );

  const isSearchActive = debouncedQuery.length > 0;
  const allCheckpoints = data?.checkpoints ?? [];
  const checkpoints = isSearchActive
    ? (searchData?.checkpoints ?? [])
    : allCheckpoints;

  // =============================================================================
  // LOCAL DEV ONLY: Fetch from GitHub button
  // In local development, the D1 database isn't populated with checkpoint data.
  // This button fetches directly from GitHub to allow testing the UI.
  // import.meta.env.DEV is false in production builds, so this code is tree-shaken.
  // =============================================================================
  const isDev = import.meta.env.DEV;
  const [isFetchingFromGitHub, setIsFetchingFromGitHub] = useState(false);

  const handleFetchFromGitHub = async () => {
    setIsFetchingFromGitHub(true);
    try {
      const response = await fetchCheckpoints(org, repo, branch, {
        source: "github",
      });
      queryClient.setQueryData(
        ["github", "checkpoints", org, repo, branch],
        response,
      );
    } catch (err) {
      console.error("Failed to fetch from GitHub:", err);
    } finally {
      setIsFetchingFromGitHub(false);
    }
  };
  // =============================================================================

  // Use whichever error arrives first (status is faster, catches 404s early)
  const anyError = statusError || error;
  const isRepoNotFound = anyError?.message.includes("Repository not found");

  // Repo-level 404 — render the standard not-found page
  if (isRepoNotFound) {
    return (
      <Page noPadding>
        <div className="flex min-h-[calc(100dvh-var(--global-header-height))]">
          <NotFoundContent />
        </div>
      </Page>
    );
  }

  if (isAuthError(anyError)) {
    return (
      <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
        <ReauthenticateState />
      </Page>
    );
  }

  const isBranchNotFound = error instanceof ApiError && error.status === 404;
  const genericError = isBranchNotFound ? statusError : anyError;
  if (genericError && !isBranchNotFound) {
    return (
      <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
        <div className="border border-default rounded bg-raised p-8">
          <div className="text-center">
            <p className="text-red-500">
              Failed to load checkpoints: {genericError.message}
            </p>
          </div>
        </div>
      </Page>
    );
  }

  const hasCheckpoints = data && data.checkpoints.length > 0;
  const noCheckpoints = data && data.checkpoints.length === 0;
  // Use the fast status query to decide UI before checkpoints finish loading
  const repoHasCheckpoints = statusData && statusData.checkpoint_count > 0;
  // Show toolbar when we know there are checkpoints (or data already loaded with them)
  const showToolbar = hasCheckpoints || repoHasCheckpoints || data?.session_branch_exists === true;

  // Empty state conditions — use full data when available, fall back to status data (with error guard)
  const showNoAccess =
    (noCheckpoints && data.app_has_access === false) ||
    (!data && !anyError && statusData?.checkpoint_count === 0 && statusData?.app_has_access === false);

  // CLI install: app has access but no session branch yet (null means not synced)
  const showCliInstall =
    (noCheckpoints && data.app_has_access === true && !data.session_branch_exists) ||
    (!data && !anyError && statusData?.checkpoint_count === 0 && statusData?.app_has_access === true && !statusData.session_branch_exists);

  const showNoBranchCheckpoints =
    noCheckpoints && data.app_has_access === true && data.session_branch_exists === true;

  return (
    <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
      {/* Branch selector and search */}
      {showToolbar && <div className="pt-4 pb-4 flex items-center gap-2">
        <Combobox
          options={branchOptions}
          size="large"
          value={[branch]}
          onChange={(selected) => handleBranchChange(selected[0] ?? null)}
        >
          <ComboboxTrigger className="max-w-52 shrink-0 justify-start">
            <span className="flex items-center gap-1.5 w-full">
              <BranchIcon size={18} className="shrink-0" />
              <span className="truncate">{branch}</span>
              <ChevronDownIcon size={18} className="shrink-0 ml-auto" />
            </span>
          </ComboboxTrigger>
          <ComboboxContent>
            <ComboboxInput placeholder="Search branches..." />
            <ComboboxList emptyMessage="No branches found.">
              <BranchOptions defaultBranch={defaultBranch} />
            </ComboboxList>
          </ComboboxContent>
        </Combobox>

        <div className="min-w-45 md:min-w-65 lg:min-w-[320px] ml-auto">
          <Input
            type="text"
            placeholder="Search checkpoints..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            icon={<SearchIcon />}
          />
        </div>
      </div>}

      {/* Loading state - only show skeleton once status confirms checkpoints exist */}
      {isLoading && repoHasCheckpoints && <CheckpointsSkeleton />}

      {isBranchNotFound && (
        <ErrorState selectedBranch={branch} hasBranches={branches.length > 0} />
      )}

      {checkpoints.length > 0 && (hasCheckpoints || isSearchActive) && (
        <div className="relative">
          {isSearchActive && isSearching && (
            <div className="absolute top-0 left-0 right-0 h-0.5 bg-orange-500/30 overflow-hidden rounded-t">
              <div className="h-full w-1/3 bg-orange-500 animate-[shimmer_1s_ease-in-out_infinite]" />
            </div>
          )}
          <CheckpointsList
            checkpoints={checkpoints}
            navigate={navigate}
            isDev={isDev}
            isFetchingFromGitHub={isFetchingFromGitHub}
            handleFetchFromGitHub={handleFetchFromGitHub}
            org={org}
            repo={repo}
            branch={branch}
            searchQuery={isSearchActive ? debouncedQuery : ""}
            searchMeta={isSearchActive ? searchData?.searchMeta : undefined}
          />
        </div>
      )}

      {/* Empty search results */}
      {isSearchActive &&
        !isSearching &&
        checkpoints.length === 0 &&
        searchData && (
          <div className="border border-default rounded bg-raised p-8">
            <div className="text-center text-muted">
              <p className="text-lg font-medium">No matching checkpoints</p>
              <p className="mt-2 text-sm max-w-md mx-auto">
                No checkpoints match &ldquo;{searchQuery}&rdquo;. Try a different search
                term.
              </p>
            </div>
          </div>
        )}

      {/* Empty state: App doesn't have access */}
      {showNoAccess && (
        <div className="flex items-center justify-center min-h-[calc(100vh-var(--global-header-height)-120px)]">
          <div className="text-center text-muted py-12 px-8">
            <p className="text-xl font-semibold text-default">
              Grant access to this repository
            </p>
            <p className="mt-3 text-sm max-w-md mx-auto">
              The GitHub App needs access to this repository to track your
              Claude Code sessions.
            </p>
            <p className="mt-6 text-sm">
              <a
                href={getGitHubInstallationUrl()}
                className="text-orange-500 hover:underline"
              >
                Configure GitHub App access
              </a>
            </p>
            {isDev && (
              <div className="mt-4">
                <Button
                  variant="outline"
                  onClick={handleFetchFromGitHub}
                  disabled={isFetchingFromGitHub}
                >
                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
                </Button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Empty state: App has access but no session branch (CLI not used yet) */}
      {showCliInstall && (
        <div className="flex items-center justify-center min-h-[calc(100vh-var(--global-header-height)-120px)]">
          <div>
            <CliInstallationSteps />
            {isDev && (
              <div className="flex justify-center pb-8">
                <Button
                  variant="outline"
                  onClick={handleFetchFromGitHub}
                  disabled={isFetchingFromGitHub}
                >
                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
                </Button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Empty state: App has access and session branch exists, but no checkpoints on this branch */}
      {showNoBranchCheckpoints && (
        <div className="border border-default rounded bg-raised p-8">
          <div className="text-center text-muted">
            <p className="text-lg font-medium">
              No checkpoints on this branch
            </p>
            <p className="mt-2 text-sm max-w-md mx-auto">
              This repository has Claude Code sessions, but none of them are
              linked to commits on the{" "}
              <code className="font-mono bg-muted px-1 rounded">
                {branch}
              </code>{" "}
              branch.
            </p>
            {isDev && (
              <div className="mt-4">
                <Button
                  variant="outline"
                  onClick={handleFetchFromGitHub}
                  disabled={isFetchingFromGitHub}
                >
                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
                </Button>
              </div>
            )}
          </div>
        </div>
      )}

    </Page>
  );
}

interface ErrorStateProps {
  selectedBranch: string;
  hasBranches: boolean;
}

function ErrorState(props: ErrorStateProps) {
  const { selectedBranch, hasBranches } = props;
  return (
    <div className="border border-default rounded bg-raised p-8">
      <div className="text-center">
        <p className="text-lg font-medium text-default">Branch not found</p>
        <p className="mt-2 text-sm text-muted max-w-md mx-auto">
          The branch{" "}
          <code className="font-mono bg-muted px-1 rounded">
            {selectedBranch}
          </code>{" "}
          does not exist in this repository.
        </p>
        {hasBranches && (
          <p className="mt-4 text-sm text-muted">
            Try switching to one of the available branches above.
          </p>
        )}
      </div>
    </div>
  );
}

interface CheckpointsListProps {
  checkpoints: CheckpointInfo[];
  navigate: UseNavigateResult<string>;
  isDev: boolean;
  handleFetchFromGitHub: () => Promise<void>;
  isFetchingFromGitHub: boolean;
  org: string;
  repo: string;
  branch: string;
  searchQuery: string;
  searchMeta?: Record<string, SearchMeta>;
}

function CheckpointsList(props: CheckpointsListProps) {
  const posthog = usePostHog();
  const {
    checkpoints,
    navigate,
    isDev,
    handleFetchFromGitHub,
    isFetchingFromGitHub,
    org,
    repo,
    branch,
    searchQuery,
    searchMeta,
  } = props;

  const isSearch = searchQuery.length > 0;

  // Normalize scores relative to top result
  const maxScore = searchMeta
    ? Math.max(...Object.values(searchMeta).map((m) => m.score), 0)
    : 0;

  const handleSelect = (index: number) => {
    const checkpoint = checkpoints[index];
    if (!checkpoint) return;

    posthog.capture("checkpoint_clicked", {
      repository: `${org}/${repo}`,
      checkpoint_id: checkpoint.checkpointId,
    });
    navigate({
      to: "/gh/$org/$repo/checkpoints/$branch/$checkpointId",
      params: {
        org,
        repo,
        branch,
        checkpointId: checkpoint.checkpointId,
      },
    });
  };

  return (
    <>
      <ListView
        itemCount={checkpoints.length}
        onSelect={handleSelect}
        aria-label="Checkpoints"
        className={isSearch
          ? "@container flex flex-col gap-3"
          : "@container border border-default rounded overflow-hidden bg-raised"
        }
      >
        {checkpoints.map((checkpoint, index) => {
          const sessionCount = checkpoint.sessionCount;
          const uniqueAgents = checkpoint.agents;
          const checkpointTitle = checkpoint.commitMessage;
          const fileCount = checkpoint.fileStats?.length ?? 0;
          const meta = searchMeta?.[checkpoint.checkpointId];
          const normalizedScore = meta && maxScore > 0
            ? Math.round((meta.score / maxScore) * 100)
            : 0;

          const checkpointHref = `${GH_PATH_PREFIX}/${encodeURIComponent(org)}/${encodeURIComponent(repo)}/checkpoints/${encodeURIComponent(branch)}/${encodeURIComponent(checkpoint.checkpointId)}`;

          // Search mode: show filesTouched for keyword/both matches
          const showFiles = isSearch && meta
            && (meta.matchType === "both" || meta.matchType === "keyword")
            && checkpoint.filesTouched
            && checkpoint.filesTouched.length > 0;
          const filesToShow = showFiles ? checkpoint.filesTouched!.slice(0, 3) : [];

          if (isSearch) {
            return (
              <ListViewItem
                key={checkpoint.checkpointId}
                index={index}
                href={checkpointHref}
                aria-label={`${checkpointTitle}, ${checkpoint.additions} additions, ${checkpoint.deletions} deletions, ${fileCount} ${fileCount === 1 ? "file" : "files"}, ${formatRelativeTime(checkpoint.commitDate)}, by ${checkpoint.commitAuthorUsername}`}
                className="px-6 py-5 transition-colors hover:bg-hover border border-default rounded-lg bg-raised"
              >
                {/* Row 1: Title + Badge + Score */}
                <div className="flex items-start justify-between gap-4">
                  <p className="font-semibold text-base text-default truncate min-w-0">
                    <HighlightText text={checkpointTitle} query={searchQuery} />
                  </p>
                  <div className="flex items-center gap-2 shrink-0">
                    <MatchTypeBadge matchType={meta?.matchType ?? "semantic"} />
                    <span className="text-sm font-mono text-muted">{normalizedScore}</span>
                  </div>
                </div>

                {/* Row 2: Metadata */}
                <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-mono text-muted mt-3">
                  <span>{checkpoint.checkpointId}</span>
                  <span aria-hidden="true" className="text-muted/50">|</span>
                  <span className="flex items-center gap-1.5">
                    <Clock size={13} aria-hidden="true" />
                    {formatRelativeTime(checkpoint.commitDate)}
                  </span>
                  <span aria-hidden="true" className="text-muted/50">|</span>
                  <span className="flex items-center gap-1.5">
                    <GitHubAvatar
                      username={checkpoint.commitAuthorUsername}
                      className="size-4"
                    />
                    {checkpoint.commitAuthorUsername}
                  </span>
                  {uniqueAgents.length > 0 && (
                    <>
                      <span aria-hidden="true" className="text-muted/50">|</span>
                      {uniqueAgents.map((agent) => {
                        const config = getAgent(agent);
                        return (
                          <span key={agent} className={config.colorClass}>
                            {config.label}
                          </span>
                        );
                      })}
                    </>
                  )}
                </div>

                {/* Row 3: Stats */}
                <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs font-mono text-muted mt-2">
                  <LineCounts
                    additions={checkpoint.additions}
                    deletions={checkpoint.deletions}
                  />
                  <span>
                    {fileCount} {fileCount === 1 ? "file" : "files"}
                  </span>
                  {sessionCount > 0 && (
                    <span>
                      {sessionCount} {sessionCount === 1 ? "session" : "sessions"}
                    </span>
                  )}
                  {(checkpoint.inputTokens != null || checkpoint.outputTokens != null) && (
                    <span>
                      {formatNumber(
                        (checkpoint.inputTokens ?? 0) + (checkpoint.outputTokens ?? 0),
                      )}{" "}
                      tokens
                    </span>
                  )}
                </div>

                {/* Row 4: Files (keyword/both matches only) */}
                {filesToShow.length > 0 && (
                  <div className="mt-3 flex flex-col gap-1">
                    {filesToShow.map((file) => (
                      <span key={file} className="flex items-center gap-1.5 text-xs font-mono text-muted">
                        <FileCode size={13} className="shrink-0 text-muted/60" aria-hidden="true" />
                        <HighlightText text={file} query={searchQuery} />
                      </span>
                    ))}
                  </div>
                )}
              </ListViewItem>
            );
          }

          // Normal (non-search) card
          return (
            <ListViewItem
              key={checkpoint.checkpointId}
              index={index}
              href={checkpointHref}
              aria-label={`${checkpointTitle}, ${checkpoint.additions} additions, ${checkpoint.deletions} deletions, ${fileCount} ${fileCount === 1 ? "file" : "files"}, ${formatRelativeTime(checkpoint.commitDate)}, by ${checkpoint.commitAuthorUsername}`}
              className={`px-6 py-5 transition-colors hover:bg-hover ${
                index !== checkpoints.length - 1
                  ? "border-b border-default"
                  : ""
              }`}
            >
              <div className="flex flex-col @4xl:flex-row @4xl:items-center @4xl:justify-between gap-1 @4xl:gap-8">
                {/* Left: title + metadata */}
                <div className="min-w-0">
                  <p className="font-semibold text-base text-default truncate">
                    {checkpointTitle}
                  </p>
                  <div className="flex flex-wrap items-center gap-x-1.5 gap-y-1 text-xs font-mono text-muted mt-1">
                    <Badge>
                      <code className="font-mono">
                        {checkpoint.checkpointId}
                      </code>
                    </Badge>
                    <span aria-hidden="true">·</span>
                    <span className="flex flex-row items-center gap-1.5 shrink-0">
                      <Clock size={14} aria-hidden="true" />
                      {formatRelativeTime(checkpoint.commitDate)}
                    </span>
                    <span aria-hidden="true">·</span>
                    <span className="flex items-center gap-1 shrink-0">
                      <GitHubAvatar
                        username={checkpoint.commitAuthorUsername}
                        className="size-4"
                      />
                      <span>{checkpoint.commitAuthorUsername}</span>
                    </span>
                    {(uniqueAgents.length > 0 || sessionCount > 0) && (
                      <span aria-hidden="true">·</span>
                    )}
                    {uniqueAgents.length > 0 ? (
                      uniqueAgents.map((agent) => {
                        const config = getAgent(agent);
                        return (
                          <Badge
                            key={agent}
                            className={`${config.colorClass} agent-badge`}
                          >
                            {config.label}
                          </Badge>
                        );
                      })
                    ) : sessionCount > 0 ? (
                      <Badge className={`${getAgent(null).colorClass} agent-badge`}>
                        {getAgent(null).label}
                      </Badge>
                    ) : null}
                  </div>
                </div>

                {/* Right: stats + session summary */}
                <div className="@4xl:shrink-0 text-xs font-mono text-muted flex items-center gap-1.5">
                  <LineCounts
                    additions={checkpoint.additions}
                    deletions={checkpoint.deletions}
                  />
                  <span aria-hidden="true">·</span>
                  <span>
                    {fileCount} {fileCount === 1 ? "file" : "files"}
                  </span>
                  {sessionCount > 0 && (
                    <>
                      <span aria-hidden="true">·</span>
                      <span>
                        {sessionCount} {sessionCount === 1 ? "session" : "sessions"}
                      </span>
                      {(checkpoint.inputTokens != null ||
                        checkpoint.outputTokens != null) && (
                        <>
                          <span aria-hidden="true">·</span>
                          <span>
                            {formatNumber(
                              (checkpoint.inputTokens ?? 0) +
                                (checkpoint.outputTokens ?? 0),
                            )}{" "}
                            tokens
                          </span>
                        </>
                      )}
                    </>
                  )}
                </div>
              </div>
            </ListViewItem>
          );
        })}
      </ListView>
      {isDev && (
        <div className="flex justify-center pt-4">
          <Button
            variant="outline"
            size="small"
            onClick={handleFetchFromGitHub}
            disabled={isFetchingFromGitHub}
          >
            {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
          </Button>
        </div>
      )}
    </>
  );
}

function CheckpointsSkeleton() {
  return (
    <div className="border border-default rounded overflow-hidden bg-raised" aria-busy="true" aria-live="polite">
      {Array.from({ length: 5 }).map((_, index) => (
        <div
          key={index}
          className={`px-6 py-5 ${index !== 4 ? "border-b border-default" : ""}`}
        >
          {/* Line 1: Title + stats */}
          <div className="flex items-center justify-between gap-4">
            <Skeleton className="h-5 w-3/5" />
            <Skeleton className="h-4 w-24 shrink-0" />
          </div>
          {/* Line 2: Metadata */}
          <div className="flex items-center gap-3 mt-2.5">
            <Skeleton className="h-4 w-20" />
            <Skeleton className="h-4 w-16" />
            <Skeleton className="h-4 w-24" />
          </div>
        </div>
      ))}
    </div>
  );
}

interface BranchOptionsProps {
  defaultBranch: string;
}

const MATCH_TYPE_STYLES: Record<string, { label: string; className: string }> = {
  both: { label: "Semantic + Keyword", className: "border-green-500/50 text-green-500" },
  semantic: { label: "Semantic", className: "border-orange-500/50 text-orange-500" },
  keyword: { label: "Keyword", className: "border-green-500/50 text-green-500" },
};

function MatchTypeBadge({ matchType }: { matchType: "semantic" | "keyword" | "both" }) {
  const style = MATCH_TYPE_STYLES[matchType];
  return (
    <span className={`inline-flex items-center text-xs font-medium px-2.5 py-0.5 rounded-full border bg-transparent ${style.className}`}>
      {style.label}
    </span>
  );
}

function BranchOptions({ defaultBranch }: BranchOptionsProps) {
  const { filteredOptions } = useCombobox();

  return (
    <>
      {filteredOptions.map((option, index) => (
        <ComboboxItem key={option.id} option={option} index={index}>
          <span className="flex-1 flex items-center gap-2 truncate">
            <span className="truncate">{option.label}</span>
            {option.id === defaultBranch && (
              <Badge className="text-[10px] px-1.5 py-0 shrink-0">
                default
              </Badge>
            )}
          </span>
        </ComboboxItem>
      ))}
    </>
  );
}

