// Handle team events (added_to_repository/removed_from_repository) - always queue full sync
// We don't have team membership data, so we can't determine which users are affected
async function handleTeamEvent(
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  cache: KVNamespace,
  env?: Env
): Promise<void> {
  if (!env?.USER_REPO_SYNC_QUEUE) {
    console.log(`Access change team/${action}: no USER_REPO_SYNC_QUEUE, skipping`);
    return;
  }

  const installation = payload.installation as { id?: number } | undefined;
  if (!installation?.id) {
    console.log(`Access change team/${action}: no installation.id, skipping`);
    return;
  }

  const users = await db.installations.findUsersByGitHubId(installation.id);
  if (users.length === 0) {
    console.log(`Access change team/${action}: no users for installation ${installation.id}, skipping`);
    return;
  }

  const queued = await queueUserRepoSyncBatch(env.USER_REPO_SYNC_QUEUE, users, "access_change");
  const now = Date.now();
  await Promise.all(
    users.map((user) =>
      cache.put(`sync:lastUpdate:${user.id}`, String(now), {
        expirationTtl: 60 * 60 * 24 * 7,
      })
    )
  );
  console.log(`Access change team/${action}: queued sync for ${queued} user(s)`);
}

// PR actions that affect the open PR list
const PR_RELEVANT_ACTIONS = new Set([
  "opened",
  "closed",
  "reopened",
  "converted_to_draft",
  "ready_for_review",
]);

// Extract PR data from webhook payload
function extractPRData(payload: Record<string, unknown>): WebhookPRData | null {
  const pr = payload.pull_request as Record<string, unknown> | undefined;
  if (!pr || typeof pr.id !== "number") {
    return null;
  }

  return {
    github_pr_id: pr.id as number,
    number: pr.number as number,
    title: pr.title as string,
    html_url: pr.html_url as string,
    state: pr.state as string,
    draft: (pr.draft as boolean) ?? false,
    created_at: pr.created_at as string,
    updated_at: pr.updated_at as string,
  };
}

// Process pull_request webhook event - update PR in database
export async function processPullRequestEvent(
  eventType: string,
  action: string | null,
  payload: Record<string, unknown>,
  db: Db
): Promise<void> {
  if (eventType !== "pull_request") {
    return;
  }

  if (!action || !PR_RELEVANT_ACTIONS.has(action)) {
    console.log(`PR event ${action}: not relevant for DB, skipping`);
    return;
  }

  // Validate installation exists before processing
  // This prevents unauthorized data modification from compromised webhook secrets
  const installationId = await validateInstallation(payload, db, `PR event ${action}`);
  if (installationId === null) {
    console.log(`PR event ${action}: no installation ID in payload, skipping`);
    return;
  }

  const repo = payload.repository as Record<string, unknown> | undefined;
  if (!repo || typeof repo.full_name !== "string" || typeof repo.id !== "number") {
    console.log(`PR event: no repository data, skipping`);
    return;
  }

  const repoGithubId = repo.id as number;
  const repoFullName = repo.full_name as string;
  const prData = extractPRData(payload);
  if (!prData) {
    console.log(`PR event: no pull_request data, skipping`);
    return;
  }

  let dbChanges = 0;

  if (action === "opened" || action === "reopened") {
    // Insert or update PR in the global repo_pull_requests table
    dbChanges = await db.prs.upsertPRFromWebhook(repoGithubId, prData);
    console.log(`PR ${action} #${prData.number} for ${repoFullName}: upserted ${dbChanges} row(s)`);
  } else if (action === "closed") {
    // Delete PR (we only keep open PRs)
    dbChanges = await db.prs.deletePRByGithubId(repoGithubId, prData.github_pr_id);
    console.log(`PR closed #${prData.number} for ${repoFullName}: deleted ${dbChanges} row(s)`);
  } else if (action === "converted_to_draft" || action === "ready_for_review") {
    // Update draft status
    const draft = action === "converted_to_draft";
    dbChanges = await db.prs.updatePRDraftStatusByGithubIds(repoGithubId, prData.github_pr_id, draft);
    console.log(`PR ${action} #${prData.number} for ${repoFullName}: updated draft status ${dbChanges} row(s)`);
  }

  // Note: sync:lastUpdate cache invalidation is already handled by processWebhookEvent
  // for all pull_request events, so we don't duplicate it here (Cloudflare KV has a
  // 1 write/sec/key rate limit that would cause 429 errors).
}

// ============================================================================
// Checkpoint webhook handlers
// ============================================================================

function logCheckpointMetric(event: string, data: Record<string, unknown>): void {
  console.log(`[checkpoint-sync] ${event}`, JSON.stringify(data));
}

/** Map session data (from the checkpoint branch) into CheckpointWebhookData records. */
function buildCheckpointDataFromSessions(
  checkpointIds: string[],
  sessionDataResult: BatchResult<SessionData>,
  fallbackBranch?: string | null,
): CheckpointWebhookData[] {
  return checkpointIds.map((checkpointId) => {
    const session = sessionDataResult.data.get(checkpointId);
    return {
      checkpoint_id: checkpointId,
      prompt: session?.prompt ?? null,
      agent: session?.agent ?? null,
      steps: session?.steps ?? null,
      session_count: session?.sessionCount ?? null,
      strategy: session?.strategy ?? null,
      created_at: session?.createdAt ?? new Date().toISOString(),
      branch: session?.branch ?? fallbackBranch ?? null,
      session_id: session?.sessionId ?? null,
      files_touched: session?.filesTouched ?? null,
      session_ids: session?.sessionIds ?? null,
      transcript_uuid_at_start: session?.transcriptUuidAtStart ?? null,
      transcript_lines_at_start: session?.transcriptLinesAtStart ?? null,
      checkpoint_transcript_start: session?.checkpointTranscriptStart ?? null,
      input_tokens: session?.inputTokens ?? null,
      cache_creation_tokens: session?.cacheCreationTokens ?? null,
      cache_read_tokens: session?.cacheReadTokens ?? null,
      output_tokens: session?.outputTokens ?? null,
      api_call_count: session?.apiCallCount ?? null,
      attribution_agent_lines: session?.attributionAgentLines ?? null,
      attribution_human_added: session?.attributionHumanAdded ?? null,
      attribution_human_modified: session?.attributionHumanModified ?? null,
      attribution_human_removed: session?.attributionHumanRemoved ?? null,
      attribution_total_committed: session?.attributionTotalCommitted ?? null,
      attribution_agent_percentage: session?.attributionAgentPercentage ?? null,
      attribution_calculated_at: session?.attributionCalculatedAt ?? null,
      sessions: (session?.sessions ?? null) as Json | null,
    };
  });
}

// Process push to CHECKPOINT_BRANCH - stores session metadata (prompt, agent, steps)
export async function processSessionsPushEvent(
  eventType: string,
  payload: Record<string, unknown>,
  db: Db,
  env: Env
): Promise<void> {
  if (eventType !== "push") return;

  const repo = payload.repository as Record<string, unknown> | undefined;
  if (!repo?.full_name) return;

  const repoFullName = repo.full_name as string;
  const ref = payload.ref as string | undefined;

  // Only process pushes to CHECKPOINT_BRANCH
  if (ref !== `refs/heads/${CHECKPOINT_BRANCH}`) return;

  const deleted = payload.deleted as boolean | undefined;
  if (deleted) {
    logCheckpointMetric("sessions_branch_deleted", { repo: repoFullName });
    return;
  }

  // Find the global repo record
  const repoGithubId = repo.id as number;
  const repoRecord = await db.repos.getByGithubId(repoGithubId);
  if (!repoRecord) {
    logCheckpointMetric("skip_repo_not_found", { repo: repoFullName });
    return;
  }

  // Get commits from push payload
  const commits = payload.commits as Array<Record<string, unknown>> | undefined;
  if (!commits?.length) return;

  // Extract checkpoint IDs from Checkpoint: trailer
  // Handle multiple trailers per commit (e.g., from squashed commits)
  const checkpointIds: string[] = [];
  for (const commit of commits) {
    const message = commit.message as string;
    const trailers = parseTrailers(message);
    const commitCheckpointIds = trailers["Checkpoint"] ?? [];
    checkpointIds.push(...commitCheckpointIds);
  }

  if (checkpointIds.length === 0) {
    logCheckpointMetric("no_session_checkpoints", { repo: repoFullName });
    return;
  }

  logCheckpointMetric("processing_sessions", { repo: repoFullName, count: checkpointIds.length });

  // Validate installation exists before processing
  // This prevents unauthorized data modification from compromised webhook secrets
  const installationId = await validateInstallation(payload, db, `Sessions push ${repoFullName}`);
  if (installationId === null) {
    logCheckpointMetric("skip_no_installation", { repo: repoFullName });
    return;
  }

  // Get app installation token
  let token: string | null = null;
  try {
    token = await getInstallationToken(
      installationId,
      {
        appId: env.GITHUB_CLIENT_ID,
        privateKey: env.GITHUB_APP_PRIVATE_KEY,
      },
      env.ENTIRE_CACHE
    );
  } catch (err) {
    logCheckpointMetric("installation_token_unavailable", {
      repo: repoFullName,
      installationId,
      error: err instanceof Error ? err.message : String(err),
    });
  }

  // If no token, we can't fetch session files - skip processing
  if (!token) {
    logCheckpointMetric("skip_no_token", { repo: repoFullName });
    return;
  }

  trace.getActiveSpan()?.setAttribute("github.installation_id", installationId);

  try {
    // Batch fetch all session data using GraphQL
    const sessionDataResult = await fetchSessionDataBatch(repoFullName, checkpointIds, token);

    if (sessionDataResult.failedItems.length > 0) {
      logCheckpointMetric("sessions_partial_failure", {
        repo: repoFullName,
        failed: sessionDataResult.failedItems.length,
        errors: sessionDataResult.errors,
      });
    }

    // Build checkpoint data array
    const checkpointDataArray = buildCheckpointDataFromSessions(checkpointIds, sessionDataResult);

    // Upsert checkpoints for the global repo (once, not per-user)
    const successCount = await db.checkpoints.upsertBatch(repoRecord.id, checkpointDataArray);

    // Queue checkpoints for search indexing (non-blocking, best-effort)
    if (env.SEARCH_INDEX_QUEUE) {
      await env.SEARCH_INDEX_QUEUE.send({
        repoId: repoRecord.id,
        checkpointIds,
        queuedAt: new Date().toISOString(),
      } satisfies SearchIndexMessage);
    }

    // Invalidate transcript cache for affected checkpoints
    // Session data changes mean transcripts may have changed
    await Promise.all(
      checkpointIds.map((id) =>
        env.ENTIRE_CACHE.delete(buildTranscriptCacheKey(repoFullName, id))
      )
    );

    // Count session metrics for monitoring
    const totalSessions = checkpointDataArray.reduce((sum, cp) => sum + (cp.session_count ?? 0), 0);
    const checkpointsWithSessions = checkpointDataArray.filter((cp) => cp.sessions != null).length;

    logCheckpointMetric("sessions_completed", {
      repo: repoFullName,
      successCount,
      totalSessions,
      checkpointsWithSessions,
      checkpointsTotal: checkpointDataArray.length,
    });
  } catch (err) {
    logCheckpointMetric("error_sessions", {
      repo: repoFullName,
      error: err instanceof Error ? err.message : String(err),
    });
    throw err; // Re-throw to trigger webhook retry mechanism
  }
}

// Process push to any branch (except CHECKPOINT_BRANCH) - stores commit data
export async function processCommitPushEvent(
  eventType: string,
  payload: Record<string, unknown>,
  db: Db,
  env: Env
): Promise<void> {
  if (eventType !== "push") return;

  const repo = payload.repository as Record<string, unknown> | undefined;
  if (!repo?.full_name) return;

  const repoFullName = repo.full_name as string;
  const ref = payload.ref as string | undefined;
  const deleted = payload.deleted as boolean | undefined;

  // Only process branch pushes (not tags)
  if (!ref?.startsWith("refs/heads/")) return;
  const branch = ref.replace("refs/heads/", "");

  // Skip CHECKPOINT_BRANCH - handled by processSessionsPushEvent
  if (branch === CHECKPOINT_BRANCH) return;

  // Skip TRAILS_BRANCH - handled by processTrailsPushEvent
  if (branch === TRAILS_BRANCH) return;

  // Validate installation exists before processing any DB operations
  // This prevents unauthorized data modification from compromised webhook secrets
  const installationId = await validateInstallation(payload, db, `Commit push ${repoFullName}`);
  if (installationId === null) {
    logCheckpointMetric("skip_no_installation", { repo: repoFullName, branch });
    return;
  }

  trace.getActiveSpan()?.setAttribute("github.installation_id", installationId);

  // Find the global repo record
  const repoGithubId = repo.id as number;
  const repoRecord = await db.repos.getByGithubId(repoGithubId);
  if (!repoRecord) {
    logCheckpointMetric("skip_repo_not_found", { repo: repoFullName });
    return;
  }

  // Handle branch deletion
  if (deleted) {
    const deletedCount = await db.checkpoints.deleteCommitsByBranch(repoRecord.id, branch);
    const orphansDeleted = await db.checkpoints.deleteOrphaned(repoRecord.id);
    if (deletedCount > 0 || orphansDeleted > 0) {
      await db.checkpoints.recalculateCount(repoRecord.id);
    }
    logCheckpointMetric("branch_deleted", { repo: repoFullName, branch, deletedCount, orphansDeleted });
    return;
  }

  // Handle force push: clear stale checkpoint commits for this branch and queue re-sync.
  // Force pushes rewrite history, so old checkpoint commits may no longer be reachable.
  // The push payload only contains newly pushed commits (not the full branch), so we
  // delete stale entries immediately and queue a full backfill to re-discover the rest.
  const forced = payload.forced as boolean | undefined;
  if (forced) {
    const deletedCount = await db.checkpoints.deleteCommitsByBranch(repoRecord.id, branch);
    const orphansDeleted = await db.checkpoints.deleteOrphaned(repoRecord.id);
    if (deletedCount > 0 || orphansDeleted > 0) {
      await db.checkpoints.recalculateCount(repoRecord.id);
    }

    // Invalidate backfill state so next sync does a full re-discovery
    await db.checkpoints.updateSyncState(repoRecord.id, { resetBackfill: true });

    // Queue immediate re-sync to backfill reachable checkpoints
    if (env?.REPO_SYNC_QUEUE) {
      await queueRepoSyncBatch(env.REPO_SYNC_QUEUE, [{ id: repoRecord.id }], "manual", 10);
    }

    logCheckpointMetric("force_push_cleanup", { repo: repoFullName, branch, deletedCount, orphansDeleted });
  }

  // Get commits from push payload
  const commits = payload.commits as Array<Record<string, unknown>> | undefined;
  if (!commits?.length) return;

  const defaultBranch = repoRecord.default_branch || repo.default_branch || "main";

  // Extract checkpoint IDs from Entire-Checkpoint trailers in commit messages.
  // On non-default branches, skip non-distinct commits (distinct=false means the
  // commit already existed in the repository / was pushed before, e.g. via "Update branch" merge).
  const checkpointCommits: Array<{
    sha: string;
    message: string;
    checkpointId: string;
    author: { name: string; username?: string };
    timestamp: string;
  }> = [];

  let skippedNonDistinct = 0;

  for (const commit of commits) {
    if (branch !== defaultBranch && commit.distinct === false) {
      skippedNonDistinct++;
      continue;
    }

    const message = commit.message as string;
    const checkpointIds = extractCheckpointIds(message);

    for (const checkpointId of checkpointIds) {
      checkpointCommits.push({
        sha: commit.id as string,
        message,
        checkpointId,
        author: {
          name: (commit.author as Record<string, unknown>)?.name as string,
          username: (commit.author as Record<string, unknown>)?.username as string | undefined,
        },
        timestamp: commit.timestamp as string,
      });
    }
  }

  if (skippedNonDistinct > 0) {
    logCheckpointMetric("skipped_non_distinct_commits", {
      repo: repoFullName,
      branch,
      skipped: skippedNonDistinct,
    });
  }

  if (checkpointCommits.length === 0) {
    logCheckpointMetric("no_commit_checkpoints", { repo: repoFullName, branch });
    return;
  }

  logCheckpointMetric("processing_commits", { repo: repoFullName, branch, count: checkpointCommits.length });

  // Get app installation token (installation already validated above)
  // Token is required to fetch commit stats - without it we'd store incomplete data
  let token: string;
  try {
    token = await getInstallationToken(
      installationId,
      {
        appId: env.GITHUB_CLIENT_ID,
        privateKey: env.GITHUB_APP_PRIVATE_KEY,
      },
      env.ENTIRE_CACHE
    );
  } catch (err) {
    logCheckpointMetric("installation_token_unavailable", {
      repo: repoFullName,
      branch,
      installationId,
      error: err instanceof Error ? err.message : String(err),
    });
    // Throw so webhook retries - we need the token to fetch complete commit stats
    throw err;
  }

  try {
    // Extract checkpoint IDs for stub creation
    const checkpointIds = checkpointCommits.map((c) => c.checkpointId);

    // Batch fetch commit stats using REST API (includes per-file breakdown)
    const shas = checkpointCommits.map((c) => c.sha);
    const commitStatsResult = await fetchCommitStatsBatch(repoFullName, shas, token);

    if (commitStatsResult.failedItems.length > 0) {
      logCheckpointMetric("commits_stats_partial_failure", {
        repo: repoFullName,
        branch,
        failed: commitStatsResult.failedItems.length,
        errors: commitStatsResult.errors,
      });
    }

    // Build commit data array
    // Look up author GitHub IDs from the users table by username
    const uniqueUsernames = [...new Set(checkpointCommits.map((c) => c.author.username).filter(Boolean))] as string[];
    const usernameToGithubId = await db.users.findGitHubIdsByLogins(uniqueUsernames);

    // Parse squash commit titles for each unique commit message
    // This extracts individual commit titles from GitHub's squash-merge format
    const squashTitlesByMessage = new Map<string, Map<string, string>>();
    for (const commit of checkpointCommits) {
      if (!squashTitlesByMessage.has(commit.message)) {
        squashTitlesByMessage.set(commit.message, parseSquashCommitTitles(commit.message));
      }
    }

    const commitDataArray: CommitWebhookData[] = checkpointCommits.map((commit) => {
      const stats = commitStatsResult.data.get(commit.sha);
      const username = commit.author.username ?? null;
      const squashTitles = squashTitlesByMessage.get(commit.message);
      const commitTitle = squashTitles?.get(commit.checkpointId) ?? commit.message.split("\n")[0];
      return {
        checkpoint_id: commit.checkpointId,
        commit_sha: commit.sha,
        commit_message: commitTitle,
        commit_author: commit.author.name,
        commit_author_username: username,
        commit_author_github_id: username ? usernameToGithubId.get(username) ?? null : null,
        commit_date: commit.timestamp,
        additions: stats?.additions ?? 0,
        deletions: stats?.deletions ?? 0,
        files_changed: stats?.filesChanged ?? 0,
        file_stats: stats?.files ?? null,
      };
    });

    // Fetch session metadata from CHECKPOINT_BRANCH tree (may be empty if session push hasn't arrived yet)
    const sessionDataResult = await fetchSessionDataBatch(repoFullName, checkpointIds, token);

    if (sessionDataResult.failedItems.length > 0) {
      logCheckpointMetric("commit_sessions_partial_failure", {
        repo: repoFullName,
        failed: sessionDataResult.failedItems.length,
        errors: sessionDataResult.errors,
      });
    }

    // Upsert full checkpoint records (COALESCE preserves existing data)
    const checkpointData = buildCheckpointDataFromSessions(checkpointIds, sessionDataResult, branch);
    const checkpointsProcessed = await db.checkpoints.upsertBatch(repoRecord.id, checkpointData);

    // Upsert commits for the global repo (once, not per-user)
    const successCount = await db.checkpoints.upsertCommitBatch(repoRecord.id, branch, commitDataArray);

    // Queue checkpoints for search indexing (non-blocking, best-effort)
    if (env.SEARCH_INDEX_QUEUE) {
      await env.SEARCH_INDEX_QUEUE.send({
        repoId: repoRecord.id,
        checkpointIds: checkpointCommits.map((c) => c.checkpointId),
        queuedAt: new Date().toISOString(),
      } satisfies SearchIndexMessage);
    }

    // Recalculate checkpoint count
    if (successCount > 0) {
      await db.checkpoints.recalculateCount(repoRecord.id);
    }

    if (checkpointsProcessed > 0) {
      logCheckpointMetric("checkpoints_upserted", { repo: repoFullName, branch, count: checkpointsProcessed });
    }

    logCheckpointMetric("commits_completed", { repo: repoFullName, branch, successCount });

    // Link checkpoints to matching trails (best-effort, non-blocking)
    try {
      await linkCheckpointsToTrails(
        repoFullName,
        branch,
        checkpointCommits.map((c) => ({
          sha: c.sha,
          checkpointId: c.checkpointId,
          message: c.message.split("\n")[0],
          timestamp: c.timestamp,
        })),
        token,
      );
    } catch (err) {
      logCheckpointMetric("trail_linkage_error", {
        repo: repoFullName,
        branch,
        error: err instanceof Error ? err.message : String(err),
      });
    }
  } catch (err) {
    logCheckpointMetric("error_commits", {
      repo: repoFullName,
      branch,
      error: err instanceof Error ? err.message : String(err),
    });
    throw err; // Re-throw to trigger webhook retry mechanism
  }
}

// ============================================================================
// Checkpoint-to-trail linkage
// ============================================================================

/**
 * Link newly synced checkpoints to any trails that match the pushed branch.
 * Discovers trails from the entire/trails/v1 git branch, finds those whose
 * metadata.branch matches the pushed branch, and appends new checkpoint
 * references to their checkpoints.json.
 */
async function linkCheckpointsToTrails(
  repoFullName: string,
  branch: string,
  checkpointCommits: Array<{ sha: string; checkpointId: string; message: string; timestamp: string }>,
  token: string,
): Promise<void> {
  // Discover all trails in this repo
  const trailIds = await discoverTrailsFromBranch(repoFullName, token);
  if (trailIds.length === 0) return;

  // Fetch trail metadata + checkpoints only (skip discussion to reduce latency)
  const trailData = await fetchTrailMetadataAndCheckpointsBatch(repoFullName, trailIds, token);

  // Find trails whose branch matches the pushed branch
  for (const [trailId, trail] of trailData) {
    if (trail.metadata.branch !== branch) continue;

    // Build set of existing checkpoint IDs for deduplication
    const existingIds = new Set(trail.checkpoints.checkpoints.map((cp) => cp.checkpoint_id));

    // Filter to only new checkpoint refs
    const newRefs = checkpointCommits
      .filter((c) => !existingIds.has(c.checkpointId))
      .map((c) => ({
        checkpoint_id: c.checkpointId,
        commit_sha: c.sha,
        created_at: c.timestamp,
        summary: c.message,
      }));

    if (newRefs.length === 0) continue;

    // Prepend new refs (newest first) to existing checkpoints
    const merged = {
      checkpoints: [...newRefs, ...trail.checkpoints.checkpoints],
    };

    await updateTrailCheckpoints(
      repoFullName,
      trailId,
      merged,
      token,
      `Link ${newRefs.length} checkpoint(s) to trail ${trailId}`,
    );

    logCheckpointMetric("trail_checkpoints_linked", {
      repo: repoFullName,
      branch,
      trailId,
      count: newRefs.length,
    });
  }
}

// ============================================================================
// Trail merge detection
// ============================================================================

/**
 * Check if any trail's feature branch has been merged into the pushed base branch.
 * For each trail whose metadata.base matches the pushed branch, uses the GitHub
 * compare API to check if ahead_by === 0 (all feature branch commits are in base).
 */
async function checkAndMergeTrails(
  repoFullName: string,
  pushedBranch: string,
  beforeSha: string,
  token: string,
): Promise<void> {
  const trailIds = await discoverTrailsFromBranch(repoFullName, token);
  if (trailIds.length === 0) return;

  const trailData = await fetchTrailMetadataAndCheckpointsBatch(repoFullName, trailIds, token);
  const isNewBranch = beforeSha === "0000000000000000000000000000000000000000";

  for (const [trailId, trail] of trailData) {
    if (trail.metadata.base !== pushedBranch) continue;
    if (trail.metadata.status === "merged" || trail.metadata.status === "closed") continue;

    try {
      let merged = await isBranchMergedInto(repoFullName, pushedBranch, trail.metadata.branch, token);

      // If the branch ref is gone (deleted after merge), fall back to comparing
      // the latest checkpoint commit SHA — the SHA still exists in git even after
      // the branch ref is removed.
      if (merged === null && trail.checkpoints.checkpoints.length > 0) {
        const latestSha = trail.checkpoints.checkpoints[0].commit_sha;
        merged = await isBranchMergedInto(repoFullName, pushedBranch, latestSha, token);
      }

      if (!merged) continue;

      // Verify this push actually merged the branch by checking it wasn't already
      // incorporated before this push. This prevents false positives for branches
      // that were created from the base but never diverged.
      // Skip this check if the trail has checkpoints (real work was done) — we
      // want to mark it merged regardless, and this handles retries when a
      // previous merge detection succeeded but the metadata update failed.
      if (!isNewBranch && trail.checkpoints.checkpoints.length === 0) {
        const wasAlreadyIn = await isBranchMergedInto(repoFullName, beforeSha, trail.metadata.branch, token);
        if (wasAlreadyIn) continue;
      }

      const now = new Date().toISOString();
      const updatedMetadata = {
        ...trail.metadata,
        status: "merged" as const,
        merged_at: now,
        updated_at: now,
      };

      await updateTrailMetadata(
        repoFullName,
        trailId,
        updatedMetadata,
        token,
        `Merge trail ${trailId} (branch ${trail.metadata.branch} merged into ${pushedBranch})`,
      );

      console.log(`[trails-merge] merged trail=${trailId} repo=${repoFullName} branch=${trail.metadata.branch}`);
    } catch (err) {
      console.error(`[trails-merge] failed trail=${trailId} repo=${repoFullName}: ${err}`);
    }
  }
}

/**
 * Detect trail merges on push events. When a branch receives a push,
 * check if any trail's feature branch has been fully merged into it.
 */
async function processTrailMergeDetection(
  eventType: string,
  payload: Record<string, unknown>,
  db: Db,
  env: Env
): Promise<void> {
  if (eventType !== "push") return;

  const repo = payload.repository as Record<string, unknown> | undefined;
  if (!repo?.full_name) return;

  const ref = payload.ref as string | undefined;
  if (!ref?.startsWith("refs/heads/")) return;
  const branch = ref.replace("refs/heads/", "");

  // Skip special branches
  if (branch === CHECKPOINT_BRANCH || branch === TRAILS_BRANCH) return;

  // Skip branch deletions
  if (payload.deleted === true) return;

  const repoFullName = repo.full_name as string;

  const installationId = await validateInstallation(payload, db, `Trail merge detection ${repoFullName}`);
  if (installationId === null) return;

  let token: string;
  try {
    token = await getInstallationToken(
      installationId,
      { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
      env.ENTIRE_CACHE
    );
  } catch {
    return;
  }

  try {
    const before = (payload.before as string) || "";
    await checkAndMergeTrails(repoFullName, branch, before, token);
  } catch (err) {
    console.log(`[trails-merge] error repo=${repoFullName} branch=${branch} error=${err instanceof Error ? err.message : String(err)}`);
  }
}

// ============================================================================
// Trail webhook handlers
// ============================================================================

// Process push to TRAILS_BRANCH - sync trail metadata to database
export async function processTrailsPushEvent(
  eventType: string,
  payload: Record<string, unknown>,
  db: Db,
  env: Env
): Promise<void> {
  if (eventType !== "push") return;

  const repo = payload.repository as Record<string, unknown> | undefined;
  if (!repo?.full_name) return;

  const repoFullName = repo.full_name as string;
  const ref = payload.ref as string | undefined;

  // Only process pushes to TRAILS_BRANCH
  if (ref !== `refs/heads/${TRAILS_BRANCH}`) return;

  const deleted = payload.deleted as boolean | undefined;
  if (deleted) {
    console.log(`[trails-sync] trails_branch_deleted repo=${repoFullName}`);
    return;
  }

  // Find the global repo record
  const repoGithubId = repo.id as number;
  const repoRecord = await db.repos.getByGithubId(repoGithubId);
  if (!repoRecord) {
    console.log(`[trails-sync] skip_repo_not_found repo=${repoFullName}`);
    return;
  }

  // Validate installation exists before processing
  const installationId = await validateInstallation(payload, db, `Trails push ${repoFullName}`);
  if (installationId === null) {
    console.log(`[trails-sync] skip_no_installation repo=${repoFullName}`);
    return;
  }

  // Get app installation token
  let token: string;
  try {
    token = await getInstallationToken(
      installationId,
      {
        appId: env.GITHUB_CLIENT_ID,
        privateKey: env.GITHUB_APP_PRIVATE_KEY,
      },
      env.ENTIRE_CACHE
    );
  } catch (err) {
    console.log(`[trails-sync] installation_token_unavailable repo=${repoFullName} error=${err instanceof Error ? err.message : String(err)}`);
    throw err;
  }

  try {
    // Sync trails from the branch
    const result = await syncRepoTrails(db, repoRecord.id, repoFullName, token);
    console.log(`[trails-sync] completed repo=${repoFullName} status=${result.status} discovered=${result.trailsDiscovered} synced=${result.trailsSynced}`);
  } catch (err) {
    console.log(`[trails-sync] error repo=${repoFullName} error=${err instanceof Error ? err.message : String(err)}`);
    throw err;
  }
}

