import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { CheckpointsPage } from "./CheckpointsPage";
import "@testing-library/jest-dom/vitest";
import { ApiError } from "@/lib/api";
import type {
  CheckpointsResponse,
  CheckpointStatusResponse,
  BranchesResponse,
} from "../api";

// ---------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------

const mockFetchCheckpointStatus = vi.fn<() => Promise<CheckpointStatusResponse>>();
const mockFetchCheckpoints = vi.fn<() => Promise<CheckpointsResponse>>();
const mockFetchBranches = vi.fn<() => Promise<BranchesResponse>>();
const mockSearchCheckpoints = vi.fn<() => Promise<CheckpointsResponse>>();

vi.mock("../api", () => ({
  fetchCheckpointStatus: (...args: unknown[]) => mockFetchCheckpointStatus(...args),
  fetchCheckpoints: (...args: unknown[]) => mockFetchCheckpoints(...args),
  fetchBranches: (...args: unknown[]) => mockFetchBranches(...args),
  searchCheckpoints: (...args: unknown[]) => mockSearchCheckpoints(...args),
}));

vi.mock("@/domains/platform/components/Page", () => ({
  Page: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
}));

vi.mock("@/domains/platform/auth/api", () => ({
  getGitHubInstallationUrl: () => "https://github.com/apps/test/installations/new",
}));

vi.mock("@tanstack/react-router", () => ({
  useNavigate: () => vi.fn(),
  Link: ({ children, ...props }: { children: React.ReactNode; to: string }) => <a {...props}>{children}</a>,
}));

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function createQueryClient() {
  return new QueryClient({
    defaultOptions: {
      queries: { retry: false },
    },
  });
}

function renderPage(props = { org: "entireio", repo: "test-repo", branch: "main" }) {
  const queryClient = createQueryClient();
  return render(
    <QueryClientProvider client={queryClient}>
      <CheckpointsPage {...props} />
    </QueryClientProvider>,
  );
}

const CHECKPOINT = {
  commitSha: "abc123",
  commitMessage: "Add feature",
  commitAuthor: "Test User",
  commitAuthorUsername: "testuser",
  commitDate: new Date().toISOString(),
  additions: 50,
  deletions: 10,
  fileStats: [{ filename: "file.ts", status: "modified" as const, additions: 50, deletions: 10 }],
  filesTouched: ["file.ts"],
  checkpointId: "cp-1",
  sessions: [{ prompt: "Add feature", agent: "Claude Code", steps: 5 }],
  sessionCount: 1,
  totalSteps: 5,
  agents: ["Claude Code"],
  inputTokens: 1000,
  outputTokens: 500,
  attribution: null,
};

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe("CheckpointsPage", () => {
  beforeEach(() => {
    vi.clearAllMocks();

    // Default: branches returns main
    mockFetchBranches.mockResolvedValue({
      branches: ["main"],
      default_branch: "main",
      stored_default_branch: "main",
      from_cache: false,
    });
  });

  describe("repository not found", () => {
    it("shows the standard 404 page immediately when status 404s", async () => {
      mockFetchCheckpointStatus.mockRejectedValue(new Error("Repository not found"));
      mockFetchCheckpoints.mockRejectedValue(new Error("Repository not found"));

      renderPage();

      await waitFor(() => {
        expect(screen.getByText("404")).toBeInTheDocument();
      });
      expect(screen.getByText("Page Not Found")).toBeInTheDocument();
      expect(screen.queryByText("No checkpoints found")).not.toBeInTheDocument();
      expect(screen.queryByText("Install the CLI")).not.toBeInTheDocument();
    });
  });

  describe("branch not found", () => {
    it("shows branch-specific error, not the 404 page", async () => {
      mockFetchCheckpointStatus.mockResolvedValue({
        app_has_access: true,
        session_branch_exists: true,
        checkpoint_count: 5,
      });
      mockFetchCheckpoints.mockRejectedValue(new ApiError("Branch 'nonexistent' not found", 404));

      renderPage({ org: "entireio", repo: "test-repo", branch: "nonexistent" });

      await waitFor(() => {
        expect(screen.getByText("Branch not found")).toBeInTheDocument();
      });
      expect(screen.queryByText("404")).not.toBeInTheDocument();
      expect(screen.queryByText("Page Not Found")).not.toBeInTheDocument();
    });
  });

  describe("no access to repo", () => {
    it("shows grant-access empty state", async () => {
      mockFetchCheckpointStatus.mockResolvedValue({
        app_has_access: false,
        session_branch_exists: null,
        checkpoint_count: 0,
      });
      mockFetchCheckpoints.mockResolvedValue({
        checkpoints: [],
        repo_full_name: "entireio/test-repo",
        updated_at: new Date().toISOString(),
        from_cache: false,
        app_has_access: false,
        session_branch_exists: null,
      });

      renderPage();

      await waitFor(() => {
        expect(screen.getByText("Grant access to this repository")).toBeInTheDocument();
      });
      expect(screen.getByText("Configure GitHub App access")).toBeInTheDocument();
      expect(screen.queryByText("No checkpoints found")).not.toBeInTheDocument();
    });
  });

  describe("no checkpoints exist", () => {
    it("shows CLI installation empty state", async () => {
      // Status endpoint returns null for session_branch_exists (never false)
      mockFetchCheckpointStatus.mockResolvedValue({
        app_has_access: true,
        session_branch_exists: null,
        checkpoint_count: 0,
      });
      mockFetchCheckpoints.mockResolvedValue({
        checkpoints: [],
        repo_full_name: "entireio/test-repo",
        updated_at: new Date().toISOString(),
        from_cache: false,
        app_has_access: true,
        session_branch_exists: null,
      });

      renderPage();

      await waitFor(() => {
        expect(screen.getByText("No checkpoints found")).toBeInTheDocument();
      });
      expect(screen.getByText("Install the CLI")).toBeInTheDocument();
      expect(screen.queryByPlaceholderText("Search checkpoints...")).not.toBeInTheDocument();
    });

    it("does not show the skeleton loader", async () => {
      mockFetchCheckpointStatus.mockResolvedValue({
        app_has_access: true,
        session_branch_exists: null,
        checkpoint_count: 0,
      });
      // Delay checkpoints response to verify skeleton doesn't appear
      mockFetchCheckpoints.mockImplementation(
        () => new Promise((resolve) => setTimeout(() => resolve({
          checkpoints: [],
          repo_full_name: "entireio/test-repo",
          updated_at: new Date().toISOString(),
          from_cache: false,
          app_has_access: true,
          session_branch_exists: null,
        }), 100)),
      );

      renderPage();

      // Status resolves first, empty state shows without skeleton
      await waitFor(() => {
        expect(screen.getByText("No checkpoints found")).toBeInTheDocument();
      });
      expect(screen.queryByRole("list", { name: "Checkpoints" })).not.toBeInTheDocument();
    });
  });

  describe("checkpoints exist", () => {
    describe("no checkpoints on this branch", () => {
      it("shows branch-specific empty state with toolbar", async () => {
        mockFetchCheckpointStatus.mockResolvedValue({
          app_has_access: true,
          session_branch_exists: true,
          checkpoint_count: 5,
        });
        mockFetchCheckpoints.mockResolvedValue({
          checkpoints: [],
          repo_full_name: "entireio/test-repo",
          updated_at: new Date().toISOString(),
          from_cache: false,
          app_has_access: true,
          session_branch_exists: true,
        });

        renderPage({ org: "entireio", repo: "test-repo", branch: "feature-branch" });

        await waitFor(() => {
          expect(screen.getByText("No checkpoints on this branch")).toBeInTheDocument();
        });
        expect(screen.getByPlaceholderText("Search checkpoints...")).toBeInTheDocument();
        expect(screen.queryByText("No checkpoints found")).not.toBeInTheDocument();
      });
    });

    describe("checkpoints on this branch", () => {
      it("shows the checkpoint list", async () => {
        mockFetchCheckpointStatus.mockResolvedValue({
          app_has_access: true,
          session_branch_exists: true,
          checkpoint_count: 1,
        });
        mockFetchCheckpoints.mockResolvedValue({
          checkpoints: [CHECKPOINT],
          repo_full_name: "entireio/test-repo",
          updated_at: new Date().toISOString(),
          from_cache: false,
          app_has_access: true,
          session_branch_exists: true,
        });

        renderPage();

        await waitFor(() => {
          expect(screen.getByText("Add feature")).toBeInTheDocument();
        });
        expect(screen.getByPlaceholderText("Search checkpoints...")).toBeInTheDocument();
        expect(screen.getByRole("img", { name: "testuser" })).toBeInTheDocument();
      });

      it("shows skeleton while checkpoints load", async () => {
        mockFetchCheckpointStatus.mockResolvedValue({
          app_has_access: true,
          session_branch_exists: true,
          checkpoint_count: 5,
        });
        // Delay checkpoints response
        let resolveCheckpoints!: (value: CheckpointsResponse) => void;
        mockFetchCheckpoints.mockImplementation(
          () => new Promise((resolve) => { resolveCheckpoints = resolve; }),
        );

        renderPage();

        // Status resolves, skeleton should show because checkpoint_count > 0
        await waitFor(() => {
          expect(screen.getByPlaceholderText("Search checkpoints...")).toBeInTheDocument();
        });

        // Now resolve checkpoints
        resolveCheckpoints({
          checkpoints: [CHECKPOINT],
          repo_full_name: "entireio/test-repo",
          updated_at: new Date().toISOString(),
          from_cache: false,
          app_has_access: true,
          session_branch_exists: true,
        });

        await waitFor(() => {
          expect(screen.getByText("Add feature")).toBeInTheDocument();
        });
      });
    });
  });
});

