// Repo sync queue consumer and cron handler
// Processes checkpoint sync messages for individual repos

import { trace } from "@opentelemetry/api";
import type { Env } from "../env";
import { GitHubRateLimitError } from "./github";
import {
  queueRepoSyncBatch,
  syncRepoCheckpoints,
  type RepoSyncMessage,
} from "./repo-sync-service";
import { getDb } from "./db";
import type { Db } from "./db/db-types";
import { avgMs, errorString, generateBatchId, traced } from "./telemetry";
import { getInstallationToken } from "./token";
import { queueUserRepoSyncBatch } from "./user-repo-sync";
import type { SearchIndexMessage } from "./search-index-queue";

export type { RepoSyncMessage } from "./repo-sync-service";

// TTL for sync:lastUpdate KV entries (7 days)
const SYNC_LAST_UPDATE_TTL = 60 * 60 * 24 * 7;

// Log with consistent prefix
function log(event: string, data: Record<string, unknown>): void {
  console.log(`[repo-sync-queue] ${event}`, JSON.stringify(data));
}

// KV key for per-installation rate limit state
function rateLimitKey(installationId: number): string {
  return `github:ratelimit:installation:${installationId}:resetAt`;
}

// Check if a specific installation is currently rate limited
async function isRateLimited(cache: KVNamespace, installationId: number): Promise<boolean> {
  const key = rateLimitKey(installationId);
  const resetAt = await cache.get(key);
  if (!resetAt) return false;

  const resetTime = parseInt(resetAt, 10);
  if (Date.now() < resetTime) {
    return true;
  }

  // Rate limit has expired, clean up
  await cache.delete(key);
  return false;
}

// Set rate limit marker for a specific installation (called when we hit a rate limit)
async function setRateLimitMarker(
  cache: KVNamespace,
  installationId: number,
  resetAt?: number,
): Promise<void> {
  // Default to 15 minutes from now if no reset time provided
  const resetTime = resetAt ?? Date.now() + 15 * 60 * 1000;
  // Store with TTL of 1 hour (self-cleaning)
  await cache.put(rateLimitKey(installationId), String(resetTime), {
    expirationTtl: 60 * 60,
  });
  log("rate_limit_set", { installationId, resetAt: new Date(resetTime).toISOString() });
}

// Notify users with access to a repo that data has been updated
// This triggers frontend polling to detect the change and refresh
// Note: This function never throws - errors are logged and swallowed
// to avoid affecting the main sync flow (notification is best-effort)
async function notifyUsersOfRepoUpdate(
  db: Db,
  cache: KVNamespace,
  repoId: string
): Promise<number> {
  try {
    // Get all users with access to this repo (reuse existing utility)
    const userIds = await db.repos.getUsersForRepo(repoId);

    if (userIds.length === 0) {
      return 0;
    }

    // Update sync:lastUpdate for each user
    const now = String(Date.now());
    await Promise.all(
      userIds.map((userId) =>
        cache.put(`sync:lastUpdate:${userId}`, now, {
          expirationTtl: SYNC_LAST_UPDATE_TTL,
        })
      )
    );

    return userIds.length;
  } catch (err) {
    log("notify_users_error", {
      repoId,
      error: errorString(err),
    });
    return 0;
  }
}

// Type guard to check if a message is a RepoSyncMessage
export function isRepoSyncMessage(msg: unknown): msg is RepoSyncMessage {
  return (
    typeof msg === "object" &&
    msg !== null &&
    "repoId" in msg &&
    "reason" in msg &&
    "priority" in msg &&
    "queuedAt" in msg &&
    typeof (msg as RepoSyncMessage).repoId === "string" &&
    typeof (msg as RepoSyncMessage).reason === "string" &&
    typeof (msg as RepoSyncMessage).priority === "number"
  );
}

// Look up the GitHub App installation ID for a repo
async function getRepoInstallationId(
  db: Db,
  repoId: string,
): Promise<number | null> {
  const repo = await db.repos.getById(repoId);

  if (!repo) {
    log("repo_not_found", { repoId });
    return null;
  }

  // Fast path: use the direct FK if available
  if (repo.installation_id) {
    const githubInstallationId = await db.installations.getGithubId(repo.installation_id);
    if (githubInstallationId) {
      return githubInstallationId;
    }
  }

  // NB: This fallback shouldn't be required for long.
  // Fallback: look up by owner name (for repos not yet backfilled)
  const owner = repo.full_name.split("/")[0];
  const githubInstallationId = await db.installations.getGithubIdByOwner(owner);
  if (!githubInstallationId) {
    log("no_installation_for_repo", { repoId, owner });
    return null;
  }

  return githubInstallationId;
}

// Get a valid token for a GitHub App installation
async function getTokenForInstallation(
  installationId: number,
  env: Env,
): Promise<string | null> {
  try {
    return await getInstallationToken(
      installationId,
      {
        appId: env.GITHUB_CLIENT_ID,
        privateKey: env.GITHUB_APP_PRIVATE_KEY,
      },
      env.ENTIRE_CACHE,
    );
  } catch (err) {
    log("installation_token_error", {
      installationId,
      error: errorString(err),
    });
    return null;
  }
}

// Process a batch of repo sync messages
export async function processRepoSyncBatch(
  batch: MessageBatch<RepoSyncMessage>,
  env: Env,
): Promise<void> {
  const batchStartTime = Date.now();
  const batchId = generateBatchId();

  // Calculate queue wait times for all messages in batch
  const queueWaitTimes = batch.messages.map(
    (msg) => Date.now() - msg.timestamp.getTime(),
  );
  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;

  log("batch_started", {
    batchId,
    queue: batch.queue,
    count: batch.messages.length,
    avgQueueWaitMs: avgMs(queueWaitTimes),
    maxQueueWaitMs: maxWaitMs,
  });

  const db = getDb(env);
  const processingTimes: number[] = [];
  let successCount = 0;
  let errorCount = 0;
  let skippedCount = 0;

  for (let i = 0; i < batch.messages.length; i++) {
    const msg = batch.messages[i];
    const msgStartTime = Date.now();
    const { repoId, reason } = msg.body;
    const queueWaitMs = Date.now() - msg.timestamp.getTime();

    let installationId: number | null = null;
    try {
      // Look up installation for rate limit checks
      installationId = await getRepoInstallationId(db, repoId);

      if (!installationId) {
        log("no_installation_for_repo", { batchId, repoId, reason });
        msg.ack();
        skippedCount++;
        continue;
      }

      // Check if this installation is rate limited
      if (await isRateLimited(env.ENTIRE_CACHE, installationId)) {
        log("message_skipped_rate_limited", { batchId, repoId, installationId, reason });
        msg.retry();
        skippedCount++;
        continue;
      }

      // Get a token for this installation
      const token = await getTokenForInstallation(installationId, env);

      if (!token) {
        log("no_token_for_repo", { batchId, repoId, installationId, reason });
        // Can't sync without a token - ack to avoid infinite retries
        // The repo will be picked up again on next reconciliation
        msg.ack();
        skippedCount++;
        continue;
      }

      // For user_sync, skip if repo was already synced (another job got there first)
      // This prevents duplicate work when multiple users log in for the same repo
      if (reason === "user_sync" && await db.repos.isCheckpointsSynced(repoId)) {
        log("skip_already_synced", { batchId, repoId, reason });
        msg.ack();
        skippedCount++;
        continue;
      }

      const result = await traced("repo-sync-queue.processMessage", async () => {
        const span = trace.getActiveSpan();
        span?.setAttribute("queue.message_wait_ms", queueWaitMs);
        span?.setAttribute("github.installation_id", installationId!);

        return await syncRepoCheckpoints(db, repoId, token);
      });
      const processingMs = Date.now() - msgStartTime;
      processingTimes.push(processingMs);

      log("message_processed", {
        batchId,
        messageIndex: i + 1,
        totalMessages: batch.messages.length,
        repoId,
        reason,
        result: result.status,
        skipReason: result.reason,
        checkpoints: result.checkpointsDiscovered,
        queueWaitMs,
        processingMs,
        attempt: msg.attempts,
      });

      msg.ack();
      if (result.status === "ok") {
        successCount++;
        // Notify users so frontend refreshes
        const usersNotified = await notifyUsersOfRepoUpdate(db, env.ENTIRE_CACHE, repoId);
        if (usersNotified > 0) {
          log("users_notified", { repoId, usersNotified });
        }
        // Queue discovered checkpoints for transcript storage + search indexing
        const cpIds = result.discoveredCheckpointIds;
        if (cpIds && cpIds.length > 0 && env.SEARCH_INDEX_QUEUE) {
          const SEARCH_BATCH_SIZE = 50;
          for (let j = 0; j < cpIds.length; j += SEARCH_BATCH_SIZE) {
            await env.SEARCH_INDEX_QUEUE.send({
              repoId,
              checkpointIds: cpIds.slice(j, j + SEARCH_BATCH_SIZE),
              queuedAt: new Date().toISOString(),
            } satisfies SearchIndexMessage);
          }
          log("search_index_queued", { repoId, checkpointCount: cpIds.length });
        }
      } else if (result.status === "error") {
        errorCount++;
      } else {
        skippedCount++;
      }
    } catch (err) {
      const processingMs = Date.now() - msgStartTime;
      processingTimes.push(processingMs);
      errorCount++;

      // Check if this is a rate limit error
      if (err instanceof GitHubRateLimitError) {
        log("rate_limit_hit", {
          batchId,
          repoId,
          installationId,
          reason,
          resetAt: err.resetAt
            ? new Date(err.resetAt * 1000).toISOString()
            : undefined,
          processingMs,
        });

        // Set the rate limit marker for this installation only
        if (installationId) {
          await setRateLimitMarker(
            env.ENTIRE_CACHE,
            installationId,
            err.resetAt ? err.resetAt * 1000 : undefined,
          );
        }

        // Retry only this message; continue processing remaining
        // (they may belong to different installations)
        msg.retry();
        continue;
      }

      log("message_error", {
        batchId,
        repoId,
        reason,
        attempt: msg.attempts,
        processingMs,
        error: errorString(err),
      });

      // Retry if not at max attempts (max_retries is configured in wrangler.jsonc)
      msg.retry();
    }
  }

  const totalBatchTimeMs = Date.now() - batchStartTime;

  log("batch_complete", {
    batchId,
    count: batch.messages.length,
    successCount,
    errorCount,
    skippedCount,
    totalBatchTimeMs,
    avgProcessingMs: avgMs(processingTimes),
    throughputPerMin:
      totalBatchTimeMs > 0
        ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
        : 0,
  });
}

// Reconciliation options
export interface ReconciliationOptions {
  force?: boolean; // Skip staleness check and queue all repos
  repoFullName?: string; // Target a specific repo by full name (e.g., "owner/repo")
  repoIds?: string[]; // Target specific repos by ID
}

// Reconciliation result
export interface ReconciliationResult {
  reposQueued: number;
  usersQueued: number;
  targetedRepo?: string; // The repo that was targeted (if any)
}

// Daily reconciliation cron handler
// Queues stale repos for checkpoint sync and identifies stale users
export async function handleReconciliationCron(
  env: Env,
  options: ReconciliationOptions = {},
): Promise<ReconciliationResult> {
  const now = new Date();
  const staleThreshold = new Date(
    now.getTime() - 24 * 60 * 60 * 1000,
  ).toISOString();
  const isTargeted = !!(options.repoFullName || options.repoIds?.length);

  log("cron_started", {
    threshold: staleThreshold,
    force: options.force ?? false,
    targeted: isTargeted,
    repoFullName: options.repoFullName,
    repoIds: options.repoIds,
  });

  const db = getDb(env);

  // A. Queue repos for checkpoint reconciliation
  let reposToQueue: { id: string; full_name: string }[];
  try {
    reposToQueue = await db.repos.getForReconciliation({
      repoFullName: options.repoFullName,
      repoIds: options.repoIds,
      force: options.force,
      staleThreshold,
    });
  } catch (err) {
    if (options.repoFullName) {
      log("cron_error_repo_not_found", {
        repoFullName: options.repoFullName,
        error: errorString(err),
      });
      return { reposQueued: 0, usersQueued: 0, targetedRepo: options.repoFullName };
    }
    log("cron_error_fetching_repos", { error: errorString(err) });
    return { reposQueued: 0, usersQueued: 0 };
  }

  const reposQueued = await queueRepoSyncBatch(
    env.REPO_SYNC_QUEUE,
    reposToQueue,
    "reconciliation",
    1,
  );

  // B. Queue stale users for repo sync (skip if targeting specific repos)
  let usersQueued = 0;
  if (!isTargeted) {
    try {
      const staleUsers = await db.refreshState.getStaleUsers(staleThreshold, 100);
      usersQueued = await queueUserRepoSyncBatch(
        env.USER_REPO_SYNC_QUEUE,
        staleUsers,
        "reconciliation",
      );
    } catch (err) {
      log("cron_error_fetching_users", { error: errorString(err) });
    }
  }

  const result: ReconciliationResult = {
    reposQueued,
    usersQueued,
    targetedRepo: options.repoFullName,
  };

  log("cron_complete", { ...result });

  return result;
}

