        is_private: r.private,
        pushed_at: r.pushed_at || r.updated_at,
        default_branch: r.default_branch,
        permission: getPermissionLevel(r.permissions),
      });
    }

    // Add installation repos that aren't already in the map
    const installationRepoIds = new Set<number>();
    for (const repos of installationReposResults) {
      if (repos) {
        for (const repo of repos) {
          installationRepoIds.add(repo.github_id);
          if (!reposByGithubId.has(repo.github_id)) {
            reposByGithubId.set(repo.github_id, {
              github_id: repo.github_id,
              name: repo.name,
              full_name: repo.full_name,
              description: repo.description,
              html_url: repo.html_url,
              language: repo.language,
              stargazers_count: repo.stargazers_count,
              is_fork: repo.is_fork,
              is_private: repo.is_private,
              pushed_at: repo.pushed_at,
              default_branch: repo.default_branch,
              permission: "read",
            });
          }
        }
      }
    }

    // Convert map to array for upsert
    const reposToUpsert = Array.from(reposByGithubId.values());

    // Upsert all repos with installation repo IDs for app_has_access
    await db.repos.upsertForUser(
      userId,
      reposToUpsert,
      installationRepoIds,
      c.env.ENTIRE_CACHE,
    );

    // Delete repos that no longer exist (include both OAuth and installation repos)
    const currentGithubIds = Array.from(reposByGithubId.keys());
    await db.repos.deleteStaleForUser(userId, currentGithubIds);

    // Get non-fork repos for PRs (include forks with explicit app access)
    const nonForkRepos = reposToUpsert.filter((r) => !r.is_fork || installationRepoIds.has(r.github_id));
    const repoNames = nonForkRepos.map((r) => r.full_name);

    // Record sync start time before fetching PRs from GitHub
    // This prevents race conditions with webhooks that may insert PRs during sync
    const syncStartTime = new Date().toISOString();

    // Fetch PRs from GitHub
    const prs = await fetchUserPRs(repoNames, token);

    // Persist PRs to database
    const prData: GitHubPRData[] = prs.map((pr) => ({
      github_pr_id: pr.id,
      number: pr.number,
      title: pr.title,
      html_url: pr.html_url,
      state: pr.state,
      draft: pr.draft,
      created_at: pr.created_at,
      updated_at: pr.updated_at,
      repo_full_name: pr.repo_full_name,
    }));
    await db.prs.upsertPRsForUser(userId, prData);

    // Delete PRs that are no longer open (only those that existed before sync started)
    const currentPRIds = prs.map((pr) => pr.id);
    await db.prs.deleteStalePRsForUser(
      userId,
      currentPRIds,
      syncStartTime,
    );

    const now = new Date().toISOString();

    // Return the synced repos with PRs
    // checkpoint_count is null until checkpoint sync runs (indicates "unknown" vs "zero")
    const repos = nonForkRepos.map((r) => ({
      name: r.name,
      full_name: r.full_name,
      description: r.description,
      html_url: r.html_url,
      stargazers_count: r.stargazers_count,
      language: r.language,
      private: r.is_private,
      updated_at: r.pushed_at || new Date().toISOString(),
      permission: r.permission,
      checkpoint_count: null,
    }));

    return c.json({
      repos,
      prs,
      updated_at: now,
      synced: true,
      total_synced: reposToUpsert.length,
    });
  } catch (err) {
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error("Failed to sync repos:", err);
    recordSpanError(err);
    return c.json({ error: "Failed to sync repos" }, 500);
  }
});

