/**
 * Backfill script: Index checkpoints into Turbopuffer for full-text + semantic search.
 *
 * Usage:
 *   npx tsx scripts/backfill-search.ts [options]
 *
 * Options:
 *   --repo <full_name>     Only backfill a specific repo (e.g., "entireio/cli")
 *   --with-transcripts     Fetch transcript excerpts from GitHub (slower, needs GITHUB_TOKEN)
 *   --dry-run              Show what would be indexed without writing to Turbopuffer
 *   --limit <n>            Max checkpoints per repo (for testing)
 *
 * Environment:
 *   DATABASE_URL           MySQL connection string (defaults to local Docker MySQL)
 *   TURBOPUFFER_API_KEY    Turbopuffer API key (required unless --dry-run)
 *   OPENAI_API_KEY         OpenAI API key for embeddings (required unless --dry-run)
 *   GITHUB_TOKEN           GitHub PAT with repo read access (required for --with-transcripts)
 */

import { Kysely, MysqlDialect } from "kysely";
import { createPool } from "mysql2";
import type { DB } from "../db/types";
import OpenAI from "openai";
import { getParserForAgent } from "../src/lib/transcript-parsers/registry";

// --- Config ---

const EMBEDDING_MODEL = "text-embedding-3-small";
const EMBEDDING_DIMENSIONS = 1536;
const CHUNK_SIZE = 50; // process checkpoints in chunks of 50 (fetch transcripts + embed + upsert per chunk)
const CHECKPOINT_BRANCH = "entire/checkpoints/v1";
const GITHUB_API = "https://api.github.com";
const TRANSCRIPT_CONCURRENCY = 15; // parallel GitHub API fetches per chunk
const MAX_TRANSCRIPT_CHARS = 200_000; // generous limit for user prompts + AI responses
const MAX_FILTERABLE_BYTES = 3800; // Turbopuffer 4 KiB limit on filterable attributes
const MAX_TEXT_BYTES = 500_000; // text field is non-filterable (8 MiB limit), generous cap for BM25
const MAX_EMBEDDING_CHARS = 25000; // ~8K tokens, text-embedding-3-small limit is 8192 tokens
const MAX_RETRIES = 3;
const RETRY_BASE_DELAY_MS = 1000;

// --- CLI Argument Parsing ---

interface CliOptions {
  repo: string | null;
  withTranscripts: boolean;
  dryRun: boolean;
  limit: number | null;
}

function parseArgs(): CliOptions {
  const args = process.argv.slice(2);
  const options: CliOptions = {
    repo: null,
    withTranscripts: false,
    dryRun: false,
    limit: null,
  };

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case "--repo":
        options.repo = args[++i];
        if (!options.repo) {
          console.error("Error: --repo requires a value (e.g., 'entireio/cli')");
          process.exit(1);
        }
        break;
      case "--with-transcripts":
        options.withTranscripts = true;
        break;
      case "--dry-run":
        options.dryRun = true;
        break;
      case "--limit":
        options.limit = parseInt(args[++i], 10);
        if (isNaN(options.limit) || options.limit <= 0) {
          console.error("Error: --limit requires a positive integer");
          process.exit(1);
        }
        break;
      default:
        console.error(`Unknown option: ${args[i]}`);
        console.error("Usage: npx tsx scripts/backfill-search.ts [--repo <name>] [--with-transcripts] [--dry-run] [--limit <n>]");
        process.exit(1);
    }
  }

  return options;
}

// --- Database Setup ---

function createDb(): Kysely<DB> {
  const url = process.env.DATABASE_URL ?? "mysql://entire:entire@localhost:3306/entire";
  const parsed = new URL(url);
  const isLocalhost = parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1";

  return new Kysely<DB>({
    dialect: new MysqlDialect({
      pool: createPool({
        host: parsed.hostname,
        port: Number(parsed.port) || 3306,
        user: decodeURIComponent(parsed.username),
        password: decodeURIComponent(parsed.password),
        database: parsed.pathname.replace("/", ""),
        ssl: isLocalhost ? undefined : { rejectUnauthorized: true },
      }),
    }),
  });
}

// --- Text Construction ---

function buildSearchText(
  checkpoint: CheckpointRow,
  transcriptExcerpt?: string,
): string {
  const parts: string[] = [];

  if (checkpoint.prompt) {
    parts.push(`Prompt: ${checkpoint.prompt}`);
  }
  if (checkpoint.commit_message) {
    parts.push(`Commit: ${checkpoint.commit_message}`);
  }
  if (checkpoint.files_touched_str) {
    parts.push(`Files: ${checkpoint.files_touched_str}`);
  }
  if (transcriptExcerpt) {
    parts.push(`Transcript: ${transcriptExcerpt}`);
  }

  return parts.join("\n");
}

// --- Embedding Generation ---

async function generateEmbeddings(
  openai: OpenAI,
  texts: string[],
): Promise<number[][]> {
  const response = await openai.embeddings.create({
    model: EMBEDDING_MODEL,
    input: texts,
    dimensions: EMBEDDING_DIMENSIONS,
  });

  // Sort by index to maintain order
  return response.data
    .sort((a, b) => a.index - b.index)
    .map((item) => item.embedding);
}

// --- Attribute Truncation ---

function truncateToBytes(str: string | null, maxBytes: number): string | null {
  if (str === null) return null;
  // Fast path: ASCII strings where 1 char = 1 byte
  if (str.length <= maxBytes) return str;
  // Truncate by encoding to bytes
  const encoder = new TextEncoder();
  const encoded = encoder.encode(str);
  if (encoded.length <= maxBytes) return str;
  // Find the last valid UTF-8 boundary within maxBytes
  const truncated = encoded.slice(0, maxBytes);
  const decoder = new TextDecoder("utf-8", { fatal: false });
  return decoder.decode(truncated);
}

// --- Fetch with Retry ---

async function fetchWithRetry(
  url: string,
  options: RequestInit,
): Promise<Response> {
  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    try {
      const response = await fetch(url, options);
      // Retry on transient server errors and rate limits
      if (response.status >= 500 || response.status === 429) {
        if (attempt < MAX_RETRIES - 1) {
          const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
          await sleep(delay);
          continue;
        }
      }
      return response;
    } catch (err) {
      if (attempt < MAX_RETRIES - 1) {
        const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
        await sleep(delay);
        continue;
      }
      throw err;
    }
  }
  throw new Error("fetchWithRetry: exhausted retries");
}

// --- Transcript Fetching ---

async function fetchTranscriptExcerpt(
  repoFullName: string,
  checkpointId: string,
  agent: string,
  token: string,
): Promise<string | null> {
  const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
  const path = `${folder}/0/full.jsonl`;

  // Encode each path segment individually (preserves / separators)
  const encodedPath = path.split("/").map(encodeURIComponent).join("/");
  const url = `${GITHUB_API}/repos/${repoFullName}/contents/${encodedPath}?ref=${CHECKPOINT_BRANCH}`;

  try {
    const response = await fetchWithRetry(url, {
      headers: {
        Accept: "application/vnd.github.raw+json",
        Authorization: `Bearer ${token}`,
        "User-Agent": "entire-backfill",
        "X-GitHub-Api-Version": "2022-11-28",
      },
    });

    if (!response.ok) {
      if (response.status === 404) {
        return null;
      }
      return null;
    }

    const content = await response.text();

    const parser = getParserForAgent(agent);
    const result = parser.parse(content);

    if (result.messages.length === 0) {
      return null;
    }

    // Extract all user prompts + assistant responses, excluding tool-only messages
    const parts: string[] = [];
    let charsUsed = 0;

    for (const msg of result.messages) {
      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;

      // Skip assistant messages that are just tool calls with no text
      if (msg.role === "assistant" && msg.toolCalls?.length && !msg.content.trim()) {
        continue;
      }

      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
      const text = msg.content.slice(0, remaining);
      parts.push(`[${msg.role}]: ${text}`);
      charsUsed += text.length;
    }

    return parts.join("\n") || null;
  } catch {
    return null;
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// --- Types ---

interface CheckpointRow {
  checkpoint_id: string;
  branch: string;
  agent: string;
  commit_author_username: string | null;
  created_at: string | null;
  commit_sha: string | null;
  commit_message: string | null;
  prompt: string | null;
  files_touched_str: string | null;
}

interface RepoRow {
  id: string;
  github_id: number;
  full_name: string;
  checkpoint_count: number;
}

// --- Per-Repo Processing ---

async function fetchCheckpointsForRepo(
  db: Kysely<DB>,
  repoId: string,
  limit: number | null,
): Promise<CheckpointRow[]> {
  // Use the same deferred-join pattern as getCheckpointsForBranch
  let idQuery = db
    .selectFrom("repo_checkpoint_commits")
    .select("id")
    .where("repo_id", "=", repoId)
    .orderBy("commit_date", "desc");

  if (limit) {
    idQuery = idQuery.limit(limit);
  }

  const idRows = await idQuery.execute();
  if (idRows.length === 0) return [];

  const rows = await db
    .selectFrom("repo_checkpoint_commits as cc")
    .leftJoin("repo_checkpoints as cp", (join) =>
      join
        .onRef("cp.repo_id", "=", "cc.repo_id")
        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
    )
    .select([
      "cc.checkpoint_id",
      "cc.branch",
      "cc.commit_sha",
      "cc.commit_message",
      "cc.commit_author_username",
      "cc.commit_date",
      "cp.prompt",
      "cp.agent",
      "cp.created_at",
      "cp.files_touched",
    ])
    .where(
      "cc.id",
      "in",
      idRows.map((r) => r.id),
    )
    .execute();

  return rows.map((row) => {
    const filesTouched = row.files_touched as string[] | null;
    return {
      checkpoint_id: row.checkpoint_id,
      branch: row.branch,
      agent: row.agent ?? "Claude Code",
      commit_author_username: row.commit_author_username,
      created_at: row.created_at?.toISOString() ?? row.commit_date?.toISOString() ?? null,
      commit_sha: row.commit_sha,
      commit_message: row.commit_message,
      prompt: row.prompt,
      files_touched_str: filesTouched?.join(", ") ?? null,
    };
  });
}

function formatElapsed(ms: number): string {
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  return `${m}m${s % 60}s`;
}

async function processRepo(
  db: Kysely<DB>,
  openai: OpenAI,
  repo: RepoRow,
  options: CliOptions,
): Promise<{ indexed: number; skipped: number }> {
  const start = Date.now();
  const total = repo.checkpoint_count;
  console.log(`\n--- ${repo.full_name} (${total} checkpoints) ---`);

  const checkpoints = await fetchCheckpointsForRepo(db, repo.id, options.limit);
  if (checkpoints.length === 0) {
    console.log(`  No checkpoint commits found, skipping.`);
    return { indexed: 0, skipped: 0 };
  }

  console.log(`  Fetched ${checkpoints.length} checkpoint rows from DB.`);

  const githubToken = process.env.GITHUB_TOKEN;
  const namespaceName = `checkpoints-gh-${repo.github_id}`;
  const turbopufferApiKey = process.env.TURBOPUFFER_API_KEY ?? "";
  let totalIndexed = 0;
  let totalSkipped = 0;
  let totalTranscripts = 0;

  // Process in chunks: for each chunk, fetch transcripts -> build text -> embed -> upsert
  const numChunks = Math.ceil(checkpoints.length / CHUNK_SIZE);

  for (let chunkIdx = 0; chunkIdx < numChunks; chunkIdx++) {
    const chunkStart = chunkIdx * CHUNK_SIZE;
    const chunkEnd = Math.min(chunkStart + CHUNK_SIZE, checkpoints.length);
    const chunk = checkpoints.slice(chunkStart, chunkEnd);
    const chunkNum = chunkIdx + 1;
    const elapsed = formatElapsed(Date.now() - start);

    console.log(`  [${chunkNum}/${numChunks}] Processing checkpoints ${chunkStart + 1}-${chunkEnd} of ${checkpoints.length} (${elapsed})`);

    // 1. Fetch transcripts for this chunk (parallel with concurrency limit)
    let transcripts: (string | undefined)[];
    if (options.withTranscripts && githubToken) {
      transcripts = new Array(chunk.length).fill(undefined);
      let found = 0;

      // Process in batches of TRANSCRIPT_CONCURRENCY
      for (let batchStart = 0; batchStart < chunk.length; batchStart += TRANSCRIPT_CONCURRENCY) {
        const batchEnd = Math.min(batchStart + TRANSCRIPT_CONCURRENCY, chunk.length);
        const batch = chunk.slice(batchStart, batchEnd);
        const results = await Promise.all(
          batch.map((cp) =>
            fetchTranscriptExcerpt(repo.full_name, cp.checkpoint_id, cp.agent, githubToken),
          ),
        );
        for (let i = 0; i < results.length; i++) {
          transcripts[batchStart + i] = results[i] ?? undefined;
          if (results[i]) found++;
        }
      }

      totalTranscripts += found;
      console.log(`    Transcripts: ${found}/${chunk.length} found`);
    } else {
      transcripts = new Array(chunk.length).fill(undefined);
    }

    // 2. Build search text for each checkpoint
    const texts: string[] = [];
    const validIndices: number[] = []; // indices within this chunk that have non-empty text
    let chunkSkipped = 0;

    for (let i = 0; i < chunk.length; i++) {
      const text = buildSearchText(chunk[i], transcripts[i]);
      if (!text.trim()) {
        chunkSkipped++;
        continue;
      }
      texts.push(text);
      validIndices.push(i);
    }

    totalSkipped += chunkSkipped;

    if (texts.length === 0) {
      console.log(`    All empty, skipped.`);
      continue;
    }

    if (options.dryRun) {
      console.log(`    [DRY RUN] Would index ${texts.length} (${chunkSkipped} skipped)`);
      totalIndexed += texts.length;
      continue;
    }

    // 3. Truncate texts to stay under embedding model token limit
    const embeddingTexts = texts.map((t) => t.slice(0, MAX_EMBEDDING_CHARS));

    // 4. Generate embeddings
    let embeddings: number[][];
    try {
      embeddings = await generateEmbeddings(openai, embeddingTexts);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`    Embedding failed for chunk ${chunkNum}: ${msg.slice(0, 200)}`);
      console.error(`    Skipping chunk, continuing...`);
      totalSkipped += texts.length;
      continue;
    }
    console.log(`    Embedded ${texts.length} checkpoints`);

    // 5. Upsert to Turbopuffer
    const vectors = validIndices.map((localIdx, j) => {
      const cp = chunk[localIdx];
      const globalId = chunkStart + localIdx + 1; // unique ID across all chunks
      return {
        id: globalId,
        vector: embeddings[j],
        attributes: {
          checkpoint_id: cp.checkpoint_id,
          branch: cp.branch,
          agent: cp.agent,
          author: cp.commit_author_username,
          created_at: cp.created_at,
          commit_sha: cp.commit_sha,
          commit_message: truncateToBytes(cp.commit_message, MAX_FILTERABLE_BYTES),
          prompt: truncateToBytes(cp.prompt, MAX_FILTERABLE_BYTES),
          files_touched: truncateToBytes(cp.files_touched_str, MAX_FILTERABLE_BYTES),
          text: truncateToBytes(texts[j], MAX_TEXT_BYTES),
        },
      };
    });

    // Use raw API instead of SDK — the SDK doesn't pass schema through
    const upsertUrl = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespaceName)}`;
    try {
      const resp = await fetchWithRetry(upsertUrl, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${turbopufferApiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          upserts: vectors,
          distance_metric: "cosine_distance",
          schema: {
            text: {
              type: "string",
              filterable: false,
              full_text_search: {
                language: "english",
                stemming: true,
                remove_stopwords: true,
              },
            },
          },
        }),
      });
      if (!resp.ok) {
        const errText = await resp.text().catch(() => "");
        throw new Error(errText);
      }
      totalIndexed += texts.length;
      console.log(`    Upserted ${texts.length} to Turbopuffer (${totalIndexed} total)`);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`    Upsert failed for chunk ${chunkNum}: ${msg.slice(0, 200)}`);
      console.error(`    Skipping chunk, continuing...`);
      totalSkipped += texts.length;
    }
  }

  const elapsed = formatElapsed(Date.now() - start);
  console.log(`  Done: ${totalIndexed} indexed, ${totalSkipped} skipped, ${totalTranscripts} transcripts (${elapsed})`);

  return { indexed: totalIndexed, skipped: totalSkipped };
}

// --- Main ---

async function main() {
  const options = parseArgs();

  // Validate env vars
  if (!options.dryRun) {
    if (!process.env.TURBOPUFFER_API_KEY) {
      console.error("Error: TURBOPUFFER_API_KEY is required (or use --dry-run)");
      process.exit(1);
    }
    if (!process.env.OPENAI_API_KEY) {
      console.error("Error: OPENAI_API_KEY is required (or use --dry-run)");
      process.exit(1);
    }
  }

  if (options.withTranscripts && !process.env.GITHUB_TOKEN) {
    console.error("Error: GITHUB_TOKEN is required when using --with-transcripts");
    process.exit(1);
  }

  const db = createDb();

  const openai = new OpenAI({
    apiKey: process.env.OPENAI_API_KEY ?? "",
  });

  console.log("Backfill Search Index");
  console.log("=====================");
  if (options.dryRun) console.log("[DRY RUN MODE]");
  if (options.repo) console.log(`Repo filter: ${options.repo}`);
  if (options.limit) console.log(`Limit: ${options.limit} checkpoints per repo`);
  if (options.withTranscripts) console.log("Transcript fetching: enabled");

  // Fetch repos that have actual checkpoint commit rows (not just checkpoint_count > 0,
  // which can be stale). This ensures we only index repos with real data.
  let repoQuery = db
    .selectFrom("repos")
    .innerJoin("repo_checkpoint_commits", "repo_checkpoint_commits.repo_id", "repos.id")
    .select([
      "repos.id",
      "repos.github_id",
      "repos.full_name",
      db.fn.countAll<number>().as("checkpoint_count"),
    ])
    .groupBy(["repos.id", "repos.github_id", "repos.full_name"]);

  if (options.repo) {
    repoQuery = repoQuery.where("repos.full_name", "=", options.repo);
  }

  const repos = (await repoQuery.execute()) as RepoRow[];

  if (repos.length === 0) {
    console.log("\nNo repos with checkpoints found.");
    await db.destroy();
    return;
  }

  console.log(`\nFound ${repos.length} repo(s) with checkpoints.`);

  // Process each repo
  let totalIndexed = 0;
  let totalSkipped = 0;

  for (const repo of repos) {
    try {
      const result = await processRepo(db, openai, repo, options);
      totalIndexed += result.indexed;
      totalSkipped += result.skipped;
    } catch (err) {
      console.error(`\nError processing ${repo.full_name}:`, err);
      console.error("Continuing with next repo...");
    }
  }

  // Summary
  console.log("\n=====================");
  console.log("Summary:");
  console.log(`  Repos processed: ${repos.length}`);
  console.log(`  Checkpoints indexed: ${totalIndexed}`);
  console.log(`  Checkpoints skipped: ${totalSkipped}`);

  await db.destroy();
}

main();

