  2→
  3→import type { Context } from "hono";
  4→import { refreshAccessToken } from "./github";
  5→import { decrypt, encrypt } from "./crypto";
  6→import type { User } from "../types";
  7→import type { Db } from "./db/db-types";
  8→import type { Env } from "../env";
  9→import { errorString } from "./telemetry";
 10→
 11→interface TokenConfig {
 12→  clientId: string;
 13→  clientSecret: string;
 14→  encryptionKey: string;
 15→}
 16→
 17→interface TokenResult {
 18→  token: string;
 19→  refreshed: boolean;
 20→}
 21→
 22→// Buffer time before expiration to trigger refresh (5 minutes)
 23→const EXPIRATION_BUFFER_MS = 5 * 60 * 1000;
 24→
 25→// GitHub App installation token config
 26→export interface AppTokenConfig {
 27→  appId: string;
 28→  privateKey: string;
 29→}
 30→
 31→// Installation token cache TTL (50 minutes - tokens expire after 1 hour)
 32→const INSTALLATION_TOKEN_CACHE_TTL = 50 * 60;
 33→
 34→/**
 35→ * Base64URL encode a buffer (RFC 4648)
 36→ */
 37→function base64UrlEncode(data: Uint8Array | ArrayBuffer): string {
 38→  const bytes = data instanceof ArrayBuffer ? new Uint8Array(data) : data;
 39→  const base64 = btoa(String.fromCharCode(...bytes));
 40→  return base64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
 41→}
 42→
 43→/**
 44→ * Create a JWT for GitHub App authentication.
 45→ * The JWT is signed with RS256 using the app's private key.
 46→ */
 47→export async function createAppJWT(appId: string, privateKeyPem: string): Promise<string> {
 48→  const now = Math.floor(Date.now() / 1000);
 49→
 50→  // JWT header
 51→  const header = {
 52→    alg: "RS256",
 53→    typ: "JWT",
 54→  };
 55→
 56→  // JWT payload - issued 60 seconds in the past to allow for clock drift
 57→  // Expires in 10 minutes (max allowed by GitHub)
 58→  const payload = {
 59→    iat: now - 60,
 60→    exp: now + 600,
 61→    iss: appId,
 62→  };
 63→
 64→  const encoder = new TextEncoder();
 65→  const headerB64 = base64UrlEncode(encoder.encode(JSON.stringify(header)));
 66→  const payloadB64 = base64UrlEncode(encoder.encode(JSON.stringify(payload)));
 67→  const signingInput = `${headerB64}.${payloadB64}`;
 68→
 69→  // Import the private key for signing
 70→  const key = await importPrivateKey(privateKeyPem);
 71→
 72→  // Sign the JWT
 73→  const signature = await crypto.subtle.sign(
 74→    { name: "RSASSA-PKCS1-v1_5" },
 75→    key,
 76→    encoder.encode(signingInput)
 77→  );
 78→
 79→  const signatureB64 = base64UrlEncode(signature);
 80→
 81→  return `${signingInput}.${signatureB64}`;
 82→}
 83→
 84→/**
 85→ * Import a PEM-encoded RSA private key for use with Web Crypto API.
 86→ */
 87→async function importPrivateKey(pemKey: string): Promise<CryptoKey> {
 88→  // Remove PEM headers and whitespace
 89→  const pemContents = pemKey
 90→    .replace(/REDACTED/, "")
 93→    .replace(/-----END PRIVATE KEY-----/, "")
 94→    .replace(/\s/g, "");
 95→
 96→  // Decode base64 to binary
 97→  const binaryString = atob(pemContents);
 98→  const bytes = new Uint8Array(binaryString.length);
 99→  for (let i = 0; i < binaryString.length; i++) {
100→    bytes[i] = binaryString.charCodeAt(i);
101→  }
102→
103→  // Import as PKCS#8 (PRIVATE KEY) or try PKCS#1 (RSA PRIVATE KEY)
104→  try {
105→    return await crypto.subtle.importKey(
106→      "pkcs8",
107→      bytes,
108→      { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
109→      false,
110→      ["sign"]
111→    );
112→  } catch {
113→    // If PKCS#8 fails, the key might be PKCS#1 format
114→    // PKCS#1 keys need to be wrapped in PKCS#8 format
115→    throw new Error("Failed to import private key. Ensure the key is in PKCS#8 format (BEGIN PRIVATE KEY)");
116→  }
117→}
118→
119→/**
120→ * Get a GitHub App installation access token.
121→ * Uses the app's JWT to authenticate and request a token for the specific installation.
122→ * Tokens are cached in KV for 50 minutes (expire after 1 hour).
123→ *
124→ * @param installationId - The GitHub App installation ID
125→ * @param config - App authentication config (appId and privateKey)
126→ * @param kv - KV namespace for caching tokens
127→ * @returns The installation access token
128→ */
129→export async function getInstallationToken(
130→  installationId: number,
131→  config: AppTokenConfig,
132→  kv?: KVNamespace
133→): Promise<string> {
134→  const cacheKey = `installation_token:${installationId}`;
135→
136→  // Check cache first
137→  if (kv) {
138→    const cached = await kv.get(cacheKey);
139→    if (cached) {
140→      return cached;
141→    }
142→  }
143→
144→  // Create JWT for app authentication
145→  const jwt = await createAppJWT(config.appId, config.privateKey);
146→
147→  // Request installation access token from GitHub
148→  const response = await fetch(
149→    `https://api.github.com/app/installations/${installationId}/access_tokens`,
150→    {
151→      method: "POST",
152→      headers: {
153→        Authorization: `Bearer ${jwt}`,
154→        Accept: "application/vnd.github+json",
155→        "User-Agent": "entire-api",
156→        "X-GitHub-Api-Version": "2022-11-28",
157→      },
158→    }
159→  );
160→
161→  if (!response.ok) {
162→    const errorText = await response.text();
163→    throw new Error(`Failed to get installation token: ${response.status} - ${errorText}`);
164→  }
165→
166→  const data = await response.json<{ token: string; expires_at: string }>();
167→
168→  // Cache the token
169→  if (kv) {
170→    await kv.put(cacheKey, data.token, { expirationTtl: INSTALLATION_TOKEN_CACHE_TTL });
171→  }
172→
173→  return data.token;
174→}
175→
176→/**
177→ * Get a valid GitHub access token, refreshing if expired.
178→ * Returns the decrypted access token ready to use.
179→ *
180→ * @param kv - Optional KV namespace to invalidate user cache on token refresh
181→ */
182→export async function getValidGitHubToken(
183→  db: Db,
184→  user: Pick<User, "id" | "github_token_enc" | "github_refresh_token_enc" | "github_token_expires_at">,
185→  config: TokenConfig,
186→  kv?: KVNamespace
187→): Promise<TokenResult> {
188→  if (!user.github_token_enc) {
189→    throw new Error("User has no GitHub token");
190→  }
191→
192→  const now = Date.now();
193→  const expiresAt = user.github_token_expires_at
194→    ? new Date(user.github_token_expires_at).getTime()
195→    : null;
196→
197→  // Check if token is expired or about to expire
198→  const isExpired = expiresAt && now >= expiresAt - EXPIRATION_BUFFER_MS;
199→
200→  if (!isExpired) {
201→    // Token is still valid
202→    const token = await decrypt(user.github_token_enc, config.encryptionKey);
203→    return { token, refreshed: false };
204→  }
205→
206→  // Token is expired - try to refresh
207→  if (!user.github_refresh_token_enc) {
208→    // No refresh token available - return current token and hope for the best
209→    // User will need to re-authenticate if it fails
210→    console.warn(`Token expired for user ${user.id} but no refresh token available`);
211→    const token = await decrypt(user.github_token_enc, config.encryptionKey);
212→    return { token, refreshed: false };
213→  }
214→
215→  console.log(`Refreshing expired token for user ${user.id}`);
216→
217→  try {
218→    const refreshToken = await decrypt(user.github_refresh_token_enc, config.encryptionKey);
219→
220→    const tokenData = await refreshAccessToken(
221→      refreshToken,
222→      config.clientId,
223→      config.clientSecret
224→    );
225→
226→    // Encrypt new tokens
227→    const encryptedToken = await encrypt(tokenData.access_token, config.encryptionKey);
228→    const encryptedRefreshToken = tokenData.refresh_token
229→      ? await encrypt(tokenData.refresh_token, config.encryptionKey)
230→      : user.github_refresh_token_enc; // Keep old refresh token if not returned
231→
232→    const tokenExpiresAt = tokenData.expires_in
233→      ? new Date(Date.now() + tokenData.expires_in * 1000).toISOString()
234→      : null;
235→
236→    // Update user with new tokens
237→    await db.users.update(user.id, {
238→      github_token_enc: encryptedToken,
239→      github_refresh_token_enc: encryptedRefreshToken,
240→      github_token_expires_at: tokenExpiresAt,
241→    });
242→
243→    // Invalidate user cache so subsequent requests get fresh token data
244→    if (kv) {
245→      await kv.delete(`user:${user.id}`);
246→    }
247→
248→    console.log(`Successfully refreshed token for user ${user.id}`);
249→    return { token: tokenData.access_token, refreshed: true };
250→  } catch (err) {
251→    console.error(`Failed to refresh token for user ${user.id}: ${errorString(err)}`);
252→
253→    // Re-read user from DB - another request may have already refreshed successfully
254→    try {
255→      const freshUser = await db.users.findById(user.id);
256→      if (
257→        freshUser?.github_token_enc &&
258→        freshUser.github_token_enc !== user.github_token_enc
259→      ) {
260→        console.log(`Using token refreshed by concurrent request for user ${user.id}`);
261→        const token = await decrypt(freshUser.github_token_enc, config.encryptionKey);
262→        return { token, refreshed: true };
263→      }
264→    } catch (dbErr) {
265→      console.error(`Failed to re-read user ${user.id} from DB: ${errorString(dbErr)}`);
266→    }
267→
268→    // No concurrent refresh happened (or DB unavailable) - return the old token
269→    const token = await decrypt(user.github_token_enc, config.encryptionKey);
270→    return { token, refreshed: false };
271→  }
272→}
