366→// Reconciliation options
367→export interface ReconciliationOptions {
368→  force?: boolean; // Skip staleness check and queue all repos
369→  repoFullName?: string; // Target a specific repo by full name (e.g., "owner/repo")
370→  repoIds?: string[]; // Target specific repos by ID
371→}
372→
373→// Reconciliation result
374→export interface ReconciliationResult {
375→  reposQueued: number;
376→  usersQueued: number;
377→  targetedRepo?: string; // The repo that was targeted (if any)
378→}
379→
380→// Daily reconciliation cron handler
381→// Queues stale repos for checkpoint sync and identifies stale users
382→export async function handleReconciliationCron(
383→  env: Env,
384→  options: ReconciliationOptions = {},
385→): Promise<ReconciliationResult> {
386→  const now = new Date();
387→  const staleThreshold = new Date(
388→    now.getTime() - 24 * 60 * 60 * 1000,
389→  ).toISOString();
390→  const isTargeted = !!(options.repoFullName || options.repoIds?.length);
391→
392→  log("cron_started", {
393→    threshold: staleThreshold,
394→    force: options.force ?? false,
395→    targeted: isTargeted,
396→    repoFullName: options.repoFullName,
397→    repoIds: options.repoIds,
398→  });
399→
400→  const db = getDb(env);
401→
402→  // A. Queue repos for checkpoint reconciliation
403→  let reposToQueue: { id: string; full_name: string }[];
404→  try {
405→    reposToQueue = await db.repos.getForReconciliation({
406→      repoFullName: options.repoFullName,
407→      repoIds: options.repoIds,
408→      force: options.force,
409→      staleThreshold,
410→    });
411→  } catch (err) {
412→    if (options.repoFullName) {
413→      log("cron_error_repo_not_found", {
414→        repoFullName: options.repoFullName,
415→        error: errorString(err),
416→      });
417→      return { reposQueued: 0, usersQueued: 0, targetedRepo: options.repoFullName };
418→    }
419→    log("cron_error_fetching_repos", { error: errorString(err) });
420→    return { reposQueued: 0, usersQueued: 0 };
421→  }
422→
423→  const reposQueued = await queueRepoSyncBatch(
424→    env.REPO_SYNC_QUEUE,
425→    reposToQueue,
426→    "reconciliation",
427→    1,
428→  );
429→
430→  // B. Queue stale users for repo sync (skip if targeting specific repos)
431→  let usersQueued = 0;
432→  if (!isTargeted) {
433→    try {
434→      const staleUsers = await db.refreshState.getStaleUsers(staleThreshold, 100);
435→      usersQueued = await queueUserRepoSyncBatch(
436→        env.USER_REPO_SYNC_QUEUE,
437→        staleUsers,
438→        "reconciliation",
439→      );
440→    } catch (err) {
441→      log("cron_error_fetching_users", { error: errorString(err) });
442→    }
443→  }
444→
445→  const result: ReconciliationResult = {
446→    reposQueued,
447→    usersQueued,
448→    targetedRepo: options.repoFullName,
449→  };
450→
451→  log("cron_complete", { ...result });
452→
453→  return result;
454→}
