205→// Process a batch of search index messages
206→export async function processSearchIndexBatch(
207→  batch: MessageBatch<SearchIndexMessage>,
208→  env: Env,
209→): Promise<void> {
210→  const batchStartTime = Date.now();
211→  const batchId = generateBatchId();
212→
213→  const queueWaitTimes = batch.messages.map(
214→    (msg) => Date.now() - msg.timestamp.getTime(),
215→  );
216→  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;
217→
218→  log("batch_started", {
219→    batchId,
220→    queue: batch.queue,
221→    count: batch.messages.length,
222→    avgQueueWaitMs: avgMs(queueWaitTimes),
223→    maxQueueWaitMs: maxWaitMs,
224→  });
225→
226→  const processingTimes: number[] = [];
227→  let successCount = 0;
228→  let errorCount = 0;
229→  let skippedCount = 0;
230→
231→  for (const msg of batch.messages) {
232→    const msgStartTime = Date.now();
233→    const { repoId, checkpointIds } = msg.body;
234→
235→    // Early return if API keys are missing — don't retry messages that can never succeed
236→    if (!env.TURBOPUFFER_API_KEY || !env.OPENAI_API_KEY) {
237→      log("skip_missing_api_keys", {
238→        batchId,
239→        repoId,
240→        hasTurbopuffer: !!env.TURBOPUFFER_API_KEY,
241→        hasOpenai: !!env.OPENAI_API_KEY,
242→      });
243→      msg.ack();
244→      skippedCount++;
245→      continue;
246→    }
247→
248→    try {
249→      const db = getDb(env);
250→
251→      const repo = await db.repos.getById(repoId);
252→      if (!repo) {
253→        log("skip_repo_not_found", { batchId, repoId });
254→        msg.ack();
255→        skippedCount++;
256→        continue;
257→      }
258→
259→      const checkpoints = await db.checkpoints.getByIds(repoId, checkpointIds);
260→
261→      if (checkpoints.length === 0) {
262→        log("skip_no_checkpoints", { batchId, repoId, requestedIds: checkpointIds.length });
263→        msg.ack();
264→        skippedCount++;
265→        continue;
266→      }
267→
268→      // Ensure transcripts are stored in DB, fetching from GitHub if needed
269→      // Only runs when ENABLE_TRANSCRIPT_STORAGE is set; otherwise transcripts map is empty
270→      const transcripts = env.ENABLE_TRANSCRIPT_STORAGE
271→        ? await ensureTranscriptsStored(
272→            db,
273→            repoId,
274→            repo.full_name,
275→            repo.installation_id,
276→            checkpoints.map((cp) => ({
277→              checkpoint_id: cp.checkpoint_id,
278→              agent: cp.agent ?? "Claude Code",
279→              session_count: cp.session_count ?? 1,
280→            })),
281→            env,
282→            batchId,
283→          )
284→        : new Map<string, string | null>();
285→
286→      const indexed = await indexCheckpoints(
287→        env.TURBOPUFFER_API_KEY,
288→        env.OPENAI_API_KEY,
289→        repo.github_id,
290→        checkpoints.map((cp) => ({
291→          checkpoint_id: cp.checkpoint_id,
292→          branch: cp.branch,
293→          agent: cp.agent,
294→          commit_author_username: cp.commit_author_username,
295→          created_at: cp.created_at,
296→          commit_sha: cp.commit_sha,
297→          commit_message: cp.commit_message,
298→          prompt: cp.prompt,
299→          files_touched: cp.files_touched,
300→          transcript: transcripts.get(cp.checkpoint_id) ?? null,
301→        })),
302→      );
303→
304→      const processingMs = Date.now() - msgStartTime;
305→      processingTimes.push(processingMs);
306→
307→      log("message_processed", {
308→        batchId,
309→        repoId,
310→        requested: checkpointIds.length,
311→        found: checkpoints.length,
312→        indexed,
313→        processingMs,
314→        attempt: msg.attempts,
315→      });
316→
317→      msg.ack();
318→      successCount++;
319→    } catch (err) {
320→      const processingMs = Date.now() - msgStartTime;
321→      processingTimes.push(processingMs);
322→      errorCount++;
323→
324→      log("message_error", {
325→        batchId,
326→        repoId,
327→        checkpointCount: checkpointIds.length,
328→        attempt: msg.attempts,
329→        processingMs,
330→        error: err instanceof Error ? err.message : String(err),
331→      });
332→
333→      // Retry on transient failures (max_retries configured in wrangler.jsonc)
334→      msg.retry();
335→    }
336→  }
337→
338→  const totalBatchTimeMs = Date.now() - batchStartTime;
339→
340→  log("batch_complete", {
341→    batchId,
342→    count: batch.messages.length,
343→    successCount,
344→    errorCount,
345→    skippedCount,
346→    totalBatchTimeMs,
347→    avgProcessingMs: avgMs(processingTimes),
348→    throughputPerMin:
349→      totalBatchTimeMs > 0
350→        ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
351→        : 0,
352→  });
353→}
