218→export async function resolveCheckpoint(
219→  org: string,
220→  repo: string,
221→  checkpointId: string,
222→  requestedBranch?: string,
223→): Promise<CheckpointResolveResponse> {
224→  const params = requestedBranch
225→    ? `?branch=${encodeURIComponent(requestedBranch)}`
226→    : "";
227→  return request<CheckpointResolveResponse>(
228→    `/api/v1/cache/${org}/${repo}/checkpoints/resolve/${encodeURIComponent(checkpointId)}${params}`
229→  );
230→}
