232→export interface SearchMeta {
233→  matchType: "semantic" | "keyword" | "both";
234→  score: number;
235→}
236→
237→export interface SearchCheckpointsResponse extends CheckpointsResponse {
238→  searchMeta?: Record<string, SearchMeta>;
239→}
240→
241→export async function searchCheckpoints(
242→  org: string,
243→  repo: string,
244→  query: string,
245→  branch?: string,
246→): Promise<SearchCheckpointsResponse> {
247→  const params = new URLSearchParams({ q: query });
248→  if (branch) params.set("branch", branch);
249→  return request<SearchCheckpointsResponse>(
250→    `/api/v1/cache/${org}/${repo}/checkpoints/search?${params.toString()}`
251→  );
252→}
