// Webhook event processing functions
// Used by the queue worker to process GitHub webhook events

import { trace } from "@opentelemetry/api";
import type { Env } from "../../env";
import type { Json } from "../../types/database";
import type { Db } from "../db/db-types";
import { type WebhookRepoData } from "../db/repos";
import {
  type CheckpointWebhookData,
  type CommitWebhookData,
} from "../db/checkpoints";
import { type WebhookPRData } from "../db/prs";
import { queueUserRepoSync, queueUserRepoSyncBatch } from "../user-repo-sync";
import { parseTrailers, extractCheckpointIds, parseSquashCommitTitles, fetchSessionDataBatch, type BatchResult, type SessionData, fetchCommitStatsBatch, discoverTrailsFromBranch, fetchTrailMetadataAndCheckpointsBatch, updateTrailCheckpoints, updateTrailMetadata, isBranchMergedInto } from "../github";
import { buildTranscriptCacheKey } from "../kv";
import { CHECKPOINT_BRANCH, TRAILS_BRANCH } from "../constants";
import { getInstallationToken } from "../token";
import { queueRepoSyncBatch, syncRepoTrails } from "../repo-sync-service";
import { traced } from "../telemetry";
import { createMirrorRepo } from "../darwin";
import type { SearchIndexMessage } from "../search-index-queue";

// Relevant webhook events that affect repository data
const RELEVANT_EVENTS = new Set([
  "push",
  "repository",
  "star",
  "fork",
  "delete",
  "create",
  "pull_request",
]);

// Installation events that trigger a full repo sync
const INSTALLATION_EVENTS = new Set([
  "installation",
  "installation_repositories",
]);

// Convert a timestamp to ISO 8601 string
// GitHub webhooks send pushed_at as Unix timestamp (number), but API returns ISO string
function toISOString(value: unknown): string | null {
  if (value === null || value === undefined) {
    return null;
  }
  if (typeof value === "number") {
    return new Date(value * 1000).toISOString();
  }
  if (typeof value === "string") {
    return value;
  }
  return null;
}

/**
 * Validate that installation exists in database before processing webhook.
 * Returns null if no installation ID in payload (caller should skip processing).
 * Throws if installation ID exists but not found in DB (to trigger retry queue).
 * Returns the validated installation ID on success.
 */
async function validateInstallation(
  payload: Record<string, unknown>,
  db: Db,
  context: string
): Promise<number | null> {
  const installation = payload.installation as { id?: number } | undefined;
  if (!installation?.id) {
    return null;
  }

  const exists = await db.installations.existsByGitHubId(installation.id);
  if (!exists) {
    throw new Error(`${context}: installation ${installation.id} not found in database`);
  }

  return installation.id;
}

// Extract repository data from webhook payload
function extractRepoData(payload: Record<string, unknown>): WebhookRepoData | null {
  const repo = payload.repository as Record<string, unknown> | undefined;
  if (!repo || typeof repo.full_name !== "string" || typeof repo.id !== "number") {
    return null;
  }

  return {
    github_id: repo.id as number,
    full_name: repo.full_name as string,
    name: repo.name as string | undefined,
    description: repo.description as string | null | undefined,
    html_url: repo.html_url as string | undefined,
    language: repo.language as string | null | undefined,
    stargazers_count: repo.stargazers_count as number | undefined,
    private: repo.private as boolean | undefined,
    pushed_at: toISOString(repo.pushed_at) ?? toISOString(repo.updated_at),
  };
}

// Unified webhook processor - calls all webhook handlers
// Used by the queue worker to ensure consistent processing
export async function processAllWebhookEvents(
  eventType: string,
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  cache: KVNamespace,
  env?: Env
): Promise<void> {
  // Mirror repo to Darwin (fire-and-forget, non-blocking)
  if (env) {
    const installation = payload.installation as Record<string, unknown> | undefined;
    const repo = payload.repository as Record<string, unknown> | undefined;
    if (installation?.id && repo?.full_name) {
      const [owner, repoName] = (repo.full_name as string).split("/");
      traced("createMirrorRepo", () =>
        createMirrorRepo(env, owner, repoName, installation.id as number)
      ).catch((err) => console.error(`[webhook] createMirrorRepo failed for ${repo.full_name}:`, err));
    }
  }

  // Process standard repo events
  await traced("processWebhookEvent", () =>
    processWebhookEvent(eventType, action, payload, db, cache)
  );

  // Process installation events (invalidate caches + queue checkpoint sync)
  await traced("processInstallationEvent", () =>
    processInstallationEvent(eventType, action, payload, db, cache, env)
  );

  // Process access-change events (queue user repo sync)
  await traced("processAccessChangeEvent", () =>
    processAccessChangeEvent(eventType, action, payload, db, cache, env)
  );

  // Process pull request events (invalidate PR cache)
  await traced("processPullRequestEvent", () =>
    processPullRequestEvent(eventType, action, payload, db)
  );

  // Process checkpoint webhooks and trail merge detection (handlers check ref internally)
  if (env) {
    await Promise.all([
      traced("processSessionsPushEvent", () =>
        processSessionsPushEvent(eventType, payload, db, env)
      ),
      traced("processCommitPushEvent", () =>
        processCommitPushEvent(eventType, payload, db, env)
      ),
      traced("processTrailsPushEvent", () =>
        processTrailsPushEvent(eventType, payload, db, env)
      ),
      traced("processTrailMergeDetection", () =>
        processTrailMergeDetection(eventType, payload, db, env)
      ),
    ]);
  }
}

// Process webhook event to update DB directly and notify affected users
export async function processWebhookEvent(
  eventType: string,
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  cache: KVNamespace
): Promise<void> {
  // Only process relevant events
  if (!RELEVANT_EVENTS.has(eventType)) {
    return;
  }

  // Validate installation exists before processing
  // This prevents unauthorized data modification from compromised webhook secrets
  const installationId = await validateInstallation(payload, db, `Webhook ${eventType}`);
  if (installationId === null) {
    console.log(`Webhook ${eventType}: no installation ID in payload, skipping`);
    return;
  }

  const repoData = extractRepoData(payload);
  if (!repoData) {
    console.log(`Webhook ${eventType}: no repository data, skipping`);
    return;
  }

  const repoGithubId = repoData.github_id;
  const repoFullName = repoData.full_name;

  // Invalidate branches cache when a branch is created or deleted
  // GitHub's create/delete events include ref_type ("branch" or "tag") and ref (the name)
  if ((eventType === "create" || eventType === "delete") && payload.ref_type === "branch") {
    await cache.delete(`branches:${repoFullName}`);
    console.log(`Webhook ${eventType}/branch: invalidated branches cache for ${repoFullName}`);
  }

  // Find all users who have this repo synced (by stable GitHub ID)
  const userIds = await db.repos.getUsersByRepoGithubId(repoGithubId);

  if (userIds.length === 0) {
    console.log(`Webhook ${eventType} for ${repoFullName}: no affected users`);
    return;
  }

  // Handle different event types
  let dbChanges = 0;

  if (eventType === "repository" && action === "deleted") {
    // Repository was deleted - remove from DB (by stable GitHub ID)
    dbChanges = await db.repos.deleteByGithubId(repoGithubId);
    console.log(`Webhook repository/deleted for ${repoFullName}: removed ${dbChanges} row(s)`);
  } else {
    // For all other events, update the repository with the latest data
    // This also handles renames by updating full_name via github_id lookup
    dbChanges = await db.repos.updateFromWebhook(repoGithubId, repoData);
    console.log(
      `Webhook ${eventType}/${action || "n/a"} for ${repoFullName}: updated ${dbChanges} row(s)`
    );

    // For push events, increment the weekly activity counter
    if (eventType === "push") {
      const activityUpdated = await db.repos.incrementActivity(repoGithubId);
      console.log(
        `Push event for ${repoFullName}: incremented activity for ${activityUpdated} repo record(s)`
      );
    }
  }

  // Update sync timestamp for each affected user so frontend knows to refresh
  const now = Date.now();
  await Promise.all(
    userIds.map((userId) =>
      cache.put(`sync:lastUpdate:${userId}`, String(now), {
        expirationTtl: 60 * 60 * 24 * 7, // 7 days
      })
    )
  );

  console.log(
    `Webhook ${eventType}/${action || "n/a"} for ${repoFullName}: notified ${userIds.length} user(s)`
  );
}

// Process installation webhook event - update app_has_access, invalidate caches, and queue checkpoint sync
// NOTE: We don't do full repo sync here to avoid timeouts. We queue repos for background sync.
// This now handles multi-user installations (e.g., org installations accessible by multiple users).
export async function processInstallationEvent(
  eventType: string,
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  cache: KVNamespace,
  env?: Env
): Promise<void> {
  // Only process installation events
  if (!INSTALLATION_EVENTS.has(eventType)) {
    return;
  }

  const installation = payload.installation as Record<string, unknown> | undefined;
  if (!installation?.id) {
    console.log(`Installation event ${eventType}/${action}: no installation.id, skipping`);
    return;
  }

  const githubInstallationId = installation.id as number;
  console.log(`Processing installation event ${eventType}/${action} for installation ${githubInstallationId}`);

  // Find all users linked to this installation
  const users = await db.installations.findUsersByGitHubId(githubInstallationId);

  // Handle installation.created - create the installation record and process repos
  if (eventType === "installation" && action === "created") {
    const account = installation.account as Record<string, unknown> | undefined;
    if (!account) {
      // No account data - can't create installation record, skip processing
      console.warn(`Installation ${githubInstallationId}: missing account data, skipping`);
      return;
    }

    const accountId = account.id as number | undefined;
    const accountLogin = account.login as string | undefined;
    const accountType = account.type as string | undefined;

    // Log warning if account data is incomplete (but still create the record)
    if (!accountId || !accountLogin) {
      console.warn(`Installation ${githubInstallationId}: incomplete account data - id: ${accountId}, login: ${accountLogin}`);
    }

    const installationUuid = await db.installations.upsert({
      github_installation_id: githubInstallationId,
      account_login: accountLogin ?? "unknown",
      account_type: accountType ?? "User",
      account_id: accountId ?? 0,
      app_slug: (installation.app_slug as string) ?? null,
      suspended_at: null,
    });
    console.log(`Installation ${githubInstallationId}: created in DB`);

    // Process repos for this new installation - upsert with app_has_access and queue for sync
    // Note: No users are linked yet (they link on OAuth), so we just set up the repos
    const repos = (payload.repositories as Array<{ id: number; full_name: string; private?: boolean; default_branch?: string }>) || [];
    const queueAvailable = !!env?.REPO_SYNC_QUEUE;

    // Batch upsert all repos
    const repoIds = await db.repos.upsertBatch(
      repos.map((repo) => ({
        github_id: repo.id,
        full_name: repo.full_name,
        app_has_access: true,
        installation_id: installationUuid,
        default_branch: repo.default_branch,
        is_private: repo.private,
      }))
    );

    // Queue all for checkpoint backfill (user links created on OAuth callback)
    if (queueAvailable) {
      await queueRepoSyncBatch(
        env!.REPO_SYNC_QUEUE,
        repoIds.map((id) => ({ id })),
        "installation",
        10
      );
      console.log(`Installation created: ${repos.length} repos queued for sync`);
    } else {
      console.log(`Installation created: ${repos.length} repos upserted`);
    }
    return; // Done processing installation.created
  }

  // Handle installation.deleted - remove from installations table (CASCADE handles links)
  if (eventType === "installation" && action === "deleted") {
    const deleted = await db.installations.deleteByGitHubId(githubInstallationId);
    if (deleted) {
      console.log(`Installation ${githubInstallationId}: deleted from DB (links removed by CASCADE)`);
    }
    // Note: app_has_access will be reset on next refresh-app-access run
    // Invalidate cache for all affected users
    const now = Date.now();
    await Promise.all(
      users.map((user) =>
        cache.put(`sync:lastUpdate:${user.id}`, String(now), {
          expirationTtl: 60 * 60 * 24 * 7,
        })
      )
    );
    return;
  }

  // Handle repos added/removed - always update app_has_access, only link to users if they exist
  if (eventType === "installation_repositories") {
    const reposAdded = (payload.repositories_added as Array<{ id: number; full_name: string; private?: boolean; default_branch?: string }>) || [];
    const reposRemoved = (payload.repositories_removed as Array<{ id: number; full_name: string }>) || [];
    const queueAvailable = !!env?.REPO_SYNC_QUEUE;

    // Look up installation UUID for linking repos
    const installationUuid = await db.installations.findIdByGitHubId(githubInstallationId);

    // Batch upsert added repos
    const repoIds = await db.repos.upsertBatch(
      reposAdded.map((repo) => ({
        github_id: repo.id,
        full_name: repo.full_name,
        app_has_access: true,
        installation_id: installationUuid,
        default_branch: repo.default_branch,
        is_private: repo.private,
      }))
    );

    // Link repos to ALL users who have access via this installation (if any)
    await db.repos.addUserReposBatch(users.map((u) => u.id), repoIds);

    // Queue all for checkpoint backfill
    if (queueAvailable) {
      await queueRepoSyncBatch(
        env!.REPO_SYNC_QUEUE,
        repoIds.map((id) => ({ id })),
        "installation",
        10
      );
    }

    // Process removed repos - update access flag
    for (const repo of reposRemoved) {
      await db.repos.updateAppAccessByFullName(repo.full_name, false);
    }

    if (queueAvailable) {
      console.log(`Installation repos updated: +${reposAdded.length} queued (linked to ${users.length} users), -${reposRemoved.length} removed`);
    } else {
      console.log(`Installation repos updated: +${reposAdded.length} upserted (linked to ${users.length} users), -${reposRemoved.length} removed`);
    }
    return;
  }

  // For other events, skip if no users linked
  if (users.length === 0) {
    console.log(`Installation ${githubInstallationId}: no users found (not onboarded yet), skipping`);
    return;
  }

  // Invalidate sync timestamp for all affected users
  const now = Date.now();
  await Promise.all(
    users.map((user) =>
      cache.put(`sync:lastUpdate:${user.id}`, String(now), {
        expirationTtl: 60 * 60 * 24 * 7, // 7 days
      })
    )
  );

  const userLogins = users.map((u) => u.github_login).filter(Boolean).join(", ");
  console.log(`Installation ${eventType}/${action} for users [${userLogins}]: cache invalidated`);
}

// Relevant actions per access-change event type
const ACCESS_CHANGE_ACTIONS: Record<string, Set<string>> = {
  member: new Set(["added", "removed", "edited"]),
  membership: new Set(["added", "removed"]),
  organization: new Set(["member_added", "member_removed"]),
  team: new Set(["added_to_repository", "removed_from_repository"]),
  repository: new Set(["created"]),
};

// Process access-change webhook events
// Optimized handlers for repository.created and member.added/removed use direct DB operations
// Other events (team, membership, organization) queue full syncs
export async function processAccessChangeEvent(
  eventType: string,
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  cache: KVNamespace,
  env?: Env
): Promise<void> {
  // Gate on relevant action
  const relevantActions = ACCESS_CHANGE_ACTIONS[eventType];
  if (!action || !relevantActions?.has(action)) {
    return;
  }

  // Handle repository.created with direct DB operations (no API calls needed)
  if (eventType === "repository" && action === "created") {
    await handleRepositoryCreated(payload, db, cache, env);
    return;
  }

  // Handle member events - added/removed use direct DB, edited queues sync
  if (eventType === "member") {
    await handleMemberEvent(action, payload, db, cache, env);
    return;
  }

  // membership events always queue full sync (team membership changes)
  if (eventType === "membership") {
    await handleMembershipEvent(action, payload, db, cache, env);
    return;
  }

  // organization events always queue full sync
  if (eventType === "organization") {
    await handleOrganizationEvent(action, payload, db, cache, env);
    return;
  }

  // team events always queue full sync (we don't have team membership data)
  if (eventType === "team") {
    await handleTeamEvent(action, payload, db, cache, env);
    return;
  }
}

// Handle repository.created - directly upsert repo and link to all installation users
async function handleRepositoryCreated(
  payload: Record<string, unknown>,
  db: Db,
  cache: KVNamespace,
  env?: Env
): Promise<void> {
  const installation = payload.installation as { id?: number } | undefined;
  if (!installation?.id) {
    console.log("Access change repository/created: no installation.id, skipping");
    return;
  }

  const repository = payload.repository as { id?: number; full_name?: string; name?: string; description?: string | null; html_url?: string; language?: string | null; private?: boolean; default_branch?: string } | undefined;
  if (!repository?.id || !repository?.full_name) {
    console.log("Access change repository/created: no repository data, skipping");
    return;
  }

  // Look up installation UUID by GitHub installation ID
  const installationUuid = await db.installations.findIdByGitHubId(installation.id);

  if (!installationUuid) {
    console.log(`Access change repository/created: installation ${installation.id} not found in DB, skipping`);
    return;
  }

  // Find users linked to this installation
  const users = await db.installations.findUsersByGitHubId(installation.id);

  // Upsert the repo with app_has_access=true
  const repoIds = await db.repos.upsertBatch([{
    github_id: repository.id,
    full_name: repository.full_name,
    app_has_access: true,
    installation_id: installationUuid,
    default_branch: repository.default_branch,
    is_private: repository.private,
  }]);

  if (repoIds.length === 0) {
    console.log(`Access change repository/created: failed to upsert repo ${repository.full_name}`);
    return;
  }

  const repoId = repoIds[0];

  // Link all installation users to the new repo
  if (users.length > 0) {
    await db.repos.addUserReposBatch(users.map((u) => u.id), [repoId]);
  }

  // Queue checkpoint sync for the new repo
  if (env?.REPO_SYNC_QUEUE) {
    await queueRepoSyncBatch(env.REPO_SYNC_QUEUE, [{ id: repoId }], "installation", 10);
  }

  // Invalidate user caches
  if (users.length > 0) {
    const now = Date.now();
    await Promise.all(
      users.map((user) =>
        cache.put(`sync:lastUpdate:${user.id}`, String(now), {
          expirationTtl: 60 * 60 * 24 * 7,
        })
      )
    );
  }

  console.log(`Access change repository/created: upserted ${repository.full_name}, linked to ${users.length} user(s)`);
}

// Handle member events - added/removed use direct DB operations, edited queues sync
async function handleMemberEvent(
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  cache: KVNamespace,
  env?: Env
): Promise<void> {
  const member = payload.member as { id?: number } | undefined;
  if (!member?.id) {
    console.log(`Access change member/${action}: no member.id, skipping`);
    return;
  }

  const user = await db.users.findByGitHubId(member.id);
  if (!user) {
    console.log(`Access change member/${action}: user not found for GitHub ID ${member.id}, skipping`);
    return;
  }

  const repository = payload.repository as { id?: number; full_name?: string } | undefined;

  // For member.added - try direct DB link, fallback to full sync if repo doesn't exist
  if (action === "added") {
    if (repository?.id) {
      const repo = await db.repos.getByGithubId(repository.id);
      if (repo) {
        // Repo exists - add direct link
        await db.repos.addUserRepo(user.id, repo.id);
        const now = Date.now();
        await cache.put(`sync:lastUpdate:${user.id}`, String(now), {
          expirationTtl: 60 * 60 * 24 * 7,
        });
        console.log(`Access change member/added: linked user ${user.id} to repo ${repo.full_name}`);
        return;
      }
    }
    // Repo doesn't exist in our DB - fall back to full sync
    if (env?.USER_REPO_SYNC_QUEUE) {
      await queueUserRepoSync(env.USER_REPO_SYNC_QUEUE, user.id, "access_change");
      const now = Date.now();
      await cache.put(`sync:lastUpdate:${user.id}`, String(now), {
        expirationTtl: 60 * 60 * 24 * 7,
      });
      console.log(`Access change member/added: queued sync for user ${user.id} (repo not in DB)`);
    }
    return;
  }

  // For member.removed - remove direct DB link
  if (action === "removed") {
    if (repository?.id) {
      const repo = await db.repos.getByGithubId(repository.id);
      if (repo) {
        await db.repos.removeUserRepo(user.id, repo.id);
        const now = Date.now();
        await cache.put(`sync:lastUpdate:${user.id}`, String(now), {
          expirationTtl: 60 * 60 * 24 * 7,
        });
        console.log(`Access change member/removed: unlinked user ${user.id} from repo ${repo.full_name}`);
        return;
      }
    }
    // Even if repo doesn't exist, invalidate cache
    const now = Date.now();
    await cache.put(`sync:lastUpdate:${user.id}`, String(now), {
      expirationTtl: 60 * 60 * 24 * 7,
    });
    console.log(`Access change member/removed: cache invalidated for user ${user.id}`);
    return;
  }

  // For member.edited (permission changes) - queue full sync to reconcile
  if (action === "edited") {
    if (!env?.USER_REPO_SYNC_QUEUE) {
      console.log("Access change member/edited: no USER_REPO_SYNC_QUEUE, skipping");
      return;
    }
    await queueUserRepoSync(env.USER_REPO_SYNC_QUEUE, user.id, "access_change");
    const now = Date.now();
    await cache.put(`sync:lastUpdate:${user.id}`, String(now), {
      expirationTtl: 60 * 60 * 24 * 7,
    });
    console.log(`Access change member/edited: queued sync for user ${user.id}`);
  }
}

// Handle membership events (team membership) - always queue full sync
async function handleMembershipEvent(
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
