// Handle team events (added_to_repository/removed_from_repository) - always queue full sync
// We don't have team membership data, so we can't determine which users are affected
async function handleTeamEvent(
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  cache: KVNamespace,
  env?: Env
): Promise<void> {
  if (!env?.USER_REPO_SYNC_QUEUE) {
    console.log(`Access change team/${action}: no USER_REPO_SYNC_QUEUE, skipping`);
    return;
  }

  const installation = payload.installation as { id?: number } | undefined;
  if (!installation?.id) {
    console.log(`Access change team/${action}: no installation.id, skipping`);
    return;
  }

  const users = await db.installations.findUsersByGitHubId(installation.id);
  if (users.length === 0) {
    console.log(`Access change team/${action}: no users for installation ${installation.id}, skipping`);
    return;
  }

  const queued = await queueUserRepoSyncBatch(env.USER_REPO_SYNC_QUEUE, users, "access_change");
