// Debounce search query for API calls
const [debouncedQuery, setDebouncedQuery] = useState("");
useEffect(() => {
  const timer = setTimeout(() => setDebouncedQuery(searchQuery.trim()), 300);
  return () => clearTimeout(timer);
}, [searchQuery]);

const { user } = useAuth();
const isAdminUser = !!user?.is_admin;

// Admin users: server-side Turbopuffer hybrid search
const { data: searchData, isFetching: isSearching } = useSearchCheckpointsQuery(
  org, repo, isAdminUser ? debouncedQuery : "", branch,
);

const isSearchActive = debouncedQuery.length > 0;
const allCheckpoints = useMemo(() => data?.checkpoints ?? [], [data?.checkpoints]);

// Non-admin users: client-side filtering on prompt/commit message/author
const clientFilteredCheckpoints = useMemo(() => {
  if (!isSearchActive || isAdminUser) return allCheckpoints;
  const query = debouncedQuery.toLowerCase();
  return allCheckpoints.filter((cp) => {
    const prompt = cp.sessions?.[0]?.prompt?.trim();
    const displayedTitle = (
      prompt && prompt.length > 0 ? prompt : (cp.commitMessage ?? "")
    ).toLowerCase();
    const author = cp.commitAuthorUsername?.toLowerCase() ?? "";
    return displayedTitle.includes(query) || author.includes(query);
  });
}, [allCheckpoints, debouncedQuery, isSearchActive, isAdminUser]);

const checkpoints = isSearchActive
  ? (isAdminUser ? (searchData?.checkpoints ?? []) : clientFilteredCheckpoints)
  : allCheckpoints;

