describe("checkpointIdToNumeric", () => {
  it("parses 12-hex-char checkpoint ID to correct number", () => {
    expect(checkpointIdToNumeric("abc123def456")).toBe(0xabc123def456);
  });

  it("is deterministic", () => {
    const a = checkpointIdToNumeric("abc123def456");
    const b = checkpointIdToNumeric("abc123def456");
    expect(a).toBe(b);
  });

  it("produces different IDs for different inputs", () => {
    const a = checkpointIdToNumeric("abc123def456");
    const b = checkpointIdToNumeric("abc123def457");
    expect(a).not.toBe(b);
  });

  it("stays within Number.MAX_SAFE_INTEGER", () => {
    // Max 12-hex-char value: ffffffffffff = 281474976710655
    expect(checkpointIdToNumeric("ffffffffffff")).toBeLessThanOrEqual(Number.MAX_SAFE_INTEGER);
  });
});

